(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,465251,(e,a,o)=>{a.exports=JSON.parse('{"nameplate.???":"???","nameplate.Dark Figure":"Figura Oscura","nameplate.Eerie Voice":"Voz inquietante","nameplate.Elder Grah":"Elder Grah","nameplate.Eriole":"Eriole","nameplate.Grahdens":"Grahdens","nameplate.Kar & Seria":"Kar & Seria","nameplate.Karl":"Karl","nameplate.Lin":"Lin","nameplate.Lugina":"Lugina","nameplate.Man\'s Voice":"Voz de hombre","nameplate.Mare":"Mare","nameplate.Mysterious Man":"Hombre Misterioso","nameplate.Mysterious Woman":"Mujer Misteriosa","nameplate.Paris":"Paris","nameplate.Seria":"Seria","nameplate.Seria & Karl":"Seria & Karl","nameplate.Seria & Lugina":"Seria & Lugina","nameplate.Seria・Lugina":"Seria・Lugina","nameplate.Tilith":"Tilith","nameplate.Tilith & Seria":"Tilith & Seria","nameplate.Woman\'s Voice":"Voz de mujer","nameplate.Zebra":"Zebra","nameplate.静かな男の声":"Voz de hombre sereno","story.map1-dungeon0-1end.001":"¡Ya puedes obtener materiales en la <color=00FF00>Granja</color> de Village of the Venturer!","story.map1-dungeon0-2end.001":"¡Ya puedes obtener materiales en la <color=00FF00>Montaña</color> de Village of the Venturer!","story.map1-dungeon0-3end.001":"¡Ya puedes acceder a la <color=00FF00>Casa de esferas</color> de Village of the Venturer!","story.map1-dungeon0-3end.002":"En la Casa de esferas puedes usar materiales para forjar <color=00FFFF>esferas</color> y equipárselas a tus unidades.","story.map1-dungeon0-3end.003":"¡Forja esferas poderosas para aumentar la fuerza de tus unidades!","story.map1-dungeon1.001":"<size=13>¡Qué calor! <wait=40>¡Quiero irme a casa! <wait=40>Esto es insoportable...","story.map1-dungeon1.002":"<size=20>¡Oh! <wait=20>¡<rep_handlename>!","story.map1-dungeon1.003":"¡Oye, llegas tarde! <wait=40>¡¿Qué estabas haciendo?!","story.map1-dungeon1.004":"¡¿Cómo te atreves a hacerme esperar en esta cueva tan calurosa?!","story.map1-dungeon1.005":"Empiezo a preocuparme por nuestro viaje...","story.map1-dungeon1.006":"Bueno, <wait=40>te prometí que te contaría qué está pasando exactamente...","story.map1-dungeon1.007":"Esto es serio, así que escucha bien, ¿vale?","story.map1-dungeon1.008":"Grand Gaia está sumida en una gran crisis...","story.map1-dungeon1.009":"El motivo es que algunos de los poderosos dioses que velan por nosotros han sido consumidos por el mal.","story.map1-dungeon1.010":"Desafiando al Sagrado Emperador Karna Masta, <wait=19>ahora siembran el caos.","story.map1-dungeon1.011":"Entre estas fuerzas malignas, <wait=40>los pocos que poseen los poderes más excepcionales son conocidos como...","story.map1-dungeon1.012":".<wait=10>.<wait=10>.<wait=10>los Cuatro Dioses Caídos.","story.map1-dungeon1.013":"Antes eran dioses de alto rango...","story.map1-dungeon1.014":"...<wait=20>Pero ahora intentan quedarse con Grand Gaia.","story.map1-dungeon1.015":"Los Cuatro Dioses Caídos no solo han sometido a monstruos y espíritus,","story.map1-dungeon1.016":"...sino que también han usado sus poderes para invocar y manipular a los héroes legendarios de Grand Gaia.","story.map1-dungeon1.017":"Si no los detenemos, <wait=40>Grand Gaia será destruida...","story.map1-dungeon1.018":"Ni siquiera el Sagrado Emperador Karna Masta junto con los demás dioses...","story.map1-dungeon1.019":"...<wait=20>podrán contenerlos por mucho tiempo.","story.map1-dungeon1.020":"Por eso Lord Lucius abrió la Puerta que conduce a este mundo.","story.map1-dungeon1.021":"Busca tomar prestado tu poder.","story.map1-dungeon1.022":"Por eso solo los elegidos pueden ver la puerta.","story.map1-dungeon1.023":"Lord Lucius tiene grandes esperanzas puestas en ti.","story.map1-dungeon1.024":"¡Así que espero que no nos decepciones, <wait=20><rep_handlename>!","story.map1-dungeon1.025":"Dicho esto, <wait=40>tu primer objetivo será uno de los Cuatro Dioses Caídos...","story.map1-dungeon1.026":"¡La Diosa de la Creación, <wait=20>Maxwell!","story.map1-dungeon1.027":"Maxwell <wait=20>se ha apoderado de St. Lamia. Antes era una tierra sagrada; ahora es su bastión.","story.map1-dungeon1.028":"Desde aquí, en Mistral, <wait=40>tendrás que ir más allá de Morgan para llegar.","story.map1-dungeon1.029":"Es un camino muy largo, <wait=40>¡pero seguro que lo harás bien!","story.map1-dungeon1.030":"¡Vayamos paso a paso hasta que le pilles el truco a eso de ser Invocador!","story.map1-dungeon1.031":"Primero, para llegar a Morgan tendremos que dirigirnos a la Torre de Mistral.","story.map1-dungeon1.032":"Para ello, <wait=20>tendremos que atravesar la Cueva de las Llamas.","story.map1-dungeon1.033":"Dicen <wait=20>que esta cueva está infestada de bestias feroces.","story.map1-dungeon1.034":"Aun así, <wait=20>¡tú no tendrás problemas!","story.map1-dungeon1.035":"<size=20>¡Agh! <wait=40>¡No aguanto más este calor!","story.map1-dungeon1.036":"Me vuelvo a darme una ducha. ¡Cuídate y sigue adelante!","story.map1-dungeon2.001":"...Brr <wait=60><size=24>...¡Brr!","story.map1-dungeon2.002":"<size=36>¡¡Achís!!","story.map1-dungeon2.003":"...Ay, madre,<wait=30> ¡qué frío!","story.map1-dungeon2.004":"¡Oye! <wait=40>¡¿Cómo te atreves a hacer esperar a una chica en un sitio tan frío?!","story.map1-dungeon2.005":"Brr... <wait=30>¡¡qué frío hace!!","story.map1-dungeon2.006":"Bueno, <wait=20>para llegar a la Torre de Mistral <wait=40>tendrás que cruzar el Campo Nevado de Egor y atravesar el bosque...","story.map1-dungeon2.007":"Después, cruzar el pantano <wait=30>y luego las ruinas...","story.map1-dungeon2.008":"Solo de imaginarlo ya parece lejísimos, <wait=40>¡y eso sin contar lo extremo que puede ser el clima!","story.map1-dungeon2.009":"En fin, <wait=20>todavía te queda mucho camino hasta la torre.","story.map1-dungeon2.010":"Pero ten cuidado. <wait=20>Los enemigos se vuelven más fuertes cuanto más te acercas.","story.map1-dungeon2.011":"Si te encuentras con un enemigo que no puedes derrotar, <wait=20>quizá sea buena idea volver a la mazmorra anterior y entrenar un poco.","story.map1-dungeon2.012":"Ah, sí, <wait=20>ya va siendo hora de que organices tu escuadrón teniendo en cuenta los elementos.","story.map1-dungeon2.013":"¡Casi todos los enemigos de la cueva eran de elemento fuego, así que un escuadrón de unidades de agua te habría dado una gran ventaja!","story.map1-dungeon2.014":"Esta vez estamos en un campo nevado. <wait=40>Creo que veremos muchos enemigos de agua por aquí.","story.map1-dungeon2.015":"Así que... <wait=20>¡pregunta sorpresa! <wait=40>¿Qué elemento es fuerte contra el agua?","story.map1-dungeon2.016":"¡Sí, <wait=40>correcto!","story.map1-dungeon2.017":"Parece que has estado estudiando. <wait=40>Sí, el trueno vence al agua.","story.map1-dungeon2.018":"En cambio, las unidades de fuego estarán en desventaja contra los enemigos del campo nevado, así que ten cuidado.","story.map1-dungeon2.019":"...Brr <wait=60><size=24>...¡Brr!","story.map1-dungeon2.020":"<size=36>¡¡Achís!!","story.map1-dungeon2.021":"Uf, <wait=20>no puedo más. <wait=40>¡Me voy a casa!","story.map1-dungeon2.022":"...Ah, <wait=20>casi se me olvida.","story.map1-dungeon2.023":"Parece que un caballero invocado por Maxwell está sembrando el caos cerca del final de este campo nevado.","story.map1-dungeon2.024":"Dicen que es bastante fuerte. ¡Ten cuidado!","story.map1-dungeon3.001":"¡Oh, <wait=20><rep_handlename>! <wait=40>Bien hecho al cruzar el campo nevado.","story.map1-dungeon3.002":"Mmm, <wait=40>tengo que admitir que ahora pareces mucho más digno que cuando nos conocimos.","story.map1-dungeon3.003":"Muy bien, <wait=20>¡hora de atravesar el Bosque de Bestias!","story.map1-dungeon3.004":"Como su nombre indica, este bosque está infestado de bestias salvajes...","story.map1-dungeon3.005":"Pero tu verdadero enemigo <wait=20>es quien anda cazándolas.","story.map1-dungeon3.006":"Ah, <wait=40>¿y te has equipado una esfera?","story.map1-dungeon3.007":"Puedes mejorar las habilidades de tus unidades equipándoles esferas.","story.map1-dungeon3.008":"Como Invocador, tienes que saberlo si quieres sobrevivir mucho tiempo.","story.map1-dungeon3.009":"Puedes forjar esferas en la Casa de esferas de tu mundo.","story.map1-dungeon3.010":"¡Equipa esferas a tus unidades para crear un escuadrón más fuerte!","story.map1-dungeon3.011":"Para crear esferas hacen falta ciertos materiales que primero tienes que reunir.","story.map1-dungeon3.012":"Bueno, en fin, <wait=20>¡suerte y lucha con todo!<br>","story.map1-dungeon4.001":"<size=18>¡¡Agh, <wait=20>esto es horrible!! ¡¿Qué es esta humedad tan loca?!","story.map1-dungeon4.002":"¡¡Tengo el pelo y la ropa pegajosos y asquerosos!!","story.map1-dungeon4.003":"Ah... <wait=20><rep_handlename>.","story.map1-dungeon4.004":"Has cruzado el bosque. Al menos no perdí el tiempo enseñándote.","story.map1-dungeon4.005":"Ah, <wait=20>cierto. <wait=40>¿Estás aprovechando bien las chispas?","story.map1-dungeon4.006":"Cuando tus unidades atacan a la vez y consigues una chispa, el daño que infliges aumenta muchísimo.","story.map1-dungeon4.007":"Es una técnica muy importante. Ayuda sobre todo contra enemigos difíciles.","story.map1-dungeon4.008":"¡Sigue practicando hasta dominar el ritmo y lograr muchas chispas!","story.map1-dungeon4.009":"<wait=20>Bueno, ¡crucemos rápido los Humedales de Magutagal! Esto es asqueroso...","story.map1-dungeon4.010":"Agh, <wait=20>me están picando los insectos. Si me quedo más, mis piernas tan suaves se llenarán de picaduras.","story.map1-dungeon4.011":"¡Se acabó! <wait=40>¡Te espero en las ruinas!","story.map1-dungeon5.001":"¡Oh, <wait=20><rep_handlename>! <wait=40>¡Por fin has llegado a las ruinas!","story.map1-dungeon5.002":"Para ser sincera, <wait=20>cuando nos conocimos parecías poco fiable, <wait=20>despistado <wait=20>y sin enterarte de nada de lo que pasaba a tu alrededor...","story.map1-dungeon5.003":"Me preguntaba de verdad... <wait=40>¿esta persona es un Invocador?","story.map1-dungeon5.004":"Pero parece que Lord Lucius tenía razón. <wait=20>¡Tienes potencial!","story.map1-dungeon5.005":"Por cierto, <wait=20>supongo que ya conoces las Habilidades de líder, ¿no?","story.map1-dungeon5.006":"Para obtener ventaja sobre tu rival o compensar las debilidades de tu escuadrón...","story.map1-dungeon5.007":"es importante probar a cambiar de líder para ver distintas Habilidades de líder.","story.map1-dungeon5.008":"Además, <wait=40>cuando otro Invocador te ayuda...","story.map1-dungeon5.009":"...su Habilidad de líder también se activa.","story.map1-dungeon5.010":"¡Es importante, así que no lo olvides!","story.map1-dungeon5.011":"¡Vamos, <wait=20>que estamos a un paso de la Torre de Mistral!","story.map1-dungeon5.012":"Estos Restos de Mirza <wait=40>son lo que queda de una estructura construida hace miles de años...","story.map1-dungeon5.013":"Pero últimamente no he oído que haya criaturas merodeando.","story.map1-dungeon5.014":"Quizá, <wait=20>solo quizá, <wait=20>¡puedas pasar sin incidentes!","story.map1-dungeon5.015":"Bueno... <wait=20>no lo sabremos hasta que lo intentes.","story.map1-dungeon5.016":"Pero viendo todo lo que has logrado hasta ahora, <wait=20>¡dudo que haya algo capaz de detenerte!","story.map1-dungeon5.017":"¡Ten confianza! ¡Suerte!","story.map1-dungeon6.001":"Oh, <wait=20><rep_handlename>.<br><wait=40>Has salido vivo de las ruinas...","story.map1-dungeon6.002":"Brr... <wait=20>Este sitio es frío y da miedo. <wait=40>Mira ese edificio tan sospechoso de allí.","story.map1-dungeon6.003":"He oído que lo llaman el Nido de Monstruos...","story.map1-dungeon6.004":"¡Ese lugar me pone los pelos de punta!","story.map1-dungeon6.005":"Y hace poco han informado de un misterioso espadachín que merodea por la zona.","story.map1-dungeon6.006":"<size=20>¡N-<wait=10>No <size=19>es <size=18>q-<size=17>que <size=16>yo <size=15>tenga <size=14>m-<size=13>mi-<size=12>miedo, <size=11>¿vale<size=9>?!","story.map1-dungeon6.007":"E-En fin, <wait=20>parece que lleva un atuendo raro y empuña una espada extraña. <wait=20>Aun así, no hay que subestimar su verdadero poder.","story.map1-dungeon6.008":"No bajes la guardia...","story.map1-dungeon6.009":"<size=20>¡¡Iiih!!<br><wait=20><size=18>¡A-<size=20>Algo <size=16>me <size=19>acaba <size=17>de <size=18>c-<size=15>caer <size=17>en el <size=19>brazo...!","story.map1-dungeon6.010":"Ah, <wait=20>¿una hoja?<br><wait=60>¿Qué... <wait=20>qué es esa cara que pones?","story.map1-dungeon6.011":"¡E-En fin, <wait=20>ten cuidado!","story.map1-dungeon6.012":"¡Cuando pasemos esto, <wait=20>estaremos al pie de la Torre de Mistral!","story.map1-dungeon6.013":"¡Suerte, <wait=20><rep_handlename>!","story.map1-dungeon7.001":"Por fin hemos llegado a la Torre de Mistral.","story.map1-dungeon7.002":"Aunque la torre sigue dentro de Mistral, Maxwell ya se ha hecho con su control.","story.map1-dungeon7.003":"Para ser sincera, <wait=20>los enemigos que hemos encontrado hasta ahora no son nada comparados con los subordinados de Maxwell.","story.map1-dungeon7.004":"Tenemos que estar bien preparados para ganar esta batalla y liberar la torre del control de Maxwell.","story.map1-dungeon7.005":"En la planta más alta <wait=20>aguarda un monstruo que, según dicen, creó la propia Maxwell.","story.map1-dungeon7.006":"Pero no podemos permitir que te aplasten aquí.","story.map1-dungeon7.007":"Aún estamos lejos de St. Lamia, donde Maxwell nos espera.","story.map1-dungeon7.008":"Seguro que lo harás bien. <wait=40>Hasta tienes mi respeto. <wait=20>¡Confía en ti!","story.map1-dungeon7.009":"¡Vamos, <wait=40><rep_handlename>!","story.map1-dungeon7.010":"¡Desata tu poder <wait=20>y libera Mistral de las garras del mal!","story.map1-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map1-dungeon_ex_clear.002":"<size=21>¡Ahí estás!</size>","story.map1-dungeon_ex_clear.003":"¡<rep_handlename>! <wait=40>¡Lo lograste!","story.map1-dungeon_ex_clear.004":"Hemos confirmado la desaparición de un poder tremendo.","story.map1-dungeon_ex_clear.005":"Parece que has derrotado a Skramya.","story.map1-dungeon_ex_clear.006":"¡Sabía que si alguien podía hacerlo, eras tú!","story.map1-dungeon_ex_clear.007":"Ah, <wait=20>no te habrás hecho daño, ¿verdad?","story.map1-dungeon_ex_clear.008":"¡Yo te cuidaré cuando volvamos!","story.map1-dungeon_ex_clear.009":"Jeje, es broma.","story.map1-dungeon_ex_clear.010":"Esto, <wait=20>gracias a ti hemos obtenido mucha información nueva.","story.map1-dungeon_ex_clear.011":"Parece que hace mucho tiempo una pequeña nación de la región de Mystral intentó usar el poder de Skramya.","story.map1-dungeon_ex_clear.012":"Su plan les salió mal, y Skramya, enfurecido, la destruyó.","story.map1-dungeon_ex_clear.013":"La ira de Skramya no cesó y se dirigió hacia otras naciones.","story.map1-dungeon_ex_clear.014":"Sin embargo, apareció un solo héroe que selló a Skramya con gran valentía. ","story.map1-dungeon_ex_clear.015":"Después de eso, parece que Skramya siguió descansando en las Montañas de Egor sin que nadie lo molestara. ","story.map1-dungeon_ex_clear.016":"Me encantaría saber qué clase de héroe era, pero no tenemos más información.","story.map1-dungeon_ex_clear.017":"Aun así, espero que algún día sepamos más sobre esa persona.","story.map1-dungeon_ex_clear.018":"Bueno, <wait=40>¡te avisaré si conseguimos más información!","story.map1-dungeon_ex_clear.019":"¡Suerte en tu investigación de Grand Gaia!","story.map1-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map1-dungeon_ex_open.002":"H-<wait=20>Hola...","story.map1-dungeon_ex_open.003":"¿Me oye alguien?","story.map1-dungeon_ex_open.004":"¿Me oye, <wait=40>señor?","story.map1-dungeon_ex_open.005":"¡Ah! <wait=40>¡Conseguí comunicarme!","story.map1-dungeon_ex_open.006":"¡<rep_handlename>!","story.map1-dungeon_ex_open.007":"¡Ya has llegado a las Montañas de Egor!","story.map1-dungeon_ex_open.008":"¡Sabía que lo conseguirías!","story.map1-dungeon_ex_open.009":"Ah, <wait=20>permíteme presentarme otra vez.","story.map1-dungeon_ex_open.010":"Soy Lin Merylham, de Apoyo Logístico...","story.map1-dungeon_ex_open.011":"...de la Oficina de Investigación del Departamento de Exploración de Grand Gaia, a tu servicio.","story.map1-dungeon_ex_open.012":"Hoy...","story.map1-dungeon_ex_open.013":"...<rep_handlename>, como miembro del Ejército de Invocadores del Salón de Invocadores de Akras...","story.map1-dungeon_ex_open.014":"...¡te pedimos que investigues las Montañas de Egor!","story.map1-dungeon_ex_open.015":"Aunque está en la región de Mystral, su investigación se retrasó porque estaba bajo el control de Maxwell...","story.map1-dungeon_ex_open.016":"...¡desde que fue derrotada podemos entrar e investigarla a fondo!","story.map1-dungeon_ex_open.017":"Hay Invocadores realmente impresionantes por ahí, ¿verdad?","story.map1-dungeon_ex_open.018":"¡Tú también da lo mejor de ti!","story.map1-dungeon_ex_open.019":"Ah, <wait=20>volviendo a lo que decía.","story.map1-dungeon_ex_open.020":"Sobre las Montañas de Egor...","story.map1-dungeon_ex_open.021":"Según nuestra investigación, allí duerme un demonio inmensamente poderoso. ","story.map1-dungeon_ex_open.022":"Aún no estamos del todo seguros, pero...","story.map1-dungeon_ex_open.023":"...es muy probable que sea el demonio de hielo que, según dicen, habita en la región de Mystral.","story.map1-dungeon_ex_open.024":"¿Eh?","story.map1-dungeon_ex_open.025":"¿No conoces a Skramya, el demonio de hielo?","story.map1-dungeon_ex_open.026":"Me sorprende mucho oír eso...","story.map1-dungeon_ex_open.027":"¡Entendido! <wait=40>¡Entonces te lo explico!","story.map1-dungeon_ex_open.028":"Hace mucho tiempo, en la región de Mystral...","story.map1-dungeon_ex_open.029":"...parece que había varias naciones pequeñas además del antiguo reino de St. Lamia.","story.map1-dungeon_ex_open.030":"Se dice que todas fueron destruidas por los dioses tras su invasión.","story.map1-dungeon_ex_open.031":"Sin embargo, se dice que hubo una que no fue destruida por un dios, sino por Skramya.","story.map1-dungeon_ex_open.032":"Por pequeño que fuera, que un solo demonio acabe con un reino de cualquier tamaño...","story.map1-dungeon_ex_open.033":"......","story.map1-dungeon_ex_open.034":".........","story.map1-dungeon_ex_open.035":"Esto, <wait=20>esa es toda la información que tengo.","story.map1-dungeon_ex_open.036":"¡Es todo lo que necesitas saber!","story.map1-dungeon_ex_open.037":"¡Tiene el poder de destruir reinos!","story.map1-dungeon_ex_open.038":"¡Es extremadamente peligroso!","story.map1-dungeon_ex_open.039":"¡Como Invocador, no puedes dejarlo a su aire!","story.map1-dungeon_ex_open.040":"Vaya, ni siquiera pareces preocupado por lo peligroso que es.","story.map1-dungeon_ex_open.041":"Pero este demonio es realmente brutal, <wait=20>¡así que no te fuerces demasiado!","story.map1-dungeon_ex_open.042":"Bueno, ¡espero con ganas un buen informe tuyo!","story.map1-ending.001":"<size=24>¡¡<rep_handlename>!!<br>¡¡Lo lograste!!</size>","story.map1-ending.002":"¡Tu batalla contra el Juggernaut fue <wait=40>increíble!","story.map1-ending.003":"Ya puedes decir con orgullo que eres un Invocador hábil.","story.map1-ending.004":"Quizá... <wait=40>seas el némesis natural de Maxwell...","story.map1-ending.005":"¡No, <wait=40>no hay quizá que valga!","story.map1-ending.006":"¡Tienes que ser el Invocador destinado a salvar Grand Gaia!","story.map1-ending.007":"...<wait=20>¡Oye! <wait=40>¡Podrías mostrar un poco más de gratitud a quien te está elogiando!","story.map1-ending.008":"¿No puedes emocionarte un poquito? <wait=40>Da vergüenza ser la única entusiasmada con esto.","story.map1-ending.009":"¡Oh! <wait=40>¡Lord Lucius nos llama!","story.map1-ending.010":"<speed=12>Por fin podemos ir a Morgan<wait=10>.<wait=20>.<wait=30>.","story.map1-ending.011":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Soy Lucius...<br><wait=40>Dios de esta Puerta...","story.map1-ending.012":"<anchor=center><br><br><br><br><br><speed=8><size=15><rep_handlename>... <wait=40>Salvador de St. Lamia...","story.map1-ending.013":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Usa mi poder <wait=40>y aventúrate en nuevas tierras...","story.map1-ending.014":"<anchor=center><br><br><br><br><br><br><br><speed=8><size=15>Avanza <wait=20>y usa tu poder para traer la paz a este mundo...","story.map1-ending.015":"<anchor=center><color=000000><speed=5><size=12>...¡Despierta!","story.map1-ending.016":"<anchor=center><color=000000><speed=7><size=18>...¿Me oyes?","story.map1-ending.017":"<anchor=center><color=000000><speed=15><size=40>¡¡<rep_handlename>, despierta!!","story.map1-ending.018":"¡¡Uf, <wait=40>duermes demasiado!!","story.map1-ending.019":"¿Qué? <wait=40>¿Dónde estamos? Esto es Morgan... <wait=20>¡Morgan!","story.map1-ending.020":"¡¿No es maravilloso?! <wait=20>Por fin se han abierto las puertas de Morgan.","story.map1-ending.021":"Por fin, ¿eh?... <wait=20>Morgan...","story.map1-ending.022":"Este lugar fue famoso por sus paisajes pintorescos...","story.map1-ending.023":"Pero han pasado muchos años, <wait=20> y desde entonces ha caído en manos de Maxwell.","story.map1-ending.024":"Los monstruos de aquí son mucho más fuertes que los de Mistral...","story.map1-ending.025":"No sabemos qué nos espera, <wait=40>así que quizá sea mejor que vuelvas a tu aldea y te prepares.","story.map1-ending.026":"Te espero aquí.","story.map1-ending.027":"Cuando vuelvas, vayamos a la Torre de Morgan, <wait=19>¡y allí liberaremos esta tierra!","story.map1-ending.028":"Bueno, <wait=20>¡hasta luego!","story.map10-dungeon1.001":"<size=20>¡Llegas tarde! <wait=40>¡¿Dónde te habías metido, <rep_handlename>?!</size>","story.map10-dungeon1.002":"Me estoy esforzando por salvar a tu amigo, ¡¿cómo te atreves a hacerme esperar?!","story.map10-dungeon1.003":"¡Eres un <size=20>lento </size>y un inútil!","story.map10-dungeon1.004":"Sé que es una petición de los Invocadores Ancianos, pero aun así, ¿por qué tengo que ir yo a buscarlo?","story.map10-dungeon1.005":"Oye, ¿qué es esa cara?","story.map10-dungeon1.006":"No pensarás que voy a abandonar esta misión, ¿verdad?","story.map10-dungeon1.007":"<size=20>¡No me tomes el pelo!</size>","story.map10-dungeon1.008":"Cuando cumpla mis responsabilidades a la perfección, el que quedará como un tonto será ese farsante de Karl.","story.map10-dungeon1.009":"No tendré muchas más oportunidades como esta.","story.map10-dungeon1.010":"¡Así que más te vale espabilar y ayudarme!","story.map10-dungeon1.011":"Si lo haces, quizá podamos terminar rápido con la investigación.","story.map10-dungeon1.012":"No sé si esto era la capital del imperio de Agni o no; todas estas viejas ruinas polvorientas son iguales.","story.map10-dungeon1.013":"<size=20>¡Oye!</size>","story.map10-dungeon1.014":"¡Deja de hacer el tonto y ponte a buscar a ese vago de Karl!","story.map10-dungeon1.015":"¿Mmm?","story.map10-dungeon1.016":"¿Que por dónde empezar?","story.map10-dungeon1.017":"¡Mira que eres idiota!","story.map10-dungeon1.018":"Me pregunto si esa cabeza que llevas sobre los hombros es solo de adorno.","story.map10-dungeon1.019":"Pero esa discípula, Mare, sigue tras de ti, ¿no?","story.map10-dungeon1.020":"Si armaras jaleo aquí, seguro que vendría usando a Karl como moneda de cambio.","story.map10-dungeon1.021":"Esa sería nuestra oportunidad de rescatar al imbécil de Karl.","story.map10-dungeon1.022":"Si me entiendes, sigue fingiendo que investigas como el tonto que eres, ¡y arma todo el alboroto que puedas!","story.map10-dungeon2.001":"<size=20>¡Maldita sea! </size><wait=40><size=22>¡Qué fastidio!","story.map10-dungeon2.002":"¡¿Qué se cree esa mujer de cara pálida escondiéndose de nosotros?!","story.map10-dungeon2.003":"¡Oye! <wait=40>¡<rep_handlename>!","story.map10-dungeon2.004":"Podrías hacer un poco más de ruido, ¿no crees?","story.map10-dungeon2.005":"¡Ve y corretea a la vista como siempre, para que te vean más fácilmente!","story.map10-dungeon2.006":"¡Qué patético, ni siquiera sabes hacer de cebo!","story.map10-dungeon2.007":"¡Ngh! <wait=40>Con lo paciente que soy, me estás llevando al límite.","story.map10-dungeon2.008":"No puedo esperar más a esa discípula.","story.map10-dungeon2.009":"¡Iré a buscar a Karl yo solo!","story.map10-dungeon2.010":"¡Tú búscalo también por tu cuenta!","story.map10-dungeon2.011":"No soy tan amable como para proteger a alguien que no me sirve de nada.","story.map10-dungeon2.012":"Así que no me sigas, ¿entendido?","story.map10-dungeon2.013":"<size=20>¡Oye! ¡<rep_handlename>!</size>","story.map10-dungeon2.014":"Casi se me olvida decírtelo.","story.map10-dungeon2.015":"No dejes que esa discípula te atrape bajo ningún concepto.","story.map10-dungeon2.016":"Seguro que si te atrapan, de algún modo acabarían encargándome rescatarte a ti también.","story.map10-dungeon2.017":"No puedo con más encargos molestos.","story.map10-dungeon2.018":"Es más, si te capturan, mejor que te haga pedazos y punto.","story.map10-dungeon2.019":"<size=20>¡¿Me entiendes?!</size>","story.map10-dungeon3.001":"Parece que por fin me he librado de esas plagas.","story.map10-dungeon3.002":"Mmm. <wait=40>¿Qué es esa cara de sorpresa?","story.map10-dungeon3.003":"Parece que por fin te has quedado a solas.","story.map10-dungeon3.004":"Hasta un humano necio habría previsto que aparecería ante ti, mi presa.","story.map10-dungeon3.005":"¿O quizá eres tan torpe que ni te diste cuenta?","story.map10-dungeon3.006":"......","story.map10-dungeon3.007":"¿Buscas a esa ridícula criaturita verde?","story.map10-dungeon3.008":"Seguro que cayó en la trampa de la información falsa que dejé sobre el paradero de Karl.","story.map10-dungeon3.009":"Ahora mismo debe de estar corriendo como loco por Agni.","story.map10-dungeon3.010":"Por mucho que fanfarronee, no deja de ser un humano.","story.map10-dungeon3.011":"Tus amiguitos me causaron bastantes problemas antes, porque no sabía de ellos.","story.map10-dungeon3.012":"Sin embargo, parece que ya no queda nadie para ayudarte.","story.map10-dungeon3.013":"Me gustaría intentar arrebatarte la vida una vez más.","story.map10-dungeon3.014":"......","story.map10-dungeon3.015":"Sin embargo, eres el Invocador que ya ha derrotado a muchos dioses.","story.map10-dungeon3.016":"Debería dejar que te desgastes un poco más.","story.map10-dungeon3.017":"Si quieres salvar a Karl, sígueme.","story.map10-dungeon3.018":"Si no lo haces, su vida habrá terminado.","story.map10-dungeon3.019":"Aun sabiendo que el camino está lleno de trampas, me pregunto si vendrás tras de mí.","story.map10-dungeon3.020":"Hmph. <wait=40>Los humanos sois realmente necios.","story.map10-dungeon3.021":"Avanza a duras penas, para que luego me resulte más fácil acabar contigo.","story.map10-dungeon3.022":"Espero con ganas verte debilitado.","story.map10-dungeon4.001":"Así que has superado la Meseta de Granasta.","story.map10-dungeon4.002":"Supongo que era de esperar de quien derrotó a Maxwell y a Cardes.","story.map10-dungeon4.003":"......","story.map10-dungeon4.004":"Al mirarte, recuerdo la guerra en la que los humanos fueron destruidos.","story.map10-dungeon4.005":"Esos humanos tan necios como para creer que podían oponerse a los dioses.","story.map10-dungeon4.006":"Ahora que lo pienso, en aquella época hubo otro humano tan tenaz como tú.","story.map10-dungeon4.007":"Parece que los demás humanos lo llamaban héroe.","story.map10-dungeon4.008":"Sin embargo, estaba tan indefenso y tan desesperadamente asustado como tú ahora.","story.map10-dungeon4.009":"Por muy poderoso que fuera para ser humano...","story.map10-dungeon4.010":"...no podía compensar que no era más que un humano ignorante.","story.map10-dungeon4.011":"Tú también acabarás poniendo una expresión parecida.","story.map10-dungeon4.012":"Tengo ganas de disfrutarlo.","story.map10-dungeon4.013":"......","story.map10-dungeon4.014":"Hmph. <wait=40>Esa mirada tuya no me interesa.","story.map10-dungeon4.015":"Supongo que tendré que hacerte sufrir un poco más.","story.map10-dungeon4.016":"¿Qué te parece?","story.map10-dungeon4.017":"Déjame ver hasta dónde llegas por tu cuenta.","story.map10-dungeon5.001":"<rep_handlename>. Así que sigues decidiendo resistir.","story.map10-dungeon5.002":"Detesto esos ojos tuyos, <wait=40>sin rastro de desesperación.","story.map10-dungeon5.003":"¿Cómo puedes seguir teniendo esperanza en una situación así?","story.map10-dungeon5.004":"Ninguno de los aliados que te apoyaban sigue a tu lado.","story.map10-dungeon5.005":"Ni siquiera tu amigo de la infancia.","story.map10-dungeon5.006":"Ni la chica Invocadora que no paraba de insultarte.","story.map10-dungeon5.007":"Ni el anciano con sus ridículas expectativas sobre ti.","story.map10-dungeon5.008":"Ni esa criatura increíblemente vulgar.","story.map10-dungeon5.009":"Ni siquiera la diosa de bajo rango que te ha estado utilizando todo este tiempo.","story.map10-dungeon5.010":"......","story.map10-dungeon5.011":"¿O acaso quieres decirme que desde el principio nunca has dependido de nadie?","story.map10-dungeon5.012":"¿Y aun así eliges intentar salvar desesperadamente a tus amigos?","story.map10-dungeon5.013":"Qué idea tan incomprensible.","story.map10-dungeon5.014":"......","story.map10-dungeon5.015":"Ya veo, ahora lo recuerdo.","story.map10-dungeon5.016":"Ahora que lo pienso, <wait=20>aquella vez, cuando ese hombre estaba metido en problemas hasta el cuello...","story.map10-dungeon5.017":"...despertó un nuevo poder en su interior.","story.map10-dungeon5.018":"Lucía a la espalda unas grandes alas de llamas.","story.map10-dungeon5.019":"Hace mucho que deseo olvidar la deshonra de aquel poder que empuñaba.","story.map10-dungeon5.020":"Si he de suponer que tú posees ese mismo poder, ya no tengo tiempo para juegos.","story.map10-dungeon5.021":"Hmph...","story.map10-dungeon5.022":"Pero no puedo seguir dejando que me hagas perder el tiempo.","story.map10-dungeon5.023":"La batalla entre Lord Zefalhua y Afla Dilith está cerca.","story.map10-dungeon5.024":"Debo acabar contigo antes de que puedas interferir en mis predicciones.","story.map10-dungeon5.025":"¿Estás listo?","story.map10-dungeon5.026":"Voy a mostrarte un mundo de desesperación como nunca has visto.","story.map10-dungeon5.027":"No me contendré, ¡así que contempla mi verdadero poder!","story.map10-dungeon5.028":"¡Recíbelo con todo lo que tienes!","story.map10-dungeon6.001":"Hasta aquí, <wait=40><rep_handlename>.","story.map10-dungeon6.002":"Has luchado bien contra los dioses hasta ahora.","story.map10-dungeon6.003":"Sin embargo, por las heridas que cubren tu cuerpo, veo que ya no puedes luchar.","story.map10-dungeon6.004":"¡No permitiré que Lucius y sus predicciones avancen más!","story.map10-dungeon6.005":"¡Muere!","story.map10-dungeon6.006":"<size=18>*Cliiiing*","story.map10-dungeon6.007":"¡Ngh!","story.map10-dungeon6.008":"¿Cómo has dejado que una mujer así te cause tantos problemas?","story.map10-dungeon6.009":"De verdad, <wait=20>mira que eres idiota.","story.map10-dungeon6.010":"¡Oye, recupérate!","story.map10-dungeon6.011":"¡No te dejes derrotar antes de que podamos salvar a Karl!","story.map10-dungeon6.012":"¡Necio! <wait=20>¿Aún pretendes moverte con esas heridas?","story.map10-dungeon6.013":"No me tomes el pelo.","story.map10-dungeon6.014":"¿De verdad creías que un ataque así acabaría conmigo?","story.map10-dungeon6.015":"Para ser una discípula, eres bien estúpida.","story.map10-dungeon6.016":"Muy propio de un humano.","story.map10-dungeon6.017":"<size=18>*Claaaang*","story.map10-dungeon6.018":"¡Ngh!","story.map10-dungeon6.019":"¿Qué haces ahí parada?","story.map10-dungeon6.020":"¿Acaso la batalla con <rep_handlename> te ha dejado sin poder moverte?","story.map10-dungeon6.021":"Así es, <wait=20>en cuanto a Karl, <wait=20>Lugina ya va de camino a rescatarlo del Santuario Oceánico.","story.map10-dungeon6.022":"Y tú que creías haberlo engañado con tanta astucia. <wait=20>Qué lástima.","story.map10-dungeon6.023":"Eso es imposible.","story.map10-dungeon6.024":"Ngh, <rep_handlename>. <wait=20>Parece que esta vez te has librado de la muerte por poco.","story.map10-dungeon6.025":"Aunque lo único que ha vuelto a ti es un Invocador lleno de heridas.","story.map10-dungeon6.026":"Os destruiré a ambos en cuanto me haya ocupado de esa criatura vulgar.","story.map10-dungeon6.027":"......","story.map10-dungeon6.028":"......<wait=40>Ya no la siento.","story.map10-dungeon6.029":"Ngh.","story.map10-dungeon6.030":"*Jadeo* <wait=20>*jadeo* <wait=20>*Jadeo* ","story.map10-dungeon6.031":"E-<wait=20>Estoy bien.","story.map10-dungeon6.032":"Solo ha vuelto parte del dolor después de que se fuera.","story.map10-dungeon6.033":"Aun así, me alegro de que hayamos podido engañarla.","story.map10-dungeon6.034":"Mira...<wait=40>No podemos quedarnos aquí parados, tenemos que ir al Santuario Oceánico.","story.map10-dungeon6.035":"Seguro que es allí donde tienen a Karl.","story.map10-dungeon6.036":"¿Qué es esa cara?","story.map10-dungeon6.037":"No tengo tiempo para quedarme sentada hablando contigo.","story.map10-dungeon6.038":"Te prometo que hablaremos luego, así que por ahora vamos a por Karl.","story.map10-dungeon7.001":"*Jadeo* *jadeo* *jadeo*","story.map10-dungeon7.002":"Por fin hemos llegado al Santuario Oceánico.","story.map10-dungeon7.003":"Veo que estás casi al límite.","story.map10-dungeon7.004":"Es ella otra vez.","story.map10-dungeon7.005":"Reconozco el valor que hace falta para plantarte ante mí tan maltrecho como estás.","story.map10-dungeon7.006":"Hmph. <wait=40>Qué engreída eres.","story.map10-dungeon7.007":"Aunque te engañé para que me dijeras dónde teníais a Karl.","story.map10-dungeon7.008":"...Necios.","story.map10-dungeon7.009":"Veo que habéis llegado hasta mí a duras penas a través de la Cala de Lognea.","story.map10-dungeon7.010":"¿Creéis que podéis escapar de mí con esas heridas?","story.map10-dungeon7.011":"Ngh...","story.map10-dungeon7.012":"¡Mis siervos!","story.map10-dungeon7.013":"¡Reuníos aquí y librad al mundo de estos insectos!","story.map10-dungeon7.014":"¿Q-Qué es esto? <wait=20>¡¿De dónde han salido todos?!","story.map10-dungeon7.015":"¿No te da vergüenza, siendo una diosa, llamar a tantos solo para luchar contra unos humanos?","story.map10-dungeon7.016":"Basta de desvaríos absurdos.","story.map10-dungeon7.017":"Aquí es donde por fin me libraré de vosotros.","story.map10-dungeon7.018":"Eso es todo.","story.map10-dungeon7.019":"¡<rep_handlename>!","story.map10-dungeon7.020":"¡Arrepiéntete de tu necio desafío a los dioses y muere!","story.map10-dungeon7.021":"Ngh... <wait=40>Esto pinta mal, <wait=40>son demasiados.","story.map10-dungeon7.022":"No es propio de ti mostrarte tan tímida en una situación así.","story.map10-dungeon7.023":"¡Esa voz!","story.map10-dungeon7.024":"¿C-Cómo has...","story.map10-dungeon7.025":"Hola. <wait=40>Siento haberte hecho esperar.","story.map10-dungeon7.026":"¡Karl!","story.map10-dungeon7.027":"¿Cómo has...","story.map10-dungeon7.028":"La última vez que lo comprobé seguías encerrado en esa habitación...","story.map10-dungeon7.029":"Fue cuando viniste a comprobarlo cuando me di cuenta de dónde estaba.","story.map10-dungeon7.030":"Oh, diosa de tan escasa inteligencia.","story.map10-dungeon7.031":"Cómo te atreves...","story.map10-dungeon7.032":"¡Lugina! <wait=20>¡¿Por qué has tardado tanto?!","story.map10-dungeon7.033":"¡Silencio!","story.map10-dungeon7.034":"¡Rescatarlo me ha llevado una eternidad por lo vago que es!","story.map10-dungeon7.035":"Ya te he dicho que lo siento.","story.map10-dungeon7.036":"Ah, por cierto, Seria...","story.map10-dungeon7.037":"¿Cómo has acabado así?","story.map10-dungeon7.038":"¡No es culpa mía, cierta persona me estaba frenando!","story.map10-dungeon7.039":"¡Da igual, olvidémoslo!","story.map10-dungeon7.040":"Aquí tenemos un asunto que resolver.","story.map10-dungeon7.041":"¿Verdad, Mare?","story.map10-dungeon7.042":"Tu plan ya se ha venido abajo.","story.map10-dungeon7.043":"¿Qué piensas hacer ahora?","story.map10-dungeon7.044":"Humano, ¿te atreves a creerte por encima de los dioses?","story.map10-dungeon7.045":"Te elogio por haber superado mis expectativas.","story.map10-dungeon7.046":"Pero, pese a mi respeto, ahora abandonaré mis planes y simplemente haré que te destruyan.","story.map10-dungeon7.047":"¡Yo, Mare, discípula de Lord Zevalhua, os lo ordeno!","story.map10-dungeon7.048":"¡Mis siervos!","story.map10-dungeon7.049":"¡Reuníos a mi alrededor y destruid a mis enemigos!","story.map10-dungeon7.050":"¡Matad a todos los humanos que tengo delante!","story.map10-dungeon7.051":"Parece que ya se han reunido aquí unos cuantos.","story.map10-dungeon7.052":"Hay muchísimos más que antes.","story.map10-dungeon7.053":"Humanos. <wait=40>Habéis luchado bien.","story.map10-dungeon7.054":"No dejaré de recordaros...","story.map10-dungeon7.055":"...ni el trágico final que pronto os espera.","story.map10-dungeon7.056":"¡¿Adónde crees que vas?!","story.map10-dungeon7.057":"¡Apartaos todos de mi camino!","story.map10-dungeon7.058":"Son demasiados.","story.map10-dungeon7.059":"Karl, <wait=40>estás herido...","story.map10-dungeon7.060":"Ja, ja, <wait=20>esa discípula solo me ha dado unos cuantos golpes, nada más...","story.map10-dungeon7.061":"¡No le quites importancia!","story.map10-dungeon7.062":"Pero Seria, tú también estás herida...","story.map10-dungeon7.063":"E-Esto no es más que...","story.map10-dungeon7.064":"¡Mirad a todas estas criaturas lamentables!","story.map10-dungeon7.065":"¡Oye! <wait=40>¡<rep_handlename>!","story.map10-dungeon7.066":"Estoy harto de tanto correr de un lado a otro.","story.map10-dungeon7.067":"¡Tú ve tras esa mujer pálida y acaba con ella!","story.map10-dungeon7.068":"¡Yo me ocupo de estos dos mientras tanto!","story.map10-dungeon7.069":"¡No necesitamos que cuides de nosotros!","story.map10-dungeon7.070":"Siento haberte preocupado, <rep_handlename>.","story.map10-dungeon7.071":"Déjanos esto a nosotros y ve tras esa discípula.","story.map10-dungeon7.072":"Te lo compensaré después, te lo prometo.","story.map10-dungeon7.073":"Contamos contigo, <wait=20><rep_handlename>.","story.map10-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map10-dungeon_ex_clear.002":"<size=18>¿Me oyes...?</size> <wait=20><size=20> *Bzz...zzz*</size>","story.map10-dungeon_ex_clear.003":"<size=20>*Bzz*</size> <size=18>...¿Señor...?</size> <wait=20>*Bzz*</size>","story.map10-dungeon_ex_clear.004":"<size=18>*Bzz*</size><wait=20><size=20> ¡Ah, ya está!</size>","story.map10-dungeon_ex_clear.005":"Cuesta muchísimo tener señal en esas mazmorras.","story.map10-dungeon_ex_clear.006":"En fin, <wait=20>deja que te cuente lo que he descubierto.","story.map10-dungeon_ex_clear.007":"Según la literatura antigua...","story.map10-dungeon_ex_clear.008":"...ese lugar estaba sellado desde el último periodo del Imperio de Agni.","story.map10-dungeon_ex_clear.009":"Pero 100 años antes, hubo un emperador al que encarcelaron allí en secreto.","story.map10-dungeon_ex_clear.010":"Pasó mucho tiempo sin que nadie supiera que estaba allí abajo. ","story.map10-dungeon_ex_clear.011":"Ese emperador era temido por quienes lo rodeaban y lo consideraban un tirano.","story.map10-dungeon_ex_clear.012":"En realidad, <wait=20>no solo lo temían sus súbditos, sino también sus hijos.","story.map10-dungeon_ex_clear.013":"Un día, un niño que había sufrido a manos de él enfermó y murió.","story.map10-dungeon_ex_clear.014":"Por eso lo encarcelaron en secreto.","story.map10-dungeon_ex_clear.015":"Con el paso del tiempo en la oscura mazmorra, la ira del emperador creció junto con su soledad.","story.map10-dungeon_ex_clear.016":"Renació como un espectro inmensamente poderoso y se vengó del imperio durante 100 años.","story.map10-dungeon_ex_clear.017":"Como resultado, <wait=20>el fantasma del emperador fue sellado junto con la mazmorra.","story.map10-dungeon_ex_clear.018":"Sigue en algún lugar ahí abajo, <wait=20>y su ira crece a cada segundo.","story.map10-dungeon_ex_clear.019":"Da miedo solo de pensarlo.","story.map10-dungeon_ex_clear.020":"Señor, <wait=20>¡no hace falta que te esfuerces en encontrar a ese fantasma!","story.map10-dungeon_ex_clear.021":"Solo tienes que investigar a fondo lo peligroso que es ese lugar.","story.map10-dungeon_ex_clear.022":"¿Q-<wait=20>Qué es eso?<wait=40> ¿Qué acabas de decir?","story.map10-dungeon_ex_clear.023":"¡No puede ser!","story.map10-dungeon_ex_clear.024":"¡¿Has derrotado al fantasma del emperador mientras yo investigaba?!","story.map10-dungeon_ex_clear.025":"Vaya, señor...<wait=20>eres increíble.","story.map10-dungeon_ex_clear.026":"¡Pero espera! <wait=40>¡Espera un segundo!","story.map10-dungeon_ex_clear.027":"De verdad quería que esperaras un poco más hasta que terminara mi investigación...","story.map10-dungeon_ex_clear.028":"Mmm...<wait=20> ¡Bueno, da igual!","story.map10-dungeon_ex_clear.029":"¡La próxima vez haré lo posible por darte la información lo antes que pueda!","story.map10-dungeon_ex_clear.030":"¡Te demostraré que no eres el único que ha mejorado sus habilidades!","story.map10-dungeon_ex_clear.031":"Volveré a contactarte pronto, ¡así que espérame!","story.map10-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map10-dungeon_ex_open.002":"<size=18>Se...</size> <wait=20><size=20>*Bzz...zzz*</size>","story.map10-dungeon_ex_open.003":"<size=20>*Bzz*</size> <size=18>...¿me...oye?</size> <wait=20>*Bzz*</size>","story.map10-dungeon_ex_open.004":"<size=18>*Bzz*</size><wait=20><size=20>¡Señor!</size>","story.map10-dungeon_ex_open.005":"¡Por fin hemos conectado!","story.map10-dungeon_ex_open.006":"Parece que estás en un sitio con muy mala cobertura.","story.map10-dungeon_ex_open.007":"En fin, <wait=20>déjame empezar de nuevo.","story.map10-dungeon_ex_open.008":"Soy Lin Merylham, de Apoyo Logístico...","story.map10-dungeon_ex_open.009":"...de la Oficina de Investigación del Departamento de Exploración de Grand Gaia, a tu servicio.","story.map10-dungeon_ex_open.010":"Hace unos días confirmamos la desaparición de un gran poder en la región de Agni. ","story.map10-dungeon_ex_open.011":"Parece que eso hizo que se abriera una estructura subterránea que estaba sellada. ","story.map10-dungeon_ex_open.012":"Según nuestros registros, <wait=20>allí se mantenía encerrado algo bastante siniestro.","story.map10-dungeon_ex_open.013":"Tu misión esta vez es ir y detenerlo...","story.map10-dungeon_ex_open.014":"...¡antes de que pueda salir y causar daños!","story.map10-dungeon_ex_open.015":"Parece que hace muchísimo tiempo la estructura era una mazmorra.","story.map10-dungeon_ex_open.016":"¿Eh? <wait=40>¿Ya estás allí?","story.map10-dungeon_ex_open.017":"¡No me sorprende!","story.map10-dungeon_ex_open.018":"Muy bien, <wait=20>haré lo que pueda para averiguar más sobre la mazmorra.","story.map10-dungeon_ex_open.019":"Tendré información nueva para ti antes de que termines tu investigación.","story.map10-dungeon_ex_open.020":"¡Aguanta un poquito más!","story.map10-ending.001":"N-<wait=20>Necios...","story.map10-ending.002":"¿Cómo puede una diosa como yo haber sido derrotada por humanos...?","story.map10-ending.003":"¡E-Entonces que así sea!","story.map10-ending.004":"<size=20>¡Os enterraré a todos junto con este santuario!</size>","story.map10-ending.005":"<size=14>*Retumbo* *retumbo*</size>","story.map10-ending.006":"<size=21>¡No dejaré que eso pase!</size>","story.map10-ending.007":"Ngh, <wait=40>¡así que tú también sobreviviste!","story.map10-ending.008":"¡Tilith, discípula de Lucius!","story.map10-ending.009":"¡Estoy aquí, <rep_handlename>!","story.map10-ending.010":"¡Muy bien, salgamos todos de aquí!","story.map10-ending.011":"¡Alto, <rep_handlename>!","story.map10-ending.012":"¡No creas que ya has ganado!","story.map10-ending.013":"Da igual cuántos os reunáis.","story.map10-ending.014":"¡Ante Lord Zevalhua no sois nada!","story.map10-ending.015":"Y, además, la pieza clave entre vosotros es...","story.map10-ending.016":"<size=15>*Retumbo* *retumbo*</size>","story.map10-ending.017":"¡Mare! <wait=40>¡Asúmelo, has perdido!","story.map10-ending.018":"¡<rep_handlename>! <wait=40>¡Todos te están esperando!","story.map10-ending.019":"¡Vamos!","story.map10-ending.020":"<size=16>*Retumbo* *retumbo*</size>","story.map10-ending.021":"Ngh...","story.map10-ending.022":"<size=19>Lord Zevalhua...</size>","story.map10-ending.023":"<size=18>*Retumbo* *retumbo*</size>","story.map10-ending.024":"¡<rep_handlename>!","story.map10-ending.025":"¡Lo conseguiste!","story.map10-ending.026":"¡Sabía que podías derrotar a Mare, mi <rep_handlename>!","story.map10-ending.027":"¡A-Ay!","story.map10-ending.028":"Veo que vuelas tan bruscamente como siempre, <wait=40> diosa.","story.map10-ending.029":"¿No puedes tener un poquito más de cuidado?","story.map10-ending.030":"¡Oye, <wait=20>vosotros dos, dejad de quejaros!","story.map10-ending.031":"Aun así, me alegro de que estéis bien, Karl y Seria.","story.map10-ending.032":"¡Estaba muy preocupada llevándote, Seria, con lo herida que estás!","story.map10-ending.033":"Gracias por eso...","story.map10-ending.034":"Sí, <wait=20>yo también te lo agradezco, diosa.","story.map10-ending.035":"¡Y a ti también, por supuesto, <rep_handlename>!","story.map10-ending.036":"Pero que no se te suba a la cabeza, solo nos dejarías en mal lugar.","story.map10-ending.037":"Siento haber tardado tanto en recuperarme.","story.map10-ending.038":"En fin, ¡has estado increíble como siempre, <rep_handlename>!","story.map10-ending.039":"¡Derrotaste a Mare!","story.map10-ending.040":"Sí, <wait=20>así es.","story.map10-ending.041":"<rep_handlename>, <wait=40>de verdad me enorgullece poder llamarte amigo íntimo.","story.map10-ending.042":"Así es, Karl.","story.map10-ending.043":"Esto...","story.map10-ending.044":"No quiero aguaros la fiesta, pero ¿no nos estamos olvidando de alguien?","story.map10-ending.045":"¡Es verdad! <wait=40>¡Lugina!","story.map10-ending.046":"¿Dónde estará?","story.map10-ending.047":"¿Quién es Lugina?","story.map10-ending.048":"Ya veo, así que aún no conoces a Lugina en persona, ¿verdad, diosa?","story.map10-ending.049":"No puede ser, <wait=40>¿me estás diciendo que solo nos trajiste a nosotros?","story.map10-ending.050":"Esto, <wait=40>para empezar, ni sabía que hubiera nadie más.","story.map10-ending.051":"¿Quizá habláis de esa persona que estaba medio enterrada en el suelo?","story.map10-ending.052":"<size=21>¡Lugina!</size>","story.map10-ending.053":"<size=22>¡Imbéciles! <wait=40>¡Os voy a dejar a todos fuera de combate!</size>","story.map10-ending.054":"Oye, al menos has llegado de una pieza.","story.map10-ending.055":"Je... <wait=20>Estabas hecho un desastre ahí atrás, Lugina.","story.map10-ending.056":"<size=20>¡Niña estúpida! <wait=40>¡A ti te va a tocar lo peor!","story.map10-ending.057":"¡Seria, te he dicho que pares!","story.map10-ending.058":"Lugina, <wait=40>esta vez nos has salvado de verdad.","story.map10-ending.059":"Gracias.","story.map10-ending.060":"Je, <wait=20>solo os ayudé porque me lo pidió el Salón de Invocadores.","story.map10-ending.061":"Sinceramente, me habría dado igual quién fuera.","story.map10-ending.062":"Aun así, ¿cómo supiste dónde me tenían retenido?","story.map10-ending.063":"Fue fácil.","story.map10-ending.064":"Sabía que esa mujer intentaría dejar solo a este cabeza hueca.","story.map10-ending.065":"Así que sabía que, si le facilitaba esa situación, seguro que vendría corriendo.","story.map10-ending.066":"Sin embargo, era muy precavida.","story.map10-ending.067":"Karl, <wait=20>predije que te usaría como cebo mientras se acercaba poco a poco.","story.map10-ending.068":"El resto lo dejé arreglado antes de salir de Elgaia.","story.map10-ending.069":"Solo tenía que decirle a esta niña tonta que salvara a ese imbécil.","story.map10-ending.070":"<size=20>¡¿A quién llamas tonta?!</size>","story.map10-ending.071":"Bueno, <wait=40>tu idea acabó salvándome.","story.map10-ending.072":"En cuanto llegué, le mencioné a esa discípula el nombre del lugar cercano que me dijiste.","story.map10-ending.073":"Nada más decirlo, tal como dijiste, se marchó.","story.map10-ending.074":"Je, <wait=40>era fácil de adivinar, sabiendo cuándo ibais a llegar.","story.map10-ending.075":"La verdad es que no había tantos sitios donde esconder a alguien.","story.map10-ending.076":"Esa discípula estúpida <wait=20>hizo exactamente lo que yo pensaba.","story.map10-ending.077":"Se fue al Santuario Oceánico a ver cómo estaba su prisionero.","story.map10-ending.078":"Y, al hacerlo, me llevó directamente hasta él.","story.map10-ending.079":"Vaya, es increíble, Lugina.","story.map10-ending.080":"<size=19>Cuesta creer que alguien como tú pudiera lograr algo así.</size>","story.map10-ending.081":"<size=21>¡Cómo te atreves!<\\\\size>","story.map10-ending.082":"¡Así que tú eres Lugina!","story.map10-ending.083":"¡Encantada de conocerte!","story.map10-ending.084":"Soy Tilith, la diosa que vela por <rep_handlename>.","story.map10-ending.085":"Soy discípula de Lucius.","story.map10-ending.086":"¿Una diosa que es discípula de Lucius?","story.map10-ending.087":"¡Oye, <rep_handlename>!","story.map10-ending.088":"¿Esta chica está loca o qué?","story.map10-ending.089":"¡Qué malo eres!","story.map10-ending.090":"¡Y pensar que fui yo quien te trajo del Santuario Oceánico!","story.map10-ending.091":"¿Así que fuiste tú?","story.map10-ending.092":"Bueno, si es así...","story.map10-ending.093":"Sí, es una diosa de verdad.","story.map10-ending.094":"<size=18>No puede ser...</size>","story.map10-ending.095":"Ese viejo necio de Grahdens.","story.map10-ending.096":"¿De qué demonios estaba hablando...?","story.map10-ending.097":"Ah, y Lugina...","story.map10-ending.098":"Fue Grahdens quien te pidió que nos salvaras, ¿no es así?","story.map10-ending.099":"¿Qué anda tramando ahora el viejo?","story.map10-ending.100":"¡¿Qué?! <wait=20>¿Cómo voy a saberlo?","story.map10-ending.101":"Seguro que anda vagando por ahí.","story.map10-ending.102":"Si habláis del Anciano Grahdens, ha sido capturado por Zevalhua.","story.map10-ending.103":"Eres tú...","story.map10-ending.104":"Cuánto tiempo, <rep_handlename>.","story.map10-ending.105":"Aunque parece que aún no conozco a ninguno de tus amigos.","story.map10-ending.106":"Tenía ganas de conoceros a todos.","story.map10-ending.107":"¿Qué hace aquí un guardia imperial de pacotilla como tú?","story.map10-ending.108":"Antes de nada, ¿qué quieres decir con que han capturado al viejo?","story.map10-ending.109":"Je, je, je, <wait=20>no seas impaciente.","story.map10-ending.110":"Yo también tengo algunas cosas que preguntar.","story.map10-ending.111":"Por ejemplo, por qué sigues vivo después de que te capturara esa discípula.","story.map10-ending.112":"Pero podemos hablar de los detalles en Milvana.","story.map10-ending.113":"¿Os parece bien a vosotros dos...","story.map10-ending.114":"<rep_handlename> y Tilith, discípula de Lord Lucius?","story.map10-ending.115":"Sí, a mí me parece bien.","story.map10-ending.116":"Seguro que Lord Lucius pronto nos abrirá un camino a Milvana.","story.map10-ending.117":"Esto ya empieza a ser un fastidio.","story.map10-ending.118":"Karl, <wait=40>¿estás bien?","story.map10-ending.119":"Grahdens...","story.map10-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Soy Lucius...<br><wait=40>Dios de esta Puerta...","story.map10-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Tú, <rep_handlename>,<wait=39> que liberaste Ryvern...","story.map10-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Usa mi poder <wait=40>y adéntrate en nuevas tierras...","story.map10-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Para traer una nueva esperanza a este mundo sin orden...","story.map10-open.005":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Debes tener fe en tu poder <wait=20>y seguir avanzando...","story.map10-open.006":"<size=21>¡<rep_handlename>! <wait=40>¡¿Por qué has tardado tanto?!</size>","story.map10-open.007":"Hacer esperar a quien te salvó la vida, como haces siempre... no me lo puedo creer.","story.map10-open.008":"Da igual.","story.map10-open.009":"Seré amable y te lo explicaré, aunque seas un idiota.","story.map10-open.010":"¡Que por qué me encontraste allí, claro!","story.map10-open.011":"Tuve una visión.","story.map10-open.012":"Con mi mente genial pude prever el aprieto en el que acabarías metiéndote.","story.map10-open.013":"......","story.map10-open.014":"No me crees, <wait=20>¿verdad?","story.map10-open.015":"Hmph, <wait=20>da igual.","story.map10-open.016":"Fue el viejo Grahdens.","story.map10-open.017":"Me pidió que os siguiera a todos.","story.map10-open.018":"Fue una petición directa de los Invocadores Ancianos para mí.","story.map10-open.019":"¡Eso demuestra que el Salón de Invocadores confía en mi fuerza!","story.map10-open.020":"<size=21>¡Ja, ja, ja, ja!</size>","story.map10-open.021":"En fin, <wait=20>lo que de verdad querían es que rescatara a ese inútil de Karl.","story.map10-open.022":"......","story.map10-open.023":"Tú vas a ayudarme con eso.","story.map10-open.024":"No te atreverás a rechazar los deseos de quien te salvó la vida, ¿verdad?","story.map10-open.025":"Muy bien, me pondré en camino hacia el Imperio de Agni.","story.map10-open.026":"Si la información que he conseguido es correcta, allí tienen retenido a Karl.","story.map10-open.027":"No va a ser fácil, pero todo empieza en el imperio.","story.map10-open.028":"¡No es momento de dudar! ¿Me oyes?","story.map10-open.029":"¡Eso es!","story.map10-open.030":"Esa discípula, Mare, aún te tiene en el punto de mira, ¿no?","story.map10-open.031":"¡Más te vale rezar para que no te alcance!","story.map10-open.032":"<size=22>¡Ja, ja, ja, ja!</size>","story.map11-dungeon1.001":"<rep_handlename>...<wait=40>¡¡llegas tarde!! ","story.map11-dungeon1.002":"¡Deja de ser tan vago!","story.map11-dungeon1.003":"En serio...","story.map11-dungeon1.004":"¿Por qué nos has hecho esperar tanto en un sitio tan caluroso?","story.map11-dungeon1.005":"¡Vaya, vaya! <wait=20>Parece que vosotros dos os lleváis bastante bien.","story.map11-dungeon1.006":"<speed=15><size=21>¡No me tomes el pelo! ¡Deja de tomarme el pelo!</size></speed>","story.map11-dungeon1.007":"Vaya...<wait=20>¡hasta decís exactamente lo mismo!","story.map11-dungeon1.008":"<speed=15><size=21>¡¿Qué has dicho?! ¡¿Qué has dicho?!</size></speed>","story.map11-dungeon1.009":"Diosa, <wait=40>¿esa es la Paris de la Guardia Imperial?","story.map11-dungeon1.010":"Te lo ruego, no me cargues con más problemas...","story.map11-dungeon1.011":"Los padres que me criaron ya tienen bastantes problemas...","story.map11-dungeon1.012":"Je, je... <wait=20>Perdón por eso.","story.map11-dungeon1.013":"Y<wait=20><rep_handlename> también ha venido.","story.map11-dungeon1.014":"¿Puedes contarme el resto de la historia cuanto antes?","story.map11-dungeon1.015":"¿Es verdad que Zevalhua ha capturado al Anciano Grahdens?","story.map11-dungeon1.016":"Sí, es verdad.","story.map11-dungeon1.017":"No puedo darte muchos detalles,","story.map11-dungeon1.018":"pero la información me la dio un miembro de confianza de la Guardia Imperial, así que es bastante fiable.","story.map11-dungeon1.019":"Ya veo...","story.map11-dungeon1.020":"Tsk.<wait=40> ¿Por qué ese viejo Invocador tuvo que dejarse capturar? ","story.map11-dungeon1.021":"Qué fastidio.","story.map11-dungeon1.022":"¡Lugy! <wait=40> ¡No digas esas cosas!","story.map11-dungeon1.023":"¡Sabes que Elder Grah se esfuerza mucho por todos nosotros!","story.map11-dungeon1.024":"¡¿Lugy?!","story.map11-dungeon1.025":"Lugy... <wait=80> Je, je...","story.map11-dungeon1.026":"Qué apodo tan asqueroso...","story.map11-dungeon1.027":"Desde luego tienes algo que los humanos no podemos entender, diosa.","story.map11-dungeon1.028":"Señora de la Guardia Imperial, te equivocas.","story.map11-dungeon1.029":"Solo está un poco loca, nada más.","story.map11-dungeon1.030":"¡¡¡Qué malos sois los dos!!!","story.map11-dungeon1.031":"Seria, <wait=40>ya basta, ¿vale?","story.map11-dungeon1.032":"Si seguís así, no llegaremos a ninguna parte.","story.map11-dungeon1.033":"Y tú...<wait=20> ¿Podemos llamarte simplemente Paris?","story.map11-dungeon1.034":"Je, je.<wait=20> Me honras solo con llamarme por mi nombre, oh famoso Invocador Karl.","story.map11-dungeon1.035":"No te burles de mí.","story.map11-dungeon1.036":"En fin, estamos seguros de que el anciano está en algún lugar de Mirvana, ¿verdad?","story.map11-dungeon1.037":"Sí. <wait=40>Me temo que sí.","story.map11-dungeon1.038":"Creo que, si Zevalhua capturó a Elder Grah, probablemente también estará en algún lugar de Mirvana.","story.map11-dungeon1.039":"Porque gracias a todos los esfuerzos de <rep_handlename>, ","story.map11-dungeon1.040":"este es el único lugar que sigue bajo el control de Zevalhua.","story.map11-dungeon1.041":"Y si es así, <wait=40> sería más rápido separarnos y buscar lugares sospechosos.","story.map11-dungeon1.042":"Supongo que no queda más remedio que dividir las fuerzas, ¿eh?","story.map11-dungeon1.043":"¡Entonces vosotros no os metáis en mi camino!","story.map11-dungeon1.044":"Sí, sí. Ya lo hemos entendido.","story.map11-dungeon1.045":"¡Da lo mejor de ti, Lugy!","story.map11-dungeon1.046":"¡Niña estúpida! <wait=40>¡Te voy a hacer papilla!","story.map11-dungeon1.047":"¡Parece que tener algo que hacer volverá a hacer las cosas divertidas!","story.map11-dungeon1.048":"Qué pereza...","story.map11-dungeon1.049":"<rep_handlename>, <wait=40><br>contamos contigo para esto.","story.map11-dungeon1.050":"¡Ayuda al anciano con el mismo poder con el que me ayudaste a mí!","story.map11-dungeon2.001":"Mmm...","story.map11-dungeon2.002":"Por aquí no parece haber ningún sitio sospechoso...","story.map11-dungeon2.003":"¿Eh...?","story.map11-dungeon2.004":"¡Ah, Karl!","story.map11-dungeon2.005":"Hola, diosa.","story.map11-dungeon2.006":"¿Has encontrado alguna pista por allí?","story.map11-dungeon2.007":"Por desgracia, no.","story.map11-dungeon2.008":"En serio, <wait=20>¿dónde estará el anciano...?","story.map11-dungeon2.009":"Precisamente por hacer estas locuras a su edad acabó capturado.","story.map11-dungeon2.011":"Qué va. Se nota que solo estás preocupado por él, Karl.","story.map11-dungeon2.012":"Ja, ja. Supongo que no puedo con una diosa.","story.map11-dungeon2.013":"¡No tienes que preocuparte por él!","story.map11-dungeon2.014":"¡Seguro que Elder Grah está perfectamente!","story.map11-dungeon2.015":"Tú también estabas bien cuando te capturaron, ¿no?","story.map11-dungeon2.016":"Así que es evidente que alguien aún más grande como Elder Grah también estará bien.","story.map11-dungeon2.017":"Hay cosas de esa afirmación con las que no estoy de acuerdo...","story.map11-dungeon2.018":"Pero supongo que, aunque me preocupe por él, no va a estirar la pata tan pronto.","story.map11-dungeon2.019":"¡Gracias, diosa!","story.map11-dungeon2.020":"Pero es un poco extraño.","story.map11-dungeon2.021":"Tú...","story.map11-dungeon2.022":"Osita Paris.","story.map11-dungeon2.023":"¡¿O-Osita?!","story.map11-dungeon2.024":"Me cuesta mucho decirle esto a una diosa, pero...","story.map11-dungeon2.025":"...¿podrías dejar de llamarme \\"osita\\", por favor?","story.map11-dungeon2.026":"Puedes llamarme simplemente \\"Paris\\". No me importa.","story.map11-dungeon2.027":"Vale, de acuerdo.","story.map11-dungeon2.028":"Entonces, Paris, ¿qué haces exactamente aquí?","story.map11-dungeon2.029":"Bueno, <wait=20>yo también estoy buscando al Anciano Grahdens.","story.map11-dungeon2.030":"Así que no debería sorprenderte que me haya cruzado contigo.","story.map11-dungeon2.031":"Está bien, da igual.","story.map11-dungeon2.032":"Entonces, ¿qué es lo que te parece tan extraño de todo esto?","story.map11-dungeon2.033":"Vaya, <wait=20>¿alguien como Karl de Nyonne no sabe a qué me refiero?","story.map11-dungeon2.034":"No tengo tiempo para tus jueguecitos. Dínoslo ya.","story.map11-dungeon2.035":"Je, je, <wait=20>parece que, después de todo, eres distinto de Lugina.","story.map11-dungeon2.036":"Bueno, está bien.","story.map11-dungeon2.037":"Seguro que a ti también te parece extraño, ¿verdad?","story.map11-dungeon2.038":"¿Por qué iban los dioses a capturarlo y dejarlo con vida?","story.map11-dungeon2.039":"...","story.map11-dungeon2.040":"Si el Anciano Grahdens luchó a vuestro lado contra Zevalhua y lo capturaron en el proceso,","story.map11-dungeon2.041":"¿por qué no tienen motivos suficientes para matarlo?","story.map11-dungeon2.042":"...","story.map11-dungeon2.043":"¿Y si todo esto nos lleva a una trampa?","story.map11-dungeon2.044":"...","story.map11-dungeon2.045":"¡¿No podemos pensar en eso luego?! ¡Tenemos que rescatar a Elder Grah!","story.map11-dungeon2.046":"Tienes razón.","story.map11-dungeon2.047":"Karl, <wait=20><rep_handlename>, ","story.map11-dungeon2.048":"la diosa tiene razón. Yo también seguiré buscando al anciano.","story.map11-dungeon2.049":"Hagámoslo lo mejor posible juntos.","story.map11-dungeon2.050":"Sí, en eso tienes razón. Gracias por tu ayuda.","story.map11-dungeon2.051":"Je, je, <wait=20>total, puede que Grahdens nos resuelva ese pequeño acertijo.","story.map11-dungeon2.052":"Sí, puede que sí...","story.map11-dungeon2.053":"Je, je...","story.map11-dungeon3.001":"Vaya, <wait=20><rep_handlename>.","story.map11-dungeon3.002":"¿Ahora estás a solas?","story.map11-dungeon3.003":"Je, je, <wait=20>siento lástima por todos los Invocadores protegidos por esa diosa.","story.map11-dungeon3.004":"La última vez no pude oír tu respuesta por culpa de Lugina, pero","story.map11-dungeon3.005":"no es que me haya rendido contigo.","story.map11-dungeon3.006":"Me alegra poder luchar de nuevo a tu lado así.","story.map11-dungeon3.007":"Por eso...","story.map11-dungeon3.008":"<size=23>¡¡¡Ni hablar!!!</size>","story.map11-dungeon3.009":"<size=21>¡Paris! <wait=20><br>¡Para ya!</size>","story.map11-dungeon3.010":"<size=21>¡<rep_handlename> es mi Invocador!</size>","story.map11-dungeon3.011":"Ah, ¿así que <rep_handlename> es tu Invocador?","story.map11-dungeon3.012":"Bueno, <wait=20>¿y qué significa eso exactamente?","story.map11-dungeon3.013":"<size=20>¡Significa exactamente lo que parece!</size>","story.map11-dungeon3.014":"<size=20>¡<rep_handlename> es mi Invocador! <wait=20> ¡Y punto!</size>","story.map11-dungeon3.015":"Y-<wait=20>Ya veo...","story.map11-dungeon3.016":"<rep_handlename>...<wait=40><br>lo estás <wait=20>pasando bastante mal ahora mismo, ¿verdad?","story.map11-dungeon3.017":"Bueno, <wait=20>en cualquier caso, ya tendremos nuestra charla más adelante.","story.map11-dungeon3.018":"Por ahora iré a buscar al Anciano Grahdens.","story.map11-dungeon3.019":"También debería llegar información nueva, así que estate atento.","story.map11-dungeon3.020":"¡Ah! <wait=40>¡Paris, eso es muy injusto!","story.map11-dungeon3.021":"¡Que sepas que no pienso perder contra ti!","story.map11-dungeon3.022":"¡<rep_handlename>!","story.map11-dungeon3.023":"¡Le demostraré que será esta diosa guapa e invencible quien te encuentre, Elder Grah!","story.map11-dungeon3.024":"¡Así que no te preocupes y espérame!","story.map11-dungeon3.025":"<rep_handlename>, <wait=40><br>me das muchísima pena....","story.map11-dungeon4.001":"Tsk, eres tú.","story.map11-dungeon4.002":"Si sigues dando vueltas por aquí, es que sigues siendo el idiota de siempre.","story.map11-dungeon4.003":"¿Qué? <wait=40>¿Has dicho que los dos seguimos en el mismo sitio?","story.map11-dungeon4.004":"Tsk, <wait=20>por eso odio a los imbéciles.","story.map11-dungeon4.005":"Yo tengo un motivo de verdad para estar aquí.","story.map11-dungeon4.006":"Pero, más importante, <rep_handlename>.","story.map11-dungeon4.007":"Ten muchísimo cuidado con esa de la Guardia Imperial, Paris.","story.map11-dungeon4.008":"Esa tía <wait=20>trama algo, seguro.","story.map11-dungeon4.009":"Eso de que los nobles del Imperio de Randall colaboran con el Salón de Invocadores de Akras y demás...","story.map11-dungeon4.010":"es imposible que sea verdad.","story.map11-dungeon4.011":"Y seguro que también tiene un motivo para interesarse tanto por ti...","story.map11-dungeon4.012":"<size=23>¡Eh, imbéciles!</size>","story.map11-dungeon4.013":"<size=23>¡¿Qué hacéis ahí parados?!</size>","story.map11-dungeon4.014":"Tsk, y ahora aparece una tía aún más pesada.","story.map11-dungeon4.015":"<size=20>¡¿A quién llamas tía pesada?!</size>","story.map11-dungeon4.016":"<size=16>¡No es momento de cotorrear! ¡El Anciano Grahdens necesita nuestra ayuda!</size>","story.map11-dungeon4.017":"Os lleváis tan bien que me dais escalofríos...","story.map11-dungeon4.018":"<size=21>¡¿Quién se lleva bien?! <wait=40><br>¡Imbécil!</size>","story.map11-dungeon4.019":"<size=22>¡¿A quién llamas imbécil?!</size>","story.map11-dungeon4.020":"<size=21>¡No te hagas el importante, que tenías la cabeza enterrada en el suelo!</size>","story.map11-dungeon4.021":"Grr, <wait=20>eso fue culpa de esa diosa rara...","story.map11-dungeon4.022":"¡Lugy, deberías esforzarte un poco más!","story.map11-dungeon4.023":"<size=23>¡Voy a darle una paliza a esta niña tonta!</size>","story.map11-dungeon4.024":"<size=21>¡Oye, <rep_handlename>!</size>","story.map11-dungeon4.025":"<size=21>¡¿Adónde te escapas?!</size>","story.map11-dungeon4.026":"<size=18>¡Espera, <rep_handlename>! ¡¿Adónde vas?!</size>","story.map11-dungeon4.027":"<size=16>¡No me dejes con estos dos bichos raros!</size>","story.map11-dungeon4.028":"<size=14>¡No sé qué acabarán haciéndome!</size>","story.map11-dungeon4.029":"<size=12>¡Como si yo quisiera hacerte algo!</size>","story.map11-dungeon4.030":"<size=10>¡¿Y eso qué se supone que significa?!</size>","story.map11-dungeon4.031":"<size=9>¡¿No lo pillas?!</size><wait=20><br><size=9>¡Qué idiota!</size>","story.map11-dungeon4.032":"<size=8>¡Cállate!</size><wait=20><br><size=8>¡Perdedor!</size>","story.map11-dungeon5.001":"¡¡<rep_handlename>!!<wait=40> ¡¡Escucha, escucha!!","story.map11-dungeon5.002":"¡Ya sé <wait=20>dónde está Elder Grah!","story.map11-dungeon5.003":"Pues, esto... <wait=20>Parece que está en un lugar llamado la \\"Torre de los Dioses\\".","story.map11-dungeon5.004":"Zevalhua ha convertido la Torre de los Dioses en su base.","story.map11-dungeon5.005":"Así que, en resumen, <wait=20>si vamos a esa torre","story.map11-dungeon5.006":"podremos derrotar a Zevalhua <wait=20>y, de paso, rescatar a Elder Grah.","story.map11-dungeon5.007":"¡Así que diles a Karl y a los demás que vayan hacia la Torre de los Dioses!","story.map11-dungeon5.008":"No esperaba menos de la sierva de Lord Lucius, la señorita Tilith.","story.map11-dungeon5.009":"Ah, <wait=20>¡Paris!","story.map11-dungeon5.010":"Je, je, je, <wait=20>soy bastante buena, ¿verdad?","story.map11-dungeon5.011":"Pues sí.<wait=20><br>Como era de esperar de una diosa.","story.map11-dungeon5.012":"Pero <wait=20>¿cómo descubriste dónde está el Anciano Grahdens?","story.map11-dungeon5.013":"Bueno...","story.map11-dungeon5.014":"Hay otro siervo de Lord Lucius, como yo, que estaba vigilando a Zevalhua.","story.map11-dungeon5.015":"Ese siervo fue a la Torre de los Dioses e informó de que vio a un anciano encerrado en una sala.","story.map11-dungeon5.016":"Ya veo. <wait=20><br>Ahora lo entiendo...","story.map11-dungeon5.017":"¡Lord Lucius <wait=20>sigue reuniendo a un montón de siervos divinos increíbles!","story.map11-dungeon5.018":"Por supuesto, yo también entro en esa categoría.","story.map11-dungeon5.019":"Sí, sé muy bien que posees poderes asombrosos, diosa.","story.map11-dungeon5.020":"Pero <wait=20>es curioso.","story.map11-dungeon5.021":"¿Eh? <wait=20>¿El qué?","story.map11-dungeon5.022":"Si tiene tantos seres divinos excelentes de su lado,","story.map11-dungeon5.023":"¿por qué no va él mismo a por los Dioses Caídos?","story.map11-dungeon5.024":"Esto, <wait=20>bueno...","story.map11-dungeon5.025":"Y además, <wait=20>el mensajero del dios supremo,","story.map11-dungeon5.026":"el Sagrado Emperador Karna Masta, también despierta mi curiosidad.","story.map11-dungeon5.027":"Aunque Grand Gaia está en apuros, no ha mostrado ninguna intención de hacer nada al respecto.","story.map11-dungeon5.028":"Si Lord Lucius y Karna Masta trabajan juntos, no tienen ninguna necesidad de nosotros, los humanos.","story.map11-dungeon5.029":"Me da la impresión de que podrían derrotar fácilmente ellos solos a los dos Dioses Caídos que quedan.","story.map11-dungeon5.030":"Bueno... <wait=40><br>Eh, <wait=20>esto...","story.map11-dungeon5.031":"¿Será que Lord Lucius y los demás no pueden moverse libremente por sí mismos?","story.map11-dungeon5.032":"Por ejemplo, <wait=20>quizá, tras ser derrotado antes por los Cuatro Dioses Caídos, quedó sellado por algún poder, o...","story.map11-dungeon5.033":"¡No... <wait=20>No es eso!","story.map11-dungeon5.034":"¡Lord Lucius está estupendamente!","story.map11-dungeon5.035":"No puedo contártelo todo, pero ahora mismo no puede moverse mucho...","story.map11-dungeon5.036":"¡Y...<wait=20>Y a Karna Masta le pasa lo mismo!","story.map11-dungeon5.037":"¡Pero no es que estén sellados en ningún sitio!","story.map11-dungeon5.038":"Te pido disculpas.","story.map11-dungeon5.039":"Te ruego que perdones a esta humana necia y desconfiada.","story.map11-dungeon5.040":"Una tonta como yo no puede aspirar a entender las grandes ideas de los dioses.","story.map11-dungeon5.041":"No soy más que una persona que siempre tiene miedo.","story.map11-dungeon5.042":"No, <wait=20>no pasa nada.","story.map11-dungeon5.043":"Nunca pensé que me preguntarías algo así, así que me has pillado desprevenida.","story.map11-dungeon5.044":"Solo tus palabras ya me han ayudado mucho.","story.map11-dungeon5.045":"Bueno, <wait=20>deberíamos ir a rescatar al Anciano Grahdens.","story.map11-dungeon5.046":"Parece que Karl y los demás se han adelantado hacia la ciudad en ruinas de Mirvana.","story.map11-dungeon5.047":"V-<wait=20>Vale. <wait=40><br>¡Eso es!","story.map11-dungeon5.048":"¡Tenemos que decirles a Karl y a los demás dónde está Elder Grah lo antes posible!","story.map11-dungeon5.049":"¡Muy bien, <rep_handlename>! <wait=40> ¡En marcha!","story.map11-dungeon6.001":"Ah, <wait=20>¡Karl!","story.map11-dungeon6.002":"Hola, <wait=20>diosa y <rep_handlename>.","story.map11-dungeon6.003":"Os estábamos esperando.","story.map11-dungeon6.004":"Parece que habéis averiguado dónde está el Anciano Grahdens, ¿eh?","story.map11-dungeon6.005":"Muchas gracias.","story.map11-dungeon6.006":"Oye, <wait=20>¿cómo lo sabías?","story.map11-dungeon6.007":"Paris pasó por aquí antes <wait=20>y nos lo contó.","story.map11-dungeon6.008":"¡¿Quéééé?!<wait=40> ¡¡Paris, tonta!!","story.map11-dungeon6.009":"¡¡Quería ser yo quien les diera la sorpresa!!","story.map11-dungeon6.010":"Pero oye, <wait=20>¿dónde está Paris ahora?","story.map11-dungeon6.011":"Pues <wait=20>dijo que había algo que le daba curiosidad, así que se adelantó a la Torre de los Dioses.","story.map11-dungeon6.012":"Ya veo...","story.map11-dungeon6.013":"¿Qué será <wait=20> eso que tanto le intriga...?","story.map11-dungeon6.014":"Diosa, <wait=40>¿qué te pasa?","story.map11-dungeon6.015":"No tienes muy buena cara.<wait=20> ¿Ha pasado algo?","story.map11-dungeon6.016":"¡N-<wait=20>No, no es nada!","story.map11-dungeon6.017":"¡Siempre estoy llena de energía!","story.map11-dungeon6.018":"¿A que sí, <wait=20><rep_handlename>?","story.map11-dungeon6.019":"Muy bien.","story.map11-dungeon6.020":"Bueno, <wait=20>cuando salvemos al Anciano Grahdens pienso hacer que nos cuente toda la historia.","story.map11-dungeon6.021":"Ese viejo... <wait=20>Tengo la sensación de que todavía nos oculta muchas cosas.","story.map11-dungeon6.022":"Librar a la diosa de sus preocupaciones podría sernos útil a la larga.","story.map11-dungeon6.023":"Karl es un tipo genial.","story.map11-dungeon6.024":"¡Pero claro, así son los amigos de <rep_handlename>!","story.map11-dungeon6.025":"Jaja. <wait=20>Si lo dices así delante de mí, me sonrojo un poco.","story.map11-dungeon6.026":"Además, <wait=20>cambiando de tema...","story.map11-dungeon6.027":"¿Y qué tal va aquello?","story.map11-dungeon6.028":"¿Aquello...?","story.map11-dungeon6.029":"Bueno, <wait=20>igual que siempre. <wait=40><br>Así que no te preocupes...","story.map11-dungeon6.030":"¡Ya veo! <wait=20><br>Igual que siempre, ¿eh?","story.map11-dungeon6.031":"Bueno, entonces <wait=20>no me preocuparé.","story.map11-dungeon6.032":"¡Ya te lo he dicho! <wait=20>¡Voy a ser la primera en llegar a la Torre de los Dioses!","story.map11-dungeon6.033":"¡Eso no lo sabes!","story.map11-dungeon6.034":"¡Tú deberías quedarte en la entrada vigilando!","story.map11-dungeon6.035":"<size=18>¡¿Por qué tengo que ser yo la que monte guardia?!</size>","story.map11-dungeon6.036":"Porque es el trabajo perfecto para una tonta como tú.","story.map11-dungeon6.037":"<size=18>¡No soy tonta!</size>","story.map11-dungeon6.038":"¡Vigilar también es un trabajo importante!","story.map11-dungeon6.039":"¡Si no entiendes eso, vas a fracasar en un montón de misiones en el futuro!","story.map11-dungeon6.040":"<size=18>¡¿Qué me has dicho?!</size>","story.map11-dungeon6.041":"Si vigilar es un trabajo tan importante, ¡¿por qué no lo haces tú?!","story.map11-dungeon6.042":"¡Eso no tiene nada que ver!","story.map11-dungeon6.043":"Madre mía. <wait=20>Estos dos me ponen de los nervios...","story.map11-dungeon7.001":"¡Por fin, <wait=40><br><rep_handlename>!","story.map11-dungeon7.002":"Elder Grah está aquí,","story.map11-dungeon7.003":"y también uno de los Cuatro Dioses Caídos, \\"el Emperador Divino Zevalhua\\".","story.map11-dungeon7.004":"Siento un poder inmenso ahí fuera...","story.map11-dungeon7.005":"Supongo que no es de extrañar viniendo de uno de los Dioses Caídos.","story.map11-dungeon7.006":"Bah, <wait=20>me da igual lo grande que sea; si me molesta, lo haré pedazos.","story.map11-dungeon7.007":"Pero oye, <wait=20>¿dónde está esa señora de la Guardia Imperial?","story.map11-dungeon7.008":"No parece que esté por aquí.","story.map11-dungeon7.009":"Ja, <wait=20>parece que no se puede confiar en los soldados del Ejército Imperial de Randall.","story.map11-dungeon7.010":"Pero <wait=20>ella también tiene su propia misión que cumplir.","story.map11-dungeon7.011":"Parece que anda muy ocupada de aquí para allá.","story.map11-dungeon7.012":"Incluso le intriga el motivo por el que capturaron al anciano...","story.map11-dungeon7.013":"¡Karl!","story.map11-dungeon7.014":"¡Ahora no tenemos tiempo para pensar en eso!","story.map11-dungeon7.015":"¡Tenemos que darnos prisa y rescatar a Elder Grah antes de que sea tarde!","story.map11-dungeon7.016":"Tienes razón. <wait=40><br>Es tal como dice la diosa.","story.map11-dungeon7.017":"¡No sirve de nada pensar en eso ahora!","story.map11-dungeon7.018":"Bueno, entonces, <wait=20>¡separémonos e intentemos encontrar al anciano!","story.map11-dungeon7.019":"La verdad es que me gustaría que nos reagrupáramos antes de luchar contra Zevalhua, pero","story.map11-dungeon7.020":"según cómo vaya la cosa, puede que no podamos. Si hace falta, tendremos que enfrentarnos a él por separado.","story.map11-dungeon7.021":"No hay problema.","story.map11-dungeon7.022":"¡Aunque resulte que no es el auténtico, o que es una trampa, plantaré cara igualmente!","story.map11-dungeon7.023":"¡Ja! <wait=20>Nunca he esperado mucho de vuestro poder.","story.map11-dungeon7.024":"<rep_handlename>, <wait=20>volvemos a contar con tu poder.","story.map11-dungeon7.025":"Muy bien, <wait=20>¡que no os maten ahí fuera!","story.map11-dungeon7.026":"Esto es...","story.map11-dungeon7.027":"Supongo que no me queda más remedio que cambiar mis planes originales...","story.map11-ending.001":"¡Lo conseguimos, <wait=40><br><rep_handlename>!","story.map11-ending.002":"¡Y pensar que has derrotado incluso a Zevalhua! ¡Eres increíble, <rep_handlename>!","story.map11-ending.003":"Y Karl y el anciano están...","story.map11-ending.005":"*Uf* *uf* *uf* <wait=40><br><rep_handlename>...","story.map11-ending.006":"*Puf*<wait=40><br>*Uf*","story.map11-ending.007":"¡Vaya, lo has conseguido!","story.map11-ending.008":"Sentí que un poder inmenso se hacía aún más fuerte, así que vine corriendo,","story.map11-ending.009":"pero parece que no hacía falta correr...","story.map11-ending.010":"Maldita sea, <wait=20>parece que no he llegado a tiempo.","story.map11-ending.011":"¡<rep_handlename>!","story.map11-ending.012":"Desgraciado, <wait=20>te has divertido tú solo, ¿verdad?","story.map11-ending.013":"¡Por eso no me caes bien!","story.map11-ending.014":"¡Oh, <wait=20>parece que todos habéis salido ilesos!","story.map11-ending.015":"¡<rep_handlename>!","story.map11-ending.016":"¡Sabía que derrotarías a Zevalhua! Al fin y al cabo, eres mi amigo.","story.map11-ending.017":"Me alegra ver que todos estáis sanos y salvos.","story.map11-ending.018":"Entonces, <wait=20>¿habéis encontrado a Elder Grah?","story.map11-ending.019":"¿No está aquí?","story.map11-ending.020":"No estaba en ninguna de las otras salas,","story.map11-ending.021":"así que estaba segura de que estaría aquí, porque era la única sala que quedaba por revisar. Por eso vine corriendo.","story.map11-ending.022":"Uf, <wait=20>ahora tenemos que lidiar con más rollos molestos.","story.map11-ending.023":"Espero que el Anciano Grahdens <wait=20>esté a salvo en algún lugar...","story.map11-ending.024":"Ay, <wait=20>perdona, Karl. <wait=20> No quería decirlo así...","story.map11-ending.025":"Nah, no pasa nada.","story.map11-ending.026":"No hay rastro que indique <wait=20>que haya estado aquí, así que","story.map11-ending.027":"seguramente escapó por su cuenta.","story.map11-ending.028":"Jo, jo, jo. <wait=40><br>Exactamente.","story.map11-ending.029":"¡Esa voz!","story.map11-ending.030":"¡Elder Grah!","story.map11-ending.031":"Jo, jo, jo.","story.map11-ending.032":"Parece que os he causado bastantes problemas a todos.","story.map11-ending.033":"Anciano Grahdens...","story.map11-ending.034":"No pongas esa cara de niño.","story.map11-ending.035":"Puede que te haya preocupado, <wait=20><br>pero todavía no me he vuelto un debilucho.","story.map11-ending.036":"¡¿Q-Quién estaba preocupado por ti?!","story.map11-ending.037":"Y lo más importante, <wait=20>¡¿qué has estado haciendo todo este tiempo, y dónde?!","story.map11-ending.038":"¡Explícales a todos por qué hemos tenido que ir de un lado a otro buscándote!","story.map11-ending.039":"Hum, <wait=20>bueno, he hecho algo malo.","story.map11-ending.040":"Había algo en esta torre que me inquietaba, <wait=20>solo un poco.","story.map11-ending.041":"Fingí que me capturaba esa Diosa Caída, Mare-no-sé-qué, e hice que me trajera aquí.","story.map11-ending.042":"Quizá <wait=20>esperaba que capturarme le diera ventaja sobre todos vosotros en la batalla.","story.map11-ending.043":"Pero antes de que Mare pudiera aprovecharlo, la derrotasteis vosotros.","story.map11-ending.044":"Como había obtenido conocimientos sobre Zevalhua y Afla Dilith tras luchar con ellos,","story.map11-ending.045":"no quería enfrentarme a ella yo mismo.","story.map11-ending.046":"Pero, tal como esperaba, <wait=20>dejar que me capturara trajo vuestra ayuda.","story.map11-ending.047":"Y gracias a eso tuve tiempo de sobra para investigar con calma.","story.map11-ending.048":"En ese caso, <wait=20>deberías habérnoslo dicho y ya está.","story.map11-ending.049":"Viejo pesado.","story.map11-ending.050":"Jo, jo, jo. <wait=40>Lo siento, Lugina.","story.map11-ending.051":"Estoy en deuda contigo por lo que has hecho.","story.map11-ending.052":"Te recompensaré como es debido.","story.map11-ending.053":"Más te vale.","story.map11-ending.054":"Y no solo eso, <wait=20>también tienes que contarles a otras personas importantes <wait=20>todo lo que he hecho.","story.map11-ending.055":"En serio, <wait=20>ese tipo no tiene clase.","story.map11-ending.056":"¡Mira quién habla!","story.map11-ending.057":"Bueno, <wait=20>anciano.<wait=40> Ya sabes lo que quiero preguntarte, ¿no?","story.map11-ending.058":"Hum. <wait=40>Sobre tu origen, ¿me equivoco?","story.map11-ending.059":"Está escrito en mi testamento. ¿No puedes esperar hasta entonces para leerlo?","story.map11-ending.060":"Ni hablar.","story.map11-ending.061":"Jo, jo, jo. <wait=40>Era broma. <wait=20>No hace falta enfadarse tanto.","story.map11-ending.062":"Pero <wait=20>tampoco es un gran secreto.","story.map11-ending.063":"Karl.","story.map11-ending.064":"Te encontré de bebé y te crié. Eso lo sabes, ¿verdad?","story.map11-ending.065":"Sí, <wait=20>y te lo agradezco.","story.map11-ending.066":"Pero <wait=20>¿tiene algo de especial el lugar donde me encontraste?","story.map11-ending.067":"Hum. <wait=20><br>Bueno, sí.","story.map11-ending.068":"Creo que tú mismo lo habrás intuido vagamente, <wait=20><br>pero te encontré en Grand Gaia.","story.map11-ending.069":"Espera, <wait=20>¡¿qué?!","story.map11-ending.070":"Tsk, <wait=20>así que es eso.","story.map11-ending.071":"...","story.map11-ending.072":"Pero <wait=20>¿no se suponía que en Grand Gaia no había supervivientes humanos...?","story.map11-ending.073":"Ni yo mismo lo entiendo.","story.map11-ending.074":"Vine aquí con otros Invocadores y, mientras inspeccionábamos la zona,","story.map11-ending.075":"encontramos a un bebé en las ruinas de Mistral.","story.map11-ending.076":"Y así, <wait=40>nos lo llevamos con nosotros de vuelta a Elgaia.","story.map11-ending.077":"Eso es todo.","story.map11-ending.078":"No tenía ni idea de qué clase de ser era realmente aquel bebé.","story.map11-ending.079":"Karl.","story.map11-ending.080":"No sé si eres un huérfano superviviente de Grand Gaia, ","story.map11-ending.081":"o si eres un hijo de los dioses.","story.map11-ending.082":"Sin embargo...","story.map11-ending.083":"Anciano. <wait=40><br>No hace falta que me digas nada más.","story.map11-ending.084":"Porque te estoy muy agradecido a ti y a todos los demás Invocadores.","story.map11-ending.085":"...","story.map11-ending.086":"Karl...","story.map11-ending.087":"Vaya, así que Karl guardaba un secreto así, ¿eh?","story.map11-ending.088":"Mmm... <wait=40>Un bebé abandonado en Grand Gaia.","story.map11-ending.089":"Nunca había oído nada parecido.","story.map11-ending.090":"Me pregunto si Lord Lucius sabrá algo de esto.","story.map11-ending.091":"Creo que <wait=20>¡voy a ir a preguntarle!","story.map11-ending.092":"¡<rep_handlename>!","story.map11-ending.093":"Bueno, solo nos queda un Dios Caído del que ocuparnos, ¡y es el Dios Bestia Afla Dilith!","story.map11-ending.094":"¡Seguro que podemos derrotarlo si trabajamos todos juntos!","story.map11-ending.095":"Y, por supuesto, <wait=20>también contamos con tus poderes de Invocador, <rep_handlename>.","story.map11-ending.096":"Bueno, entonces, <wait=20>¡iré a preguntar por Karl y os lo contaré la próxima vez!","story.map11-ending.097":"¡Ah, <wait=20>espera! <wait=20><br>¡Diosa!","story.map11-ending.098":"Quería decirle que en realidad no me importa...","story.map11-ending.099":"No escucha, ¿verdad?","story.map11-ending.100":"Jo, jo, jo. <wait=40><br>Eso es porque Tilith es una buena chica.","story.map11-ending.101":"Bueno, <wait=20>¿qué hacemos con esa presencia maligna que apareció después de que se fuera la diosa?","story.map11-ending.102":"Soy muy duro con las presencias malignas.","story.map11-ending.103":"Tú eres...","story.map11-ending.104":"Soy Eriole.","story.map11-ending.105":"Vengo del Imperio de Randall,","story.map11-ending.106":"donde sirvo como comandante de la Guardia Imperial, que protege a la Familia Imperial.","story.map11-ending.107":"Je, <wait=20>he oído rumores sobre ese nombre.","story.map11-ending.108":"Rumores que dicen que es un tipo desagradable que se convirtió en el comandante más joven de la historia.","story.map11-ending.109":"¡Qué grosero!","story.map11-ending.110":"¡Anda, <wait=20>ha vuelto la señora que tenía demasiado miedo de enfrentarse a los Cuatro Dioses Caídos!","story.map11-ending.111":"Este hombre es un...","story.map11-ending.112":"Paris, retrocede un poco.","story.map11-ending.113":"¿Qué? <wait=20>P-<wait=20>Pero...","story.map11-ending.114":"Paris.","story.map11-ending.115":"E-<wait=20>Entendido...","story.map11-ending.116":"Bueno, <wait=20>¿qué quiere exactamente de nosotros el comandante de la Guardia Imperial?","story.map11-ending.117":"También te agradecería que nos explicaras quién es esa persona tan aterradora que tienes detrás.","story.map11-ending.118":"...","story.map11-ending.119":"Esta persona es mi colaborador. <wait=40><br>No os preocupéis por él.","story.map11-ending.120":"Seguro que habéis oído muchas cosas de mi subordinada, Paris.","story.map11-ending.121":"Quería hablar con todos vosotros al menos una vez,","story.map11-ending.122":"pero, como enviado del Emperador de Randall,","story.map11-ending.123":"esta vez he venido a hablar específicamente con el Invocador Grahdens.","story.map11-ending.124":"Jo, jo, jo.","story.map11-ending.125":"Si solo querías hablar conmigo, <wait=20>no hacía falta que vinieras hasta aquí, ¿sabes?","story.map11-ending.126":"Ja, ja, ja.","story.map11-ending.127":"Tenemos nuestros motivos para hacerlo.","story.map11-ending.128":"Os lo explicaremos en detalle más tarde.","story.map11-ending.129":"¿Pensáis llevaros al anciano con vosotros?","story.map11-ending.130":"¿De verdad creéis que se irá sin rechistar?","story.map11-ending.131":"Por favor, no nos malinterpretéis.","story.map11-ending.132":"No hemos venido a luchar.","story.map11-ending.133":"Lo sé.","story.map11-ending.134":"Al fin y al cabo, si me pasara algo, os resultaría muy inconveniente.","story.map11-ending.135":"...","story.map11-ending.136":"Disculpadme, <wait=20>todos. <wait=40><br>Voy a charlar un momento con estos señores.","story.map11-ending.137":"Quería daros las gracias como es debido, pero parece que tendrá que esperar a la próxima vez.","story.map11-ending.138":"Karl.","story.map11-ending.139":"Esta vez me ha alegrado ver<wait=20> cuánto has crecido.","story.map11-ending.140":"Anciano Grahdens...","story.map11-ending.141":"Y tú, <rep_handlename>.","story.map11-ending.142":"Hiciste un buen trabajo derrotando a Zevalhua.","story.map11-ending.143":"Sin embargo, <wait=20>la próxima vez te enfrentarás a Afla Dilith.","story.map11-ending.144":"Y, a diferencia de los otros Dioses Caídos, seguro que él estará preparado para luchar contra ti.","story.map11-ending.145":"No me cabe duda de que será una batalla difícil, pero debes ponerte a prueba a ti y a tus amigos.","story.map11-ending.146":"Además, <wait=20>dejo a Karl en tus manos.","story.map11-ending.147":"Creo que quizá ya lo sepas, pero","story.map11-ending.148":"aún le faltan algunas piezas aquí y allá, así que me preocupa.","story.map11-ending.149":"No necesito que nadie cuide de mí...","story.map11-ending.150":"Jo, jo, jo.","story.map11-ending.151":"Bueno, enviado del Imperio de Randall, <wait=40><br>¿nos ponemos en marcha?","story.map11-ending.152":"Te agradezco<wait=20> tanto tu consideración como tu comprensión.","story.map11-ending.153":"Paris, <wait=40>vámonos.","story.map11-ending.154":"¡Sí, señor!","story.map11-ending.155":"Se ha ido así sin más, ¿eh?","story.map11-ending.156":"Siendo el Anciano Grahdens, seguro que estará bien. Pero aun así...","story.map11-ending.157":"Hum. <wait=20>Esos del Imperio de Randall no pueden ponerle un dedo encima al viejo Invocador.","story.map11-ending.158":"Tienes razón.","story.map11-ending.159":"Al fin y al cabo, hablamos del Anciano Grahdens. <wait=40><br>Seguro que estará bien.","story.map11-ending.160":"Lo más importante <wait=20>es que nos centremos en cómo podemos ayudar desde nuestro lado.","story.map11-ending.161":"<rep_handlename>,","story.map11-ending.162":"vas a luchar contra Afla Dilith, <wait=20> el último de los Cuatro Dioses Caídos, <wait=20>¿verdad?","story.map11-ending.163":"La verdad es que Seria y yo queremos echarte una mano, pero tampoco podemos ignorar al demonio Graham.","story.map11-ending.164":"¡Es verdad! <wait=40><br>¡Me había olvidado por completo de él!","story.map11-ending.165":"Si no lo derrotamos...","story.map11-ending.166":"¡<rep_handlename>!","story.map11-ending.167":"Vamos a tener que separarnos, <wait=20><br>pero estarás bien, ¿verdad?","story.map11-ending.168":"Vamos a derrotar a Graham y volveremos enseguida, ¡así que cuídate!","story.map11-ending.169":"Vaya, vaya... <wait=20>Parece que la gran demonio Seria también tiene su lado amable.","story.map11-ending.170":"¡Idio-- <wait=20>Imbé-- <wait=20>Eso es lo que hay que decir en momentos así!","story.map11-ending.171":"¡Oye, <rep_handlename>!","story.map11-ending.172":"No intentes llevarte todo el mérito <wait=20>de haber derrotado a Zevalhua tú solo.","story.map11-ending.173":"Tampoco olvides todo lo <wait=40><br>que he hecho yo.","story.map11-ending.174":"Que te salve o no la próxima vez puede depender de lo agradecido que me estés.","story.map11-ending.175":"Jaja, <wait=20>así es Lugina.","story.map11-ending.176":"<rep_handlename>, <wait=40><br>tenemos que irnos ya.","story.map11-ending.177":"Si vuelves a ver a la diosa, dile que le estoy muy agradecido por su ayuda.","story.map11-ending.178":"Y <wait=20>si oyes algo sobre mí y quieres hablarme de ello, eso ya depende de ti.","story.map11-ending.179":"Porque si eres tú quien me lo cuenta, <wait=20>estoy seguro de que podré afrontar cualquier verdad.","story.map11-ending.180":"Bueno, <wait=20>espero verte la próxima vez.","story.map11-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Soy Lucius...<wait=40><br>Dios que gobierna esta Puerta...","story.map11-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Libertador de Agni...<wait=40><br><rep_handlename>...","story.map11-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Usa mi poder...<wait=40><br>y emprende el viaje hacia una nueva tierra...","story.map11-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>para llevar nuestra palabra<wait=40><br>a este mundo sumido en el caos...","story.map11-open.005":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Ten fe en ti<wait=20><br>y sigue avanzando...","story.map11-open.006":"¡<rep_handlename>! <wait=40><br>¡Ya es la hora!","story.map11-open.007":"Esto es Mirvana, la región donde Zevalhua estableció su base durante la batalla contra los dioses.","story.map11-open.008":"Parece que por eso <wait=20>la región de Agni se convirtió en el mayor campo de batalla de la guerra.","story.map11-open.009":"Qué paisaje tan lúgubre hay por aquí...","story.map11-open.010":"¡Ay! <wait=20>¡Perdón, perdón!","story.map11-open.011":"¡No es momento de ponerse sentimental!","story.map11-open.013":"Bueno, <wait=20>¡vamos a derrotar a Zevalhua y a rescatar a Elder Grah!","story.map11-open.014":"Sé que podemos contar contigo sin falta, <rep_handlename>. ¡Creo en ti!","story.map2-dungeon1.001":"<size=22>¡¿Eh?! ¡¡<rep_handlename>!!","story.map2-dungeon1.002":"¡No me lo puedo creer, <wait=20>jamás pensé que nos veríamos en un sitio así!","story.map2-dungeon1.003":"Ya veo, <wait=40>tú también vas a la Torre de Morgan, ¿no?","story.map2-dungeon1.004":"Seguro que también vas con el Ejército de Invocadores tras los Cuatro Dioses Caídos...","story.map2-dungeon1.005":"¿No? <wait=40>¿Te dijo Tilith que vinieras?","story.map2-dungeon1.006":"Ah, <wait=20>debe de ser la chica de la que me hablaste.","story.map2-dungeon1.007":"Se ve que te cuida bien.  <wait=20>Tendré que saludarla con educación cuando nos veamos. <wait=19>Nos presentarás, ¿eh?","story.map2-dungeon1.008":"¿Eh? <wait=20>¿No está aquí? <wait=40>¿Tú también la buscas?","story.map2-dungeon1.009":"Mmm... <wait=40>Bueno, <wait=40>supongo que no hace falta preguntar más.","story.map2-dungeon1.010":"Nosotros, los Cazademonios, vamos tras el demonio Graham.","story.map2-dungeon1.011":"Lo hemos acorralado varias veces, <wait=20>pero siempre consigue escapar...","story.map2-dungeon1.012":"Huyó hacia el desierto, así que estamos a punto de entrar a buscarlo.","story.map2-dungeon1.013":"En fin, <wait=20>¿nos ponemos en marcha?","story.map2-dungeon1.014":"Por cierto, <wait=40>en este desierto hace un calor tremendo, ten mucho cuidado.","story.map2-dungeon1.015":"¡Y estate atento, que hace poco han visto a un zoquete agitando una espada en llamas por ahí!","story.map2-dungeon1.016":"Ten cuidado, <wait=20>¡y nos vemos pronto!","story.map2-dungeon2.001":"¡¡Oh, <rep_handlename>!!","story.map2-dungeon2.002":"¿Lo notas? <wait=40>¿A que la brisa marina de aquí es increíble?","story.map2-dungeon2.003":"¿Eh? <wait=40>¿Que por qué estamos aquí?","story.map2-dungeon2.004":"Porque allí hacía demasiado calor...","story.map2-dungeon2.005":"<size=22>¡Ah! <wait=40>¡¡Retiro lo dicho!!","story.map2-dungeon2.006":"No estamos aquí solo por el calor...","story.map2-dungeon2.007":"¡De verdad tengo asuntos que atender aquí! <wait=40>¡Y deja ya esa cara de desconfianza!","story.map2-dungeon2.008":"¡Bueno, me tengo que ir! <wait=40>Te alcanzaré cuando termine con mis asuntos.","story.map2-dungeon2.009":"¡Ve tú delante, <rep_handlename>!<br><wait=40>No lo dejes para luego, ¿vale?","story.map2-dungeon2.010":"Por cierto, <wait=40>parece que en esta playa hay una espadachina enemiga, ¡y dicen que controla el aire gélido!","story.map2-dungeon2.011":"También dicen que es guapa, ¡pero yo sé que soy mucho más mona que ella!","story.map2-dungeon2.012":"Asegúrate de derrotarla, <wait=20>¡y date prisa, ¿eh?!","story.map2-dungeon2.013":"En fin, <wait=20>¡te espero aquí! <wait=40>¡Buena suerte!","story.map2-dungeon3.001":"¡¿Eres tú, <rep_handlename>?!<br><wait=40>¡¿Has visto a Graham?!","story.map2-dungeon3.002":"Ah, <wait=20>no lo has visto... <wait=40>Maldita sea... <wait=40>Argh...","story.map2-dungeon3.003":"Ah, <wait=20>no te preocupes. <wait=40>No es más que un rasguño, nada grave...","story.map2-dungeon3.004":"Pero lo peor es <wait=20>que casi todos mis compañeros han caído...","story.map2-dungeon3.005":"Graham... <wait=30>Ahora está en el Bosque Nocturno.","story.map2-dungeon3.006":"Al parecer, este bosque es el territorio de uno de los caballeros de Graham.","story.map2-dungeon3.007":"Ese caballero conoce las sombras del bosque como la palma de su mano y aprovecha la poca visibilidad a su favor.","story.map2-dungeon3.008":"Está acabando con los Invocadores uno a uno.","story.map2-dungeon3.009":"Si logramos derrotar a ese caballero, quizá podamos sacar a Graham del bosque.","story.map2-dungeon3.010":"Lo único que sé es que ese caballero lucha con lanza.","story.map2-dungeon3.011":"Tal como están las cosas, los Cazademonios poco más podemos hacer que cercar a Graham...","story.map2-dungeon3.012":"Y no pienso quedarme de brazos cruzados mientras mis compañeros caen uno tras otro.","story.map2-dungeon3.013":"Pase lo que pase, ¡lo sacaré de este bosque aunque tenga que hacerlo yo solo!","story.map2-dungeon3.014":"Bueno, deberíamos ponernos en marcha.<br><wait=40>¡Espero que tú también lo des todo!","story.map2-dungeon4.001":"¡Eh, <wait=20><rep_handlename>!<br><wait=40>¡Me alegra verte de una pieza!","story.map2-dungeon4.002":"Bueno, <wait=20>¡tampoco es que pensara que ibas a perder contra alguien así!","story.map2-dungeon4.003":"Vas a la Torre de Morgan, ¿verdad?","story.map2-dungeon4.004":"En ese caso, tendrás que cruzar los Páramos de Asekutt.","story.map2-dungeon4.005":"Las bestias que merodean por los páramos de Asekutt son bastante fuertes.","story.map2-dungeon4.006":"Sería peligroso que tus unidades tuvieran desventaja de elemento contra esas bestias, así que ten cuidado.","story.map2-dungeon4.007":"¿Mmm? <wait=40>¿Te preocupa cómo nos va a nosotros?","story.map2-dungeon4.008":"Bueno, de algún modo conseguí sacar a Graham del bosque.","story.map2-dungeon4.009":"Pero, a diferencia del Bosque Nocturno, Asekutt es campo abierto.","story.map2-dungeon4.010":"No podrá huir y esconderse como hizo en el Bosque Nocturno.","story.map2-dungeon4.011":"Aunque nuestro equipo de Cazademonios ha quedado reducido a la mitad...","story.map2-dungeon4.012":"Pienso zanjar esto de una vez por todas en Asekutt.","story.map2-dungeon4.013":"Es por mis compañeros, <wait=40>por su sacrificio.","story.map2-dungeon4.014":"Así que, por desgracia, <wait=40>no puedo ir contigo.","story.map2-dungeon4.015":"Pero confío plenamente en que derrotarás a Maxwell.","story.map2-dungeon4.016":"¡Hasta luego!","story.map2-dungeon5.001":"Hola, <rep_handlename>.<br><wait=40>Graham ha vuelto a escapar...","story.map2-dungeon5.002":"¡Maldición, <wait=40>estuvimos tan cerca!","story.map2-dungeon5.003":"Y he perdido aún más compañeros... <wait=40>Juro que lo aplastaré cuando le ponga las manos encima.","story.map2-dungeon5.004":"...<wait=20>Pero ahora los Cazademonios somos muy pocos.","story.map2-dungeon5.005":"Así que volvemos al Salón de Invocadores a por refuerzos.","story.map2-dungeon5.006":"También había quedado con ella aquí, pero...","story.map2-dungeon5.007":"¡Ah, <wait=20>ahí está!","story.map2-dungeon5.008":"Vaya, Seria, <wait=40>te veo con energía, ¿eh?","story.map2-dungeon5.009":"¡Karl! <wait=40>¡No es momento para charlas!","story.map2-dungeon5.010":"¡¿Qué hace <rep_handlename> aquí?!","story.map2-dungeon5.011":"¡Tú no eres de los Cazademonios, ¿verdad?!","story.map2-dungeon5.012":"Ah, <wait=40><rep_handlename> y yo nos encontramos aquí por casualidad.","story.map2-dungeon5.013":"Tu próxima parada <wait=20>es el Santuario de Lystia, ¿me equivoco?","story.map2-dungeon5.014":"Si no eres miembro de los Cazademonios, no tienes nada que hacer aquí.","story.map2-dungeon5.015":"Oye, <wait=20>Seria. <wait=40>¡No hace falta hablar así!","story.map2-dungeon5.016":"<size=12>...<wait=40>¿¿Por qué me grita a mí??","story.map2-dungeon5.017":"Lo más importante: tengo noticias para ti, Karl.","story.map2-dungeon5.018":"Según la información del Salón de Invocadores, <wait=20>parece que Graham era uno de los favoritos de Abaddon.","story.map2-dungeon5.019":"¿Que cuenta con el favor de Abaddon? <wait=40>¿Y eso qué significa?","story.map2-dungeon5.020":"Por lo visto es muy popular, incluso entre los demás dioses...","story.map2-dungeon5.021":"Así que, si Graham está en peligro, seguro que pronto vendrán más problemas.","story.map2-dungeon5.022":"Puede que incluso aparezca el mismísimo Abaddon...","story.map2-dungeon5.023":"Si es así, tenemos que acabar con Graham para hacer salir a Abaddon.","story.map2-dungeon5.024":"Por eso el Salón de Invocadores nos ha ordenado avanzar hacia la Torre de Morgan. ","story.map2-dungeon5.025":"Ya veo.","story.map2-dungeon5.026":"Por eso aceptaron tan rápido nuestra petición de refuerzos.","story.map2-dungeon5.027":"En fin, ¡¿no crees que ya va siendo hora de dejar la cháchara?!","story.map2-dungeon5.028":"Tú deberías ir de camino a la Torre de Morgan, ¿no?","story.map2-dungeon5.029":"Nosotros aún tenemos mucho que planear...","story.map2-dungeon5.030":"...¡así que, ¿por qué no te das prisa y sigues tú solo?!","story.map2-dungeon5.031":"¿Eh? <wait=20>¡O-<wait=20>Oye, Seria! <wait=40>¡¡<rep_handlename>!!","story.map2-dungeon6.001":"¡<rep_handlename>! <wait=40>¡¿Estás bien?!","story.map2-dungeon6.002":"Te fuiste corriendo después de que Seria te gritara. <wait=20>Pensé que te habrías enfadado.","story.map2-dungeon6.003":"Bueno, <wait=20>me alegra ver que estás bien.","story.map2-dungeon6.004":"Nosotros acabamos de cruzar el Santuario de Lystia.","story.map2-dungeon6.005":"Oye, <wait=40>¡¿por qué siempre apareces allá donde vamos?!","story.map2-dungeon6.006":"¡No nos estarás siguiendo, ¿verdad?!","story.map2-dungeon6.007":"¡¿Quieres dejar ya esa agresividad sin sentido?!","story.map2-dungeon6.008":"¿Por qué siempre tienes que buscar pelea?","story.map2-dungeon6.009":"¡N-<wait=20>No estoy buscando pelea!","story.map2-dungeon6.010":"Si ni siquiera es tan fuerte...","story.map2-dungeon6.011":"Me saca de quicio que elogies a alguien así. ¡En serio, solo mírale!","story.map2-dungeon6.012":"*Suspiro* <wait=40>Si eso no es buscar pelea, <wait=20>no sé qué es...","story.map2-dungeon6.013":"No sé si te has dado cuenta, <wait=20>pero <rep_handlename> ha llegado hasta aquí sin ayuda.","story.map2-dungeon6.014":"<rep_handlename> nos ayudó derrotando al subordinado de Graham en el Bosque Nocturno.","story.map2-dungeon6.015":"<rep_handlename> no es ningún debilucho, eso seguro.","story.map2-dungeon6.016":"Hmpf. <wait=40>Bueno, a mí me da igual.","story.map2-dungeon6.017":"¡Por mí, regodéate todo lo que quieras en sus elogios inmerecidos!","story.map2-dungeon6.018":"...<wait=40>No hay quien entienda a las mujeres.","story.map2-dungeon6.019":"Bueno, <wait=20>en fin...","story.map2-dungeon6.020":"Vamos a cruzar esta catedral en ruinas para llegar a la Torre de Morgan...","story.map2-dungeon6.021":"<rep_handlename>, ¿quieres venir con nosotros?","story.map2-dungeon6.022":"<size=24>¡Me opongo!","story.map2-dungeon6.023":"Je, <wait=20>sabía que dirías eso.","story.map2-dungeon6.024":"Bueno, <wait=20>no podemos ir a la batalla juntos peleándonos entre nosotros así. Mejor no forzarlo.","story.map2-dungeon6.025":"Nosotros iremos por nuestro camino, tú por el tuyo.","story.map2-dungeon6.026":"¡Nos vemos en la Torre de Morgan!","story.map2-dungeon7.001":"¡¡<rep_handlename>!! <wait=40>Qué rapidez, <wait=20>no pensé que ya estarías aquí.","story.map2-dungeon7.002":"Je, <wait=40>es lo mínimo que podía hacer...","story.map2-dungeon7.003":"Como siempre, directa a buscar pelea...","story.map2-dungeon7.004":"Bueno, <wait=20>en fin... <wait=40>Esta es la base de Abaddon, <wait=20>la Torre de Morgan.","story.map2-dungeon7.005":"Lo más probable es que Abaddon y Graham estén aquí.","story.map2-dungeon7.006":"Es casi el único sitio al que Graham podría haber huido.","story.map2-dungeon7.007":"Nosotros iremos a por Graham. <wait=40><br>Y tú, <rep_handlename>, encárgate de Abaddon.","story.map2-dungeon7.008":"Hemos llegado hasta aquí, <wait=40>¡ahora vamos a aplastarlos!","story.map2-dungeon7.009":"¡Aunque puede que derrotemos a Abaddon antes de que tengas ocasión!","story.map2-dungeon7.010":"¿Y qué dirías si <rep_handlename> derrotara a Graham antes que nosotros?","story.map2-dungeon7.011":"Bueno, <wait=40>es normal que quieras enfrentarte tú mismo a los enemigos de tus amigos...","story.map2-dungeon7.012":"¡Pero creo que lo mejor es que colaboremos cada uno en su frente y lo demos todo!","story.map2-dungeon7.013":"Oye... <wait=20>¡oye! <wait=40>Eso suenan como temblores, ¿los oyes?","story.map2-dungeon7.014":"¡¡Por allí!!","story.map2-dungeon7.015":"¡¿Q-<wait=20>Qué es eso?! <wait=40>¡¿Hordas de... <wait=20>monstruos?!","story.map2-dungeon7.016":"...Maxwell. <wait=40>Así que pretende detenernos aquí...","story.map2-dungeon7.017":"No hay vuelta atrás... <wait=40>No nos queda otra que luchar... <wait=40>Aquí y ahora...","story.map2-dungeon7.018":"...<wait=40>Espera, <wait=40>puede que haya otra forma.","story.map2-dungeon7.019":"Solo tenemos que subir a lo más alto de la Torre de Morgan <wait=40>y derrotar allí a Abaddon.","story.map2-dungeon7.020":"¡Eso es imposible!","story.map2-dungeon7.021":"Es imposible enfrentarnos a todos esos monstruos y además a Abaddon...","story.map2-dungeon7.022":"Ni lo pienses. <wait=40>Seguramente ni siquiera llegaríamos a ver a Abaddon.","story.map2-dungeon7.023":"Tienes razón. <wait=40>Pero <wait=20>estos monstruos no pasarán de aquí.","story.map2-dungeon7.024":"¡Yo los detendré aquí mismo!","story.map2-dungeon7.025":"¡¿Karl?! <wait=40>¡¿De qué estás hablando?!","story.map2-dungeon7.026":"¡¿De verdad piensas contenerlos aquí mientras nosotros vamos a enfrentarnos a Abaddon?!","story.map2-dungeon7.027":"Así es. <wait=40>Es nuestra única opción...","story.map2-dungeon7.028":"Pero míralos a todos. <wait=40>¡Es imposible que alguien pueda con todos ellos solo!","story.map2-dungeon7.029":"Sí... <wait=40>Lo sé.","story.map2-dungeon7.030":"Pero si todo tiene que acabar aquí, apostaré por lo que nos dé más posibilidades de derrotar a Abaddon.","story.map2-dungeon7.031":"Karl...","story.map2-dungeon7.032":"<rep_handlename>, <wait=40>adelántate con Seria.","story.map2-dungeon7.033":"Yo detendré a estos monstruos. <wait=40>Tú tienes que ir a acabar con Abaddon.","story.map2-dungeon7.034":"...<wait=40>Yo no voy.","story.map2-dungeon7.035":"¡¡Seria!!","story.map2-dungeon7.036":"Esta horda <wait=20>es demasiado para ti solo, Karl.","story.map2-dungeon7.037":"Si te ayudo a contenerlos <wait=20>un poquito más...","story.map2-dungeon7.038":"Puede que ese sea el tiempo extra que necesitamos <wait=20>para derrotar a Abaddon.","story.map2-dungeon7.039":"Seria, <wait=40>tú...","story.map2-dungeon7.040":"¡<rep_handlename>!","story.map2-dungeon7.041":"Tú... <wait=40>los Invocadores de antaño reconocieron tu fuerza como Invocador, ¿no es así?","story.map2-dungeon7.042":"Entonces demuéstramelo.","story.map2-dungeon7.043":"¡¡Te daré una paliza si no derrotas a Abaddon!!","story.map2-dungeon7.044":"...<wait=40>Bueno, <wait=20>¡¡vamos allá!!","story.map2-dungeon7.045":"Tsk... <wait=20>Esa chica...","story.map2-dungeon7.046":"<rep_handlename>, <wait=40>daremos todo lo que tenemos para contenerlos.","story.map2-dungeon7.047":"Tienes que derrotar a Abaddon.","story.map2-dungeon7.048":"Contamos contigo, <wait=40><rep_handlename>.","story.map2-dungeon7.049":"¡¡Y ahora, <wait=40>a la batalla!!","story.map2-ending.001":"<size=20>¡<rep_handlename>! ¡¿Estás bien?!</size>","story.map2-ending.002":"Oh, <wait=20>¿has... <wait=40>derrotado a Abaddon?","story.map2-ending.003":"Vaya... <wait=40>Sí que eres poderoso.","story.map2-ending.004":"No puedo creer que hayas derrotado a Abaddon sin ayuda de nadie...","story.map2-ending.005":"¿Yo? <wait=20>Estoy bien.","story.map2-ending.006":"Después de separarnos, <wait=20>lo di todo para proteger la entrada de la torre.","story.map2-ending.007":"Seria y yo llegamos a nuestro límite, estuvieron a punto de acabar con nosotros...","story.map2-ending.008":"Pero, por suerte, los refuerzos del Salón de Invocadores llegaron justo a tiempo.","story.map2-ending.009":"Lo dieron todo para ayudarnos...","story.map2-ending.010":"¿Mmm? <wait=20>¿Seria? <wait=40>Está por allí... <wait=40>¿Eh? <wait=20>¿Seria?","story.map2-ending.011":"¿Adónde ha ido? <wait=40>...<wait=40>Mmm, <wait=20>bueno, da igual.","story.map2-ending.012":"Por cierto, <wait=20>estaba muy preocupada por ti.","story.map2-ending.013":"Estaba hecha polvo y agotada, pero insistió en ayudarte y subió directa a la torre...","story.map2-ending.014":"Jeje, <wait=20>a saber qué haría si se enterara de que te he contado todo esto...","story.map2-ending.015":"Así que no le digas que te lo he contado, ¿vale?","story.map2-ending.016":"Pero en serio, <wait=40>te has vuelto muy fuerte.","story.map2-ending.017":"Vinimos corriendo a ayudarte, <wait=40>pero parece que no necesitabas refuerzos.","story.map2-ending.018":"Para mí ya eres un Invocador de primera.","story.map2-ending.019":"Ah, <wait=20>es verdad...","story.map2-ending.020":"Al final no pudimos acabar con Graham.","story.map2-ending.021":"Pero conseguimos capturar a unos cuantos monstruos y hacerles soltar el escondite de Graham.","story.map2-ending.022":"Pero ha huido a un lugar al que no podemos llegar... <wait=20>Maldito desgraciado... ","story.map2-ending.023":"No va a ser fácil dar con él.","story.map2-ending.024":"Tendré que informar al Salón de Invocadores de Akras...","story.map2-ending.025":"Tú... <wait=40>Bueno, <wait=40>supongo que tienes tus propios asuntos que atender.","story.map2-ending.026":"...<wait=20>Será mejor que me ponga en marcha.","story.map2-ending.027":"Puede que nuestros objetivos sean distintos, <wait=40>pero siempre estaré de tu lado.","story.map2-ending.028":"¡Y procura seguir con vida! <wait=40>¡Hasta luego!","story.map2-ending.029":"¡Eh! <wait=40>¡¡<rep_handlename>!!","story.map2-ending.030":"¡Por fin te alcanzo!","story.map2-ending.031":"¡¡Eres increíble!!","story.map2-ending.032":"Mientras yo estaba en Playa Brisa, compitiendo con la Reina de Hielo Selena a ver quién era más mona...","story.map2-ending.033":"...¡resulta que tú derrotaste a Abaddon! ¡Increíble!","story.map2-ending.034":"...¡¿Eh?!","story.map2-ending.035":"¡N-<wait=20>No me malinterpretes! <wait=40>No es que hiciéramos un concurso de belleza ni nada de eso...","story.map2-ending.036":"¡O sea, Selena ni siquiera apareció!","story.map2-ending.037":"Además, <rep_handlename>, tú no estabas, así que de todos modos no había nadie para juzgar el concurso, ¡¿verdad?!","story.map2-ending.038":"...<wait=40>¡¿Y esa cara?!","story.map2-ending.039":"¡De verdad tenía asuntos importantes en Playa Brisa!","story.map2-ending.040":"¡Ah! <wait=20>¿Lo oyes?<br><wait=40>¿Parece que Lord Lucius te está llamando?","story.map2-ending.041":"<speed=12>Que <wait=10>tengas <wait=20>buen viaje<wait=30>...","story.map2-ending.042":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Soy Lucius...<br><wait=40>Dios de la Puerta...","story.map2-ending.043":"<anchor=center><br><br><br><br><br><speed=8><size=15><rep_handlename>... <wait=40>salvador de Morgan...","story.map2-ending.044":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Usa mi poder <wait=40>y aventúrate en nuevas tierras...","story.map2-ending.045":"<anchor=center><br><br><br><br><br><br><br><speed=8><size=15>Avanza <wait=20>y usa tu poder para traer la paz a este mundo...","story.map2-ending.046":"Ah, <wait=20>ya te has despertado.","story.map2-ending.047":"Buenos días, <wait=20> <rep_handlename>.","story.map2-ending.048":"Mira... <wait=40>Por fin hemos llegado a St. Lamia.","story.map2-ending.049":"Este es... <wait=40>el dominio de Maxwell.","story.map2-ending.050":"...<wait=40><rep_handlename>, ¿tú también lo sientes?","story.map2-ending.051":"Noto las ondas de un poder inmenso...","story.map2-ending.052":"Los monstruos también son más fuertes que antes. <wait=40>Tenemos que mantenernos concentrados...","story.map2-ending.053":"Maxwell está en el Palacio de St. Lamia.","story.map2-ending.054":"Nos esperan batallas duras, <wait=40>¡esforcémonos juntos!","story.map2-ending.055":"¿Qué? <wait=40>¿Que dónde estaba yo mientras luchabas en Morgan?","story.map2-ending.056":"No seas tan quisquilloso...","story.map2-ending.057":"Te prometo que en St. Lamia daré lo mejor de mí, <wait=40>¿vale?","story.map2-ending.058":"Bueno, <wait=20>¡¡pongámonos en marcha!!","story.map3-dungeon1.001":"<size=13>¡Aquí hace un calor abrasador! <wait=40>Quiero irme a casa... <wait=40>Mi pobre piel ya no lo aguanta...","story.map3-dungeon1.002":"<size=20>¡Eh! <wait=20>¡<rep_handlename>!","story.map3-dungeon1.003":"¡Tú! <wait=20>¡¡Otra vez llegas tarde!!","story.map3-dungeon1.004":"¡¿No me digas que estabas holgazaneando en algún sitio más fresquito?!","story.map3-dungeon1.005":"¡No es momento de hacer el tonto! <wait=40>¿Qué tienes que decir en tu defensa?","story.map3-dungeon1.006":"¿Eh? <wait=20>¿Y yo qué?","story.map3-dungeon1.007":"<size=15>No <size=14>he <size=13>estado <size=12>holgazaneando <size=11>para <size=10>nada, <size=9>de <size=8>verdad<size=7>...<size=6>","story.map3-dungeon1.008":"En fin, <wait=40>a partir de hoy subiremos el Volcán Eldent.","story.map3-dungeon1.009":"El Volcán Eldent es un volcán activo, así que es muy peligroso.","story.map3-dungeon1.010":"¡Cuidado con los ríos de lava!","story.map3-dungeon1.011":"Bueno, <wait=20>¡buen viaje!","story.map3-dungeon1.012":"¿Qué? <wait=40>¿Quieres consejos más prácticos?","story.map3-dungeon1.013":"Hace demasiado calor... ¡Ya estoy al límite!","story.map3-dungeon1.014":"<size=20>¡Ah! <wait=40>¡No lo aguanto más!","story.map3-dungeon1.015":"Me voy a casa a darme un baño,<wait=20> ¡no te mueras antes de que vuelva!","story.map3-dungeon2.001":"<size=12>Brrr...","story.map3-dungeon2.002":"¡Ah, <wait=20><rep_handlename>! <wait=40>¡Jo, <wait=20>cuánto has tardado!","story.map3-dungeon2.003":"¿Eh? <wait=40>¿Que qué me pasa?","story.map3-dungeon2.004":"No me pasa nada. <wait=40>¡Soy la misma Tilith llena de energía de siempre!","story.map3-dungeon2.005":"Sí, <wait=20>tengo que admitir que aquí empieza a hacer un poco de frío.","story.map3-dungeon2.006":"¡Pero eso es solo porque me has hecho esperar muchísimo, <rep_handlename>!","story.map3-dungeon2.007":"Aparte de eso, <wait=20>debería contarte un poco más sobre el Monte Sagrado Craylia.","story.map3-dungeon2.008":"Este monte sagrado, el Monte Craylia, es la montaña más alta de St. Lamia.","story.map3-dungeon2.009":"Al parecer, en su cima hay una fuente de poder espiritual que sería el origen de esta ventisca perpetua.","story.map3-dungeon2.010":"Y encima, <wait=40>dicen que el Rey del Mar Leviathan también vive allí.","story.map3-dungeon2.011":"Me pregunto por qué dejaría el mar para vivir en lo alto de una montaña...","story.map3-dungeon2.012":"Mmm<wait=20>...","story.map3-dungeon2.013":"<size=12><wait=20>Eh... <wait=20>Brrr...","story.map3-dungeon2.014":"¿Qué? <wait=40>¡Que no, <wait=20>de verdad estoy perfectamente!","story.map3-dungeon2.015":"Pero parece que llevo tanto tiempo en este sitio helado que me he resfriado...","story.map3-dungeon2.016":"Creo que me adelantaré. <wait=40>¡Suerte subiendo esta montaña nevada!","story.map3-dungeon3.001":"*Suspiro* <wait=20>Hmpf... <wait=40>Solo un poco más...","story.map3-dungeon3.002":"¡Ah, <wait=20><rep_handlename>! <wait=40>Te estaba esperando.","story.map3-dungeon3.003":"Para llegar hasta Maxwell tenemos que cruzar esto, <wait=40>el Bosque de Sangre.","story.map3-dungeon3.004":"Bosque de Sangre, qué nombre tan siniestro...","story.map3-dungeon3.005":"Dicen que quienes intentan cruzar este bosque acaban apareciendo cubiertos de sangre...","story.map3-dungeon3.006":"<size=20><size=18>¡Es <size=20>tan, <size=16>tan, <size=19><size=17>tan, <size=18>absoluta, <size=15>totalmente <size=17>siniestro<size=19>!","story.map3-dungeon3.007":"¿Qué? <wait=40>¿Crees que me comporto de forma rara?","story.map3-dungeon3.008":"¡No me comporto de forma rara! <wait=40>Soy tan elegante como siempre, ¿no crees?","story.map3-dungeon3.009":"¿Estás preocupado... <wait=20>por mí?","story.map3-dungeon3.010":"Ya veo, <wait=20>pero si tienes tiempo para decir esas tonterías, ¡¿por qué no te pones en marcha de una vez y te enfrentas a este bosque?!","story.map3-dungeon3.011":"¡¡Buena suerte!!","story.map3-dungeon3.012":"<size=12><wait=20>Ugh<wait=20>...","story.map3-dungeon4.001":"*Cof* <wait=20>*Cof*... <wait=40>Ahh, <wait=20>ugh...","story.map3-dungeon4.002":"Ah, <wait=40><rep_handlename>... <wait=40>Ya estás aquí...","story.map3-dungeon4.003":"Ya... <wait=40>no puedo <wait=40>ocultártelo más...","story.map3-dungeon4.004":"Lo que tengo <wait=20>no es una enfermedad. <wait=40>No estoy enferma.","story.map3-dungeon4.005":"Maxwell... <wait=40>Me ha echado una maldición.","story.map3-dungeon4.006":"Desde... <wait=20>que pusimos un pie en St. Lamia.","story.map3-dungeon4.007":"Ahora que nos acercamos al Palacio de St. Lamia, <wait=40>está empeorando...","story.map3-dungeon4.008":"Seguramente Maxwell <wait=40>me considera una molestia...","story.map3-dungeon4.009":"¿Mmm? <wait=40>A ti no te afecta porque...","story.map3-dungeon4.010":"Yo... <wait=40>te estoy protegiendo de ella.","story.map3-dungeon4.011":"...<wait=40>No pasa nada. <wait=40>No me importa.","story.map3-dungeon4.012":"Gracias por preocuparte... <wait=40>pero estaré bien.","story.map3-dungeon4.013":"Soy una diosa, <wait=40>tu guía...","story.map3-dungeon4.014":"Sin duda <wait=40>te protegeré...","story.map3-dungeon4.015":"Pronto... <wait=40>atraparemos a Maxwell.","story.map3-dungeon4.016":"<wait=20>¡¡Vamos allá, <rep_handlename>!!","story.map3-dungeon4.017":"<size=12><wait=20>Ugh<wait=20>...","story.map3-dungeon5.001":"<speed=12>...Ugh. <wait=40>*Cof* <wait=20>*Jadeo*... <wait=40>*Jadeo*...","story.map3-dungeon5.002":"<speed=12><rep_handlename>... <wait=40>Lo siento... <wait=40>Yo...","story.map3-dungeon5.003":"<speed=12>No puedo... <wait=40>seguir más<wait=40>...","story.map3-dungeon5.004":"<speed=12><rep_handlename>, <wait=40>yo...","story.map3-dungeon5.005":"<speed=12>No hago esto porque Lord Lucius me lo ordenara...","story.map3-dungeon5.006":"<speed=12>Lo hago porque eres <rep_handlename>... <wait=40>Y-<wait=20>Yo solo quería protegerte.","story.map3-dungeon5.007":"<speed=12>Le pedí a Lord Lucius que me dejara... <wait=40>*Cof* <wait=20>*Cof*","story.map3-dungeon5.008":"<speed=12>Hay muchos otros lugares <wait=40>que quería visitar contigo...","story.map3-dungeon5.009":"<speed=12>Quería <wait=40>viajar más...","story.map3-dungeon5.010":"<speed=12>Pero... <wait=40>parece que se me acaba el tiempo...","story.map3-dungeon5.011":"<speed=12>Aunque yo caiga... <wait=40>mi magia seguirá protegiéndote.","story.map3-dungeon5.012":"<speed=12>Prométeme<wait=20>.<wait=20>.<wait=40>.","story.map3-dungeon5.013":"<speed=10>...que <wait=40>sin <wait=40>falta <wait=12>derrotarás <wait=10>a Max<wait=7>well<wait=5>...","story.map3-dungeon5.014":"<speed=10>Ugh...","story.map3-dungeon5.015":"<size=24>(Se desmaya)","story.map3-dungeon5.016":"...<wait=40>...<wait=40>...","story.map3-dungeon5.017":"¡Eh! <wait=40>¡¿De verdad eres tú, <rep_handlename>?!","story.map3-dungeon5.018":"Debes de ser bastante duro <wait=40>para haber llegado hasta aquí sin ayuda...","story.map3-dungeon5.019":"¿¿Y qué tal con Abaddon??<wait=40>","story.map3-dungeon5.020":"<size=18>Oye, <wait=20>¡¿qué le pasa a esa chica?! <wait=40>¡¡Se ha puesto toda azul!!","story.map3-dungeon5.021":"<rep_handlename>... <wait=40>No me digas que<wait=20>...","story.map3-dungeon5.022":"¡¿No me digas que aún no sabes sintetizar antídotos?!","story.map3-dungeon5.023":"Ya, ya. <wait=40>Era broma.","story.map3-dungeon5.024":"...¿Una maldición? <wait=40>¿A qué te refieres?","story.map3-dungeon5.025":"Venga ya, ¡¿de qué estás hablando?!","story.map3-dungeon5.026":"...<wait=60>...<wait=60>...<wait=60>¡!","story.map3-dungeon5.027":"Espera... <wait=40>¿me estás diciendo que <wait=20>esta chica es una diosa?","story.map3-dungeon5.028":"No me estarás... <wait=40>tomando <wait=20>el pelo, <wait=40>¿verdad?","story.map3-dungeon5.029":"¿Y?","story.map3-dungeon5.030":"...<wait=60>...<wait=60>...","story.map3-dungeon5.031":"Así que... <wait=40>fue Maxwell, ¿eh?...","story.map3-dungeon5.032":"Ojalá pudiera ayudar, <wait=40>pero esto me supera...","story.map3-dungeon5.033":"Esto no es algo que podamos curar sintetizando pociones...","story.map3-dungeon5.034":"Pero espera, <wait=40>esta maldición la lanzó Maxwell, ¿no?","story.map3-dungeon5.035":"Entonces, si derrotas a Maxwell, su maldición debería desaparecer, ¿no crees?","story.map3-dungeon5.036":"Y si derrotar a Maxwell no lo soluciona, ¡siempre puedes darle una paliza hasta que la deshaga!","story.map3-dungeon5.037":"Es la única otra forma que se me ocurre ahora mismo.","story.map3-dungeon5.038":"...<wait=20>De acuerdo. <wait=40>Yo me ocuparé de ella.","story.map3-dungeon5.039":"Mi equipo ha montado un campamento cerca, la llevaré allí.","story.map3-dungeon5.040":"Deberías darte prisa.","story.map3-dungeon5.041":"<size=22>¡¡Deja de quedarte ahí parado mirando a las musarañas!!","story.map3-dungeon5.042":"¡Está sufriendo por tu culpa!","story.map3-dungeon5.043":"¡No es momento de entretenerse, deberías ir corriendo al Palacio de St. Lamia!","story.map3-dungeon5.044":"<size=14>...<wait=20>Menudo idiota.","story.map3-dungeon7.001":"<size=20>¡<rep_handlename>! <wait=40>¡¡Me alegra verte con vida!!","story.map3-dungeon7.002":"¿Que por qué estoy aquí? <wait=40>¡Pues he venido a ayudarte!","story.map3-dungeon7.003":"<size=20>¡Maldición!","story.map3-dungeon7.004":"<size=24>*Tajo*","story.map3-dungeon7.005":"<size=24>*Tajo*","story.map3-dungeon7.006":"...Maldita sea, <wait=40>menuda horda tenemos encima, ¿eh?","story.map3-dungeon7.007":"Seria me lo ha contado todo.","story.map3-dungeon7.008":"Deja que me encargue de esto.","story.map3-dungeon7.009":"Se te acaba el tiempo, ¿no? <wait=40>¡Date prisa!","story.map3-dungeon7.010":"<size=20>¡Ugh!","story.map3-dungeon7.011":"<size=24>*Tajo*","story.map3-dungeon7.012":"<size=20>¡¡Lárgate de aquí!!","story.map3-dungeon7.013":"<rep_handlename>... <wait=40>contamos contigo...","story.map3-ending.001":"<size=20>¡¡<rep_handlename>!!","story.map3-ending.002":"*Jadeo*... <wait=40>hmpf...","story.map3-ending.003":"Vaya, <wait=40>el Invocador lo ha conseguido...","story.map3-ending.004":"¡¡Maxwell, uno de los Cuatro Dioses Caídos, ha sido derrotada!!","story.map3-ending.005":"Uf... <wait=40>Pero ha ido por los pelos...","story.map3-ending.006":"<size=20>¡¡<rep_handlename>, bien hecho!!","story.map3-ending.007":"Parece que derrotar a Maxwell sí que rompió la maldición.","story.map3-ending.008":"Y que lo digas, <wait=40>me alegra ver que esta joven diosa se ha recuperado...","story.map3-ending.009":"Por cierto, <wait=20>¡¿cómo has llegado antes que yo?!","story.map3-ending.010":"...<wait=20>De verdad debe de ser una diosa. <wait=40>Supongo que recuperó sus poderes al romperse la maldición.","story.map3-ending.011":"No puedo creer que <rep_handlename> haya contado todo este tiempo con la ayuda de una diosa<wait=40>...","story.map3-ending.012":"Y Seria, hasta tú me has sorprendido. Lo diste todo por esos dos, ¿eh?","story.map3-ending.013":"N-<wait=30>No lo hice por defender a <rep_handlename>.","story.map3-ending.014":"Hice lo que hice por la diosa y por el mundo.","story.map3-ending.015":"Vale, vale... <wait=40>Déjalo ya.","story.map3-ending.016":"<size=18>¡Has derrotado a Maxwell! ¡¡Ese es mi <rep_handlename>!!","story.map3-ending.017":"...<wait=40>Bueno, <wait=20>está bien.","story.map3-ending.018":"En fin, <wait=40>que un novato mejore tan rápido...","story.map3-ending.019":"Bueno, <wait=40>tiene mucho mérito.","story.map3-ending.020":"¡<rep_handlename>! <wait=40>Reconozco que eres un auténtico...","story.map3-ending.021":"¡¡<rep_handlename> lo ha conseguido!! <wait=40>¡¡<rep_handlename> ha ganado!!","story.map3-ending.022":"¡¡Abaddon, y hasta Maxwell, todos derrotados!!","story.map3-ending.023":"Estaba un poco preocupada cuando nos conocimos...","story.map3-ending.024":"...¡¡pero ahora <wait=20>no hay duda de que eres el Invocador más fuerte que existe!!","story.map3-ending.025":"<size=18>¡P-<wait=20>Perdona! <wait=40>Estás siendo muy pesada, ¡¿por qué no te calmas de una vez?!","story.map3-ending.026":"No me culpes. <wait=40>¡Mi Invocador ha derrotado a uno de los Cuatro Dioses Caídos!","story.map3-ending.027":"¡Nunca he sido tan feliz!","story.map3-ending.028":"¡Cállate ya! <wait=40>¡¡Deja de interrumpir cuando alguien intenta hablar!!","story.map3-ending.029":"¡¿Y qué es todo ese rollo empalagoso de <wait=40>«mi <rep_handlename>»?!","story.map3-ending.030":"¡No estaréis saliendo, ¿verdad?!","story.map3-ending.031":"¡Mi <rep_handlename> es mi <rep_handlename>!","story.map3-ending.032":"Arriesgué mi vida para mantener a <rep_handlename> con vida.","story.map3-ending.033":"Además, <wait=20><rep_handlename> se esforzó muchísimo para salvarme...","story.map3-ending.034":"¡<rep_handlename> y yo estamos unidos por el destino!","story.map3-ending.035":"¿Qué pasa? <wait=40>¿Estás celosa o qué?","story.map3-ending.036":"<size=20>¡¿Q-Qu-Quién se pondría celosa por semejante mocoso?!","story.map3-ending.037":"<size=18>¿Y qué es eso del destino? <wait=40><size=24>¡¿Eres tonta o qué?!","story.map3-ending.038":"...Oye, <wait=20>calmaos las dos...","story.map3-ending.039":"Solo una tonta cargaría con una maldición por alguien como <rep_handlename>. <wait=20>¡Qué estupidez!","story.map3-ending.040":"¡¡<rep_handlename> habría estado bien aunque no hubieras hecho nada!!","story.map3-ending.041":"Además, <wait=20>¡¿no se supone que eres una diosa?!","story.map3-ending.042":"¡¿No podías romper la maldición tú sola?!","story.map3-ending.043":"¡¿Qué quieres decir con eso?! <wait=40>¡¿Insinúas que no me esforcé al máximo?!","story.map3-ending.044":"¡Estabas al borde de la muerte en el Santuario Recóndito!","story.map3-ending.045":"¡¡Si yo no hubiera estado allí, esos monstruos te habrían devorado!!","story.map3-ending.046":"¡Tonterías! <wait=40>¡<rep_handlename> me habría protegido aunque tú no estuvieras!","story.map3-ending.047":"¡Mucho hablar, pero tú tampoco has hecho nada!","story.map3-ending.048":"¡¡E-<wait=10>Espera un momento!! <wait=40>¡¿Quién crees que te estuvo cuidando?!","story.map3-ending.049":"Estaba inconsciente, no recuerdo nada...","story.map3-ending.050":"¡¡Serás...!!","story.map3-ending.051":"Eh, vosotras dos... <wait=40>Parad ya.","story.map3-ending.052":"<size=24>¡¡Cállate!!","story.map3-ending.053":"Uau...","story.map3-ending.054":"Para empezar, ¡¿por qué Seria siempre se pone tan mandona con <rep_handlename>?!","story.map3-ending.055":"¡Si ni siquiera pudo derrotar a Graham, y no hablemos de Abaddon!","story.map3-ending.056":"<size=12>Ay... <wait=40>Que yo también estuve en esa batalla, ¿sabes?...","story.map3-ending.057":"¡¡Deja de dejar en ridículo a mi <rep_handlename>!!","story.map3-ending.058":"¡Y-<wait=20>Yo digo lo que me da la gana! <wait=40>¡¿Estás buscando pelea?!","story.map3-ending.059":"¡Has empezado tú!","story.map3-ending.060":"¡Y que sepas que soy muy poderosa cuando no estoy maldita!","story.map3-ending.061":"<size=24>¡Por el amor del cielo! <wait=40>¡¡Ya basta!!","story.map3-ending.062":"¡<rep_handlename> ha derrotado a Maxwell!","story.map3-ending.063":"No es momento de discutir.","story.map3-ending.064":"...Hmpf.","story.map3-ending.065":"Hmpf.","story.map3-ending.066":"Chicas, <wait=20>os estáis portando peor que el mismísimo Maxwell...","story.map3-ending.067":"Pero en fin, <wait=20>tengo que reconocerlo, <wait=20><rep_handlename>.","story.map3-ending.068":"Estoy orgulloso de ser tu amigo.","story.map3-ending.069":"...<wait=40>Me fastidia decirlo, <wait=40>pero no puedo negar que derrotaste a Maxwell.","story.map3-ending.070":"<wait=40>Buen trabajo.","story.map3-ending.071":"Uf.","story.map3-ending.072":"Bueno, <wait=20>Seria y yo tenemos que irnos ya.","story.map3-ending.073":"...¿Eh? <wait=40>No hace falta que me des las gracias.","story.map3-ending.074":"¡Solo prométeme que nos echarás una mano la próxima vez que lo necesitemos!","story.map3-ending.075":"Ya nos veremos, amigo.","story.map3-ending.076":"Hmpf, <wait=20>adiós.","story.map3-ending.077":"...Bueno, <wait=40>déjame decirlo otra vez.","story.map3-ending.078":"¡Enhorabuena! <wait=40><rep_handlename>.","story.map3-ending.079":"Tenía fe en que sin duda derrotarías a Maxwell.","story.map3-ending.080":"Pero en vez de ayudarte yo... <wait=40>acabaste ayudándome tú a mí.","story.map3-ending.081":"Estoy muy feliz. <wait=40>Gracias.","story.map3-ending.082":"Jeje. <wait=40>Jo, qué vergüenza.","story.map3-ending.083":"Ah, <wait=20>es verdad. Nos prometimos visitar juntos muchos lugares, ¿verdad?","story.map3-ending.084":"Pensé que iba a morir, <wait=40>por eso te hice prometérmelo.","story.map3-ending.085":"Pero, ahora que has derrotado a Maxwell, seguramente estaremos aún más ocupados.","story.map3-ending.086":"Aunque Maxwell haya sido derrotada, <wait=40>los Dioses Caídos son cuatro en total.","story.map3-ending.087":"Aún quedan tres por ahí.","story.map3-ending.088":"Hasta que derrotes a todos los Dioses Caídos, <wait=40>Grand Gaia no conocerá la paz.","story.map3-ending.089":"Así que <wait=40>tendremos que aplazar la aventura que nos prometimos.","story.map3-ending.090":"Lo siento muchísimo, <wait=40>pero las diosas estamos muy ocupadas, ¿sabes?","story.map3-ending.091":"Bueno, <wait=40>ya va siendo hora de que informe a Lord Lucius.","story.map3-ending.092":"Sigue mejorando tus habilidades, <wait=20>tienes que hacerte aún más fuerte si piensas derrotar al resto de los Dioses Caídos.","story.map3-ending.093":"Ah, <wait=40>y una cosa más...","story.map3-ending.094":"Si vuelves a ver a esos dos, dales las gracias de mi parte.","story.map3-ending.095":"Diles que les estoy muy agradecida por todo lo que hicieron por nosotros.","story.map3-ending.096":"Bueno, <wait=20>¡me pongo en marcha!","story.map3-ending.097":"¡Nos volveremos a ver pronto, <wait=20>estoy segura!","story.map3-ending.098":"¡¡¡Hasta luego!!!","story.map4-dungeon1.001":"Bah... ¡No me he cruzado con un solo<br>monstruo desde que llegué!","story.map4-dungeon1.002":"No me lo creo... <wait=40>¿Por qué yo, el poderoso Lugina, tengo que cargar con tareas tan mundanas...?","story.map4-dungeon1.003":"¿Hm?<wait=40><br>¡Eh, tú! <wait=20>¡Identifícate!","story.map4-dungeon1.004":"¡Ajá! <wait=20>Del Ejército de Akras, ¿eh?<br>¿Cómo te llamas?","story.map4-dungeon1.005":"¿<rep_handlename>?<wait=40><br>Bah... <wait=40>Qué nombre más raro, si me preguntas.","story.map4-dungeon1.006":"¿Qué dices?<wait=40><br>¿Quieres saber mi nombre?","story.map4-dungeon1.007":"No es que tenga por qué presentarme<br>ante un miembro del ejército regular, pero...","story.map4-dungeon1.008":"<wait=20>...Bueno, si tanto quieres saberlo, supongo que no pasa nada por decírtelo.","story.map4-dungeon1.009":"¡Soy el poderoso Invocador Lugina,<wait=40><br>distinguido líder de la 23.ª División de Cazademonios,<wait=40>","story.map4-dungeon1.010":"también conocida como Sky Garden!<br>¡Que no se te olvide!","story.map4-dungeon1.011":"Y bien,<wait=40> ¿buscas algo por aquí o qué?","story.map4-dungeon1.012":"¿Eh?<wait=40> ¿Tu misión es derrotar a los Cuatro Dioses Caídos?","story.map4-dungeon1.013":"Pff... Jeje... <size=24>¡Bwajaja!","story.map4-dungeon1.014":"¡Así que los vejestorios de Akras<br>de verdad están perdiendo la cabeza!","story.map4-dungeon1.015":"No creerás en serio que el ejército regular<br>tiene alguna opción contra los Cuatro Dioses Caídos, ¿no?","story.map4-dungeon1.016":"Ya va siendo hora de que esos carcamales se jubilen<br>y dejen la caza de demonios a profesionales como yo.","story.map4-dungeon1.017":"¿Hmm? <wait=40>¿Dices que recibes órdenes de una diosa?<br>¿No del Salón de Invocadores?","story.map4-dungeon1.018":"...¿Es una especie de broma?<wait=40><br>¿O de verdad eres tan tonto?","story.map4-dungeon1.019":"¿Sabes siquiera qué hago yo<br>aquí, tan lejos de todo?","story.map4-dungeon1.020":"Increíble... <wait=40>Por eso siempre digo","story.map4-dungeon1.021":"que no se puede uno fiar de un miembro del ejército regular.","story.map4-dungeon1.022":"¿Sabías siquiera que este territorio que pisamos<br>lo acaba de descubrir el Salón de Invocadores de Akras?","story.map4-dungeon1.023":"Aún no se ha investigado como es debido,<br>así que mejor mira dónde pisas.","story.map4-dungeon1.024":"Ya sabes cómo va: monstruos y todo ese rollo.","story.map4-dungeon1.025":"En fin, depende de Invocadores poderosos<br>y formidables como un servidor","story.map4-dungeon1.026":"asegurarse de que zonas potencialmente<br>peligrosas como esta sean lo bastante seguras","story.map4-dungeon1.027":"para que Invocadores novatos<br>como tú puedan poner un pie en ellas.","story.map4-dungeon1.028":"¡Si sabes lo que te conviene,<br>vete a un sitio más seguro hasta que yo acabe aquí!","story.map4-dungeon1.029":"Hay montones de zonas en Grand Gaia<br>que aún no se han investigado como es debido.","story.map4-dungeon1.030":"¿Qué? ¿Acaso he tartamudeado?<wait=40><br>Vaya, eres tan tonto como pareces.","story.map4-dungeon1.031":"A ver, te lo diré más claro...<br><wait=40>¡Quítate de en medio y déjame trabajar en paz!<wait=40>","story.map4-dungeon1.032":"¡Deja de perder el tiempo con estos bichejos y vete a buscar a otra parte!","story.map4-dungeon1.033":"Tsk... Con zoquetes como tú en el ejército regular, no me extraña que el Salón de Invocadores esté en apuros...","story.map4-dungeon2.001":"¡¿Tú otra vez?!<wait=40><br>¡Te dije que te largaras!","story.map4-dungeon2.002":"¡Hay que tener valor<br>para ignorarme así!","story.map4-dungeon2.003":"¿O es que necesitas que alguien te lleve<br>de la manita a casa?","story.map4-dungeon2.004":"Vaya... <wait=40>Ni los del Ejército Imperial son tan incompetentes.","story.map4-dungeon2.005":"¿Eh?<wait=40><br>¿A qué viene esa cara de despiste?","story.map4-dungeon2.006":"Un momento... <wait=40>No me digas que <br>nunca has oído hablar del Ejército Imperial de Randall.","story.map4-dungeon2.007":"Vaya. Pero vaya...","story.map4-dungeon2.008":"En serio, casi consigues<br>que me des pena.","story.map4-dungeon2.009":"En ese caso, no queda otra.","story.map4-dungeon2.010":"¡Yo, Lugina, puro y de corazón virtuoso, te enseñaré todo lo que necesitas saber!","story.map4-dungeon2.011":"¡Sécate las lágrimas de gratitud<br>y recuerda lo que voy a contarte!","story.map4-dungeon2.012":"Empecemos por lo fácil. <wait=40>Ya sabes que nuestra tierra, Elgaia, se separó de Grand Gaia.","story.map4-dungeon2.013":"Ya sabes, la Tierra de los Dioses,<br>¿no?","story.map4-dungeon2.014":"¡Bueno,<wait=40> al menos algo sabes!","story.map4-dungeon2.015":"¡No sé de qué te enorgulleces tanto!<wait=40> Eso lo sabe todo el mundo.","story.map4-dungeon2.016":"Vaya...","story.map4-dungeon2.017":"Bien, sigamos. <wait=40>Elgaia está formada por dos grandes países.","story.map4-dungeon2.018":"Uno de ellos, el Imperio de Randall, alberga el Salón de Invocadores de Akras.","story.map4-dungeon2.019":"El Salón de Invocadores de Akras se encarga de los asuntos económicos","story.map4-dungeon2.020":"y militares de la nación, así que lo del imperio es más bien de fachada.","story.map4-dungeon2.021":"La élite de Randall desciende<br>de quienes reconstruyeron la nación cuando","story.map4-dungeon2.022":"se separó de Grand Gaia, lo que en parte explica por qué se dan tantos aires.","story.map4-dungeon2.023":"Hoy en día no son más que un puñado de carcamales disfrutando de su vida de lujo.","story.map4-dungeon2.024":"Ni que decir tiene que su ejército es más que nada de fachada, una muestra de autoridad, por así decirlo.","story.map4-dungeon2.025":"Aunque supongo que algún que otro soldado con talento ha pasado por sus filas de vez en cuando.","story.map4-dungeon2.026":"En fin, <wait=40>el otro país es la Federación de Elgaia,","story.map4-dungeon2.027":"aunque su historia es bastante parecida.","story.map4-dungeon2.028":"Ninguno de los dos tiene lo necesario para plantarle cara al Salón de Invocadores de Akras,","story.map4-dungeon2.029":"así que en la práctica el Salón gobierna<br>toda Elgaia.","story.map4-dungeon2.030":"¡Y como yo soy el Invocador más poderoso<br>del Salón de Invocadores de Akras,","story.map4-dungeon2.031":"eso me convierte en el más poderoso de toda Elgaia!","story.map4-dungeon2.032":"¿Y bien?<wait=40><br>Seguro que quieres mi autógrafo, ¿eh?","story.map4-dungeon2.033":"<size=14>(Retumbo, retumbo)","story.map4-dungeon2.034":"¡Q-<wait=20>Qué!","story.map4-dungeon2.035":"¡¿H-<wait=20>Ha sido un terremoto?!","story.map4-dungeon2.036":"Aunque no ha parecido un terremoto<br>cualquiera...","story.map4-dungeon2.037":"¡¿Ves ahora a qué me refiero?!","story.map4-dungeon2.038":"Cordelica no estará a salvo hasta que averigüemos qué está pasando.","story.map4-dungeon2.039":"¡Ahora atiende a mis sabias palabras y lárgate mientras puedas!","story.map4-dungeon2.040":"¡Te arrepentirás si nuestros caminos se vuelven a cruzar!","story.map4-dungeon3.001":"<size=20>¡¿Tú otra vez?!<wait=40> ¡<rep_handlename>!","story.map4-dungeon3.002":"¡¿Por qué sigues aquí?!","story.map4-dungeon3.003":"¡Se acabó!","story.map4-dungeon3.004":"Si no vas a hacer caso de mis consejos,<wait=40> ¡tendré que meterte algo de sentido a golpes!","story.map4-dungeon3.005":"¡Ahora no te muevas!","story.map4-dungeon3.006":"<size=14>(Retumbo, retumbo)","story.map4-dungeon3.007":"¡¿O-Otra vez?!<wait=40><br>¿Qué pasa con tantos terremotos últimamente?","story.map4-dungeon3.008":"¡Eh!<wait=40> ¡<rep_handlename>!","story.map4-dungeon3.009":"¿Ves ahora de lo que te<br>hablaba?","story.map4-dungeon3.010":"Este no es sitio para que un Invocador novato como tú ande merodeando.","story.map4-dungeon3.011":"¡Vuelve a casa y asegúrate<br>de que no es el Ejército Imperial el que está tramando algo!","story.map4-dungeon3.012":"...<wait=20>¿A qué viene esa cara?","story.map4-dungeon3.013":"¿Por qué me da la impresión de que aún no entiendes lo increíble que soy...?","story.map4-dungeon3.014":"Bien, escucha.<wait=40><br>Ya te lo dije antes,","story.map4-dungeon3.015":"pero aquí en Elgaia hay varias facciones distintas,<br>cada una con su propio ejército.","story.map4-dungeon3.016":"El más fuerte de esos ejércitos es el del Salón de Invocadores de Akras.","story.map4-dungeon3.017":"Tiene sentido, ¿no?<br>Al fin y al cabo, tienen a casi todos los","story.map4-dungeon3.018":"Invocadores de Elgaia...","story.map4-dungeon3.019":"En fin, el ejército de Akras se compone<br>de tres tipos de fuerzas.","story.map4-dungeon3.020":"Para empezar, <wait=40>está el Ejército de Invocadores, alias el Ejército Regular, donde todo Invocador novato","story.map4-dungeon3.021":"empieza. Ese es tu regimiento, por cierto.","story.map4-dungeon3.022":"Tu misión oficial es derrotar a los Cuatro Dioses Caídos, pero... bueno, ¿cómo decirlo?","story.map4-dungeon3.023":"La verdad es que nadie espera que el<br>Ejército Regular consiga nada.","story.map4-dungeon3.024":"¿Y de quién esperan que haga el trabajo, preguntas?<br>¡Pues de los míos, los Cazademonios!","story.map4-dungeon3.025":"Somos un escuadrón de élite de Invocadores<br>seleccionados de entre las filas del Ejército Regular.","story.map4-dungeon3.026":"A los más fuertes, como yo por ejemplo, se les da el mando de escuadrones más pequeños.","story.map4-dungeon3.027":"Y, por supuesto, el más fuerte de todos es el que yo dirijo:","story.map4-dungeon3.028":"¡la 23.ª División de Cazademonios, Sky Garden!","story.map4-dungeon3.029":"Y justo cuando creías que no<br>podía superarme, ¿eh?","story.map4-dungeon3.030":"¿Hmm? <wait=40>¿Y los ejércitos de Randall<br>y de la Federación de Elgaia, dices?","story.map4-dungeon3.031":"¡Ja! Entre los dos apenas tienen un puñado de Invocadores. Son aún más inútiles que nuestro Ejército Regular.","story.map4-dungeon3.032":"¡Ahora deja de agobiarme con tantas preguntas y vuelve a casa, que es donde tienes que estar!","story.map4-dungeon3.033":"¡Los monstruos de por aquí no son<br>tan blandos como los que sueles enfrentar!","story.map4-dungeon3.034":"¿Me oyes? ¡Largo!","story.map4-dungeon3.035":"*Suspiro* <wait=40>¿Qué habré hecho yo<br>para que me destinen tan lejos?","story.map4-dungeon3.036":"Así que han enviado al Cazademonios Lugina, de Sky Garden...","story.map4-dungeon3.037":"Je. Seguramente solo querían que<br>dejara de molestarlos un rato...","story.map4-dungeon3.038":"Aun así, parece que será bastante fácil usarlo para mis fines.","story.map4-dungeon3.039":"Ahora solo queda trazar un plan...","story.map4-dungeon4.001":"<size=20>¡¿Tú otra vez?! ¡<rep_handlename>!","story.map4-dungeon4.002":"¡Se acabó! ¡Se terminó el ser amable!","story.map4-dungeon4.003":"¡Espero que te guste ese sitio donde estás, porque ahí es donde te voy a enterrar cuando acabe!","story.map4-dungeon4.004":"<size=18>(Retumbo, retumbo)","story.map4-dungeon4.005":"¿Otro más...?<br>Estos terremotos no son nada normales.","story.map4-dungeon4.006":"Esos viejos necios del Salón de Invocadores...<br>¡Malditos sean todos!","story.map4-dungeon4.007":"¡Escucha, <rep_handlename>!","story.map4-dungeon4.008":"Este sitio es demasiado peligroso<br>para quedarnos.","story.map4-dungeon4.009":"Voy a redactar mi informe y volver<br>a Elgaia ahora mismo. <wait=40>Serás mi testigo, ¿verdad?","story.map4-dungeon4.010":"¡Piensa en todo lo que te he enseñado!<br>No dejarías tirado a un viejo amigo, ¿a que no?","story.map4-dungeon4.011":"Palabras bastante cobardes para alguien que se proclama mando de los Cazademonios, ¿no crees?","story.map4-dungeon4.012":"¡¿...?!<br><wait=40>¿Quién eres?","story.map4-dungeon4.013":"E-Ese escudo de armas...","story.map4-dungeon4.014":"¡No puede ser!<br>¡¿Un miembro de la Guardia Imperial?!","story.map4-dungeon4.015":"Así es.<br>Quizá sí sirvas para enseñar, después de todo.","story.map4-dungeon4.016":"Me llamo Paris. Pertenezco a una<br>de esas fuerzas \\"inútiles\\" que describías hace un momento.","story.map4-dungeon4.017":"¡¿Has estado escuchando todo este tiempo?!<br>¿Nadie te enseñó modales?","story.map4-dungeon4.018":"Podría preguntarte lo mismo.","story.map4-dungeon4.019":"¿O acaso consideras que ignorar las órdenes<br>de tu país, por no hablar de menospreciar","story.map4-dungeon4.020":"al Ejército Imperial que se esfuerza<br>por la prosperidad de nuestro reino, es propio de una persona honorable?","story.map4-dungeon4.021":"Pff...<br><wait=40>¡Ay, lo siento muchísimo! ¡Te ruego que me perdones!","story.map4-dungeon4.022":"Tal como esperaba, los miembros del Salón<br>de Invocadores sois a cuál más grosero...","story.map4-dungeon4.023":"¡Cuéntaselo a quien le importe,<br>señora!","story.map4-dungeon4.024":"Además, los zoquetes de la Guardia Imperial<br>protegéis a la Familia Imperial, ¿no?","story.map4-dungeon4.025":"¿Qué haces tan lejos de casa?","story.map4-dungeon4.026":"No tengo todo el día,<br>¡así que suéltalo ya!","story.map4-dungeon4.027":"Je...<br>Tienes mucho carácter para ser un simple compinche.","story.map4-dungeon4.028":"¡¿A quién llamas compinche?!","story.map4-dungeon4.029":"¿Crees que este bobo y yo somos compañeros? ¡Ja!","story.map4-dungeon4.030":"Lo que tú digas, señora.<br>Tengo cosas mejores que hacer con","story.map4-dungeon4.031":"mi tiempo que buscar pelea con la<br>Guardia Imperial aquí, en el quinto pino.","story.map4-dungeon4.032":"Ah, la famosa diplomacia de los Cazademonios.<br>Al menos todos sabemos a qué atenernos.","story.map4-dungeon4.033":"Bueno, para ser sincera, he venido hasta aquí para pedirte un favor.","story.map4-dungeon4.034":"Queremos contar con tu ayuda<br>para investigar Cordelica.","story.map4-dungeon4.035":"¡Ja!<wait=40><br>¿De verdad has dicho lo que creo?","story.map4-dungeon4.036":"No busco problemas, <wait=40>¡pero tampoco pienso obedecer tus órdenes!","story.map4-dungeon4.037":"Este sitio no es seguro para quedarnos,<br>por si no te habías dado cuenta.","story.map4-dungeon4.038":"Veo que eres consciente del peligro<br>que entraña esta región.","story.map4-dungeon4.039":"Claro, no esperaba menos<br>de alguien que se proclama líder de los Cazademonios.","story.map4-dungeon4.040":"¿Qué estás insinuando, eh?","story.map4-dungeon4.041":"¿Insinuar?<wait=40> No, solo constato hechos.","story.map4-dungeon4.042":"Alguien que teme unos cuantos<br>terremotos de nada no podría","story.map4-dungeon4.043":"dirigir un escuadrón con tanto talento como dices, ¿verdad?","story.map4-dungeon4.044":"¡Serás...!<wait=40><br>¡Cuidado con lo que dices!","story.map4-dungeon4.045":"¡¿Me estás llamando cobarde?!","story.map4-dungeon4.046":"¡No me hagas reír!<wait=40><br>¡Ya te enseñaré yo lo que es tener miedo!","story.map4-dungeon4.047":"¡Eh!<wait=40> ¡<rep_handlename>!","story.map4-dungeon4.048":"¡Ya es hora de que arrimes el hombro!","story.map4-dungeon4.049":"Hasta ahora has ignorado todo<br>lo que te he dicho.","story.map4-dungeon4.050":"Seguro que te crees muy importante, ¿eh?","story.map4-dungeon4.051":"Pues si tan bueno eres, ¡demuéstralo librándote del enano que se esconde en esa fortaleza de allí!","story.map4-dungeon4.052":"Los monstruos que encontremos<br>serán más duros a partir de ahora,","story.map4-dungeon4.053":"pero ni siquiera tú deberías tener<br>problemas con esos de allí.","story.map4-dungeon4.054":"Jeje... <wait=40>Esto va a ser interesante.","story.map4-dungeon4.055":"...¡¿Y bien?! ¡No te quedes ahí mirando!<wait=40><br>¡Sal ahí y dales una buena tunda!","story.map4-dungeon4.056":"Ya has oído al señor,<br><rep_handlename>... Jeje.","story.map4-dungeon5.001":"¡Hmpf! <wait=40>Sí que te has tomado<br>tu tiempo para llegar.","story.map4-dungeon5.002":"Y luego se preguntan por qué no respeto<br>más a los del Ejército Regular.","story.map4-dungeon5.003":"Aun así, has llegado antes que esa engreída de la Guardia Imperial, algo es algo.","story.map4-dungeon5.004":"¿Y quién será esa, entonces?","story.map4-dungeon5.005":"¿Qu-? <wait=20>¡¿Tú?!<wait=40><br>¡¿Cuánto llevas ahí plantada?!","story.map4-dungeon5.006":"Desde justo antes de que llegaras<br>y empezaras a hacer el ridículo.","story.map4-dungeon5.007":"¡Serás...! <wait=40>¡Has estado<br>vigilándome todo este tiempo!","story.map4-dungeon5.008":"Ay, relájate, ¿quieres?","story.map4-dungeon5.009":"Tengo cosas más importantes que hacer<br>que analizar cada movimiento que haces.","story.map4-dungeon5.010":"¡Argh, dejadme que la pille!","story.map4-dungeon5.011":"¡Por esto odio a los de la Guardia<br>Imperial, siempre tan condenadamente engreídos!","story.map4-dungeon5.012":"Ya airearás tus quejas luego.<wait=40><br>Primero, dime qué haces aquí.","story.map4-dungeon5.013":"¿Eh?<wait=40> <br>¿Es una especie de broma?","story.map4-dungeon5.014":"He venido a investigar las ruinas, por supuesto.","story.map4-dungeon5.015":"¡Míralas! Deben de llevar aquí<br>desde antes del Gran Colapso.","story.map4-dungeon5.016":"¿Has visto alguna vez un sitio<br>que pida a gritos que lo investiguen?","story.map4-dungeon5.017":"En fin, vine a echarles un<br>vistazo, y este no deja de seguirme.","story.map4-dungeon5.018":"Ya veo...<wait=40><br>Así que sabes leer escritura antigua, deduzco.","story.map4-dungeon5.019":"Tenía entendido que el que debía<br>investigar era yo...","story.map4-dungeon5.020":"¿Qué pasa? ¡¿Crees que no estoy a la altura, eh?!","story.map4-dungeon5.021":"Eres la única capaz de hacer<br>algo intelectual, ¿es eso?","story.map4-dungeon5.022":"No, <wait=40>de hecho, estoy bastante impresionada.","story.map4-dungeon5.023":"Quizá no seas tan tonto como<br>sugiere ese aspecto tan tosco.","story.map4-dungeon5.024":"...<wait=40>Te lo advierto,<br>señora.","story.map4-dungeon5.025":"No creas que no voy a reaccionar si sigues provocándome.","story.map4-dungeon5.026":"Y créeme, cuando me enfado,<br>¡soy capaz de hacer polvo cualquier cosa!","story.map4-dungeon5.027":"Sea de la Guardia Imperial o no.","story.map4-dungeon5.028":"Vaya, eso sí que da miedo.<br>Más me vale no enfadarte, entonces.","story.map4-dungeon5.029":"Grrr...<wait=40><br>¡Lo sabía! ¡Te estás burlando de mí!","story.map4-dungeon5.030":"Jeje...<wait=40><br>¿De verdad crees que sería tan cruel?","story.map4-dungeon5.031":"De hecho, mejor que tú tampoco hagas enfadar a Lugina, ¿entendido?","story.map4-dungeon5.032":"Aunque no me imagino<br>a ningún amigo de Karl","story.map4-dungeon5.033":"asustándose de alguien de Sky Garden...","story.map4-dungeon5.034":"¿Eh?<wait=40><br>Ese Karl del que hablas... <wait=40>¿No será Karl de Nyonne?","story.map4-dungeon5.035":"<size=20>¡Bwajaja!","story.map4-dungeon5.036":"Ay, hacía siglos que no me reía así.<wait=40><br>¡Solo de pensar que este zoquete pueda ser amigo de Karl!","story.map4-dungeon5.037":"Ahora sí que lo he oído todo...","story.map4-dungeon5.038":"¡Eh! ¡¿Adónde crees que vas?!","story.map4-dungeon5.039":"A investigar.<wait=40><br>Cubriremos más terreno si nos separamos, ¿no crees?","story.map4-dungeon5.040":"Lugina,<wait=40><br>tú revisa por allí.","story.map4-dungeon5.041":"¡E-Espera!<wait=40><br>¿Cómo se supone que voy a saber dónde...?","story.map4-dungeon5.042":"...Hmpf.","story.map4-dungeon5.043":"Si va a mentirme a la cara,<br>al menos podría hacerlo un poco creíble.","story.map4-dungeon5.044":"Je, como si este bobo ignorante<br>pudiera conocer de verdad a Karl...","story.map4-dungeon5.045":"Grr... <wait=40>¡Solo de pensar en ese<br>niño bonito con cara de chica me hierve la sangre!","story.map4-dungeon5.046":"¡Eh, tú! <wait=40>¡No te quedes ahí con cara de tonto! ¡Sal ahí y encárgate de esos monstruos!","story.map4-dungeon6.001":"<size=20>¡Argh, <wait=40>se acabó!","story.map4-dungeon6.002":"¡Estoy harto de esto!<br>¡¿Qué he hecho yo para merecer esto, eh?!","story.map4-dungeon6.003":"¡¿Por qué me toca a mí enfrentarme<br>a unas bestias tan monstruosas?!","story.map4-dungeon6.004":"¡No es justo!<wait=40><br>¡No he hecho nada para merecer esto!","story.map4-dungeon6.005":"¡¡Ay!!<wait=40><br>...Ah, solo eres tú, <rep_handlename>.","story.map4-dungeon6.006":"Tsk... No he tenido más que problemas<br>desde que me topé contigo.","story.map4-dungeon6.007":"Quejándote como siempre, ¿eh?<br>De verdad, Lugina, no es propio de un hombre de tu talla.","story.map4-dungeon6.008":"¡Cállate tú!<wait=40><br>¡¿Y qué te has creído, apareciendo siempre a mis espaldas?!","story.map4-dungeon6.009":"¡Tú eres una de las razones por las que<br>me vi metido en este lío en primer lugar!","story.map4-dungeon6.010":"Nuestra situación actual dista mucho de ser ideal,<br>eso te lo concedo.","story.map4-dungeon6.011":"Pero insultar a la gente y quejarse no va a cambiar la situación.","story.map4-dungeon6.012":"¡¿Crees que no lo sé<br>ya?!","story.map4-dungeon6.013":"¡Tengo una noticia para ti: no me arrastro por estos túneles mugrientos por diversión, ¿vale?!","story.map4-dungeon6.014":"Jeje...<wait=40><br>No, ya lo veo.","story.map4-dungeon6.015":"Aun así, pareces saber<br>lo que hay que hacer.","story.map4-dungeon6.016":"Exacto. <wait=40>Y de eso es de lo que me quejo.","story.map4-dungeon6.017":"¡Bien! Crucemos de una vez este<br>túnel y vayamos rápido a las Ruinas del Gigante.","story.map4-dungeon6.018":"Vaya, alguien parece tener prisa...<wait=40> Será mejor que tú también te des prisa.","story.map4-dungeon6.019":"Si no nos damos prisa, los grandes dioses<br>despertarán y arrasarán todo este continente.","story.map4-dungeon6.020":"¡No hay tiempo para explicarle cosas a ese lerdo!","story.map4-dungeon6.021":"Yo iré delante.","story.map4-dungeon6.022":"¡Tú acaba con los rezagados que<br>consigan escabullirse!","story.map4-dungeon6.023":"Je...<wait=40><br>Hablas como un auténtico guerrero, Lugina.","story.map4-dungeon6.024":"Pero te equivocas en una cosa.","story.map4-dungeon6.025":"<rep_handlename> tiene derecho a saber<br>el peligro en el que nos encontramos.","story.map4-dungeon6.026":"Has visto luchar a <rep_handlename>,<br>¿no es así?","story.map4-dungeon6.027":"Deberíamos aprovechar toda la<br>fuerza militar que tenemos a mano.","story.map4-dungeon6.028":"¡Hmpf! <wait=40>Como quieras.<br>¡Pero las explicaciones te las dejo a ti!","story.map4-dungeon6.029":"Estoy hasta las narices de<br>hacer de niñera de este crío crecidito.","story.map4-dungeon6.030":"Parece que al final ha decidido<br>ir por su cuenta.","story.map4-dungeon6.031":"Tsk... Nunca hará amigos<br>con esa actitud tan agria.","story.map4-dungeon6.032":"Bueno,<wait=40><br>¡por fin estamos solos tú y yo!","story.map4-dungeon6.033":"Así que tú eres de quien hablan los Ancianos, amigo de Karl,","story.map4-dungeon6.034":"el líder de la poderosa 24.ª de Cazademonios, Rebluens.","story.map4-dungeon6.035":"He oído grandes historias sobre ti,<br><rep_handlename>.","story.map4-dungeon6.036":"No hace falta que pongas esa<br>cara de alarma.","story.map4-dungeon6.037":"Calma.<wait=40><br>Estoy de tu lado, ¿sabes?","story.map4-dungeon6.038":"A juzgar por tu expresión, aún me queda camino para ganarme tu confianza.","story.map4-dungeon6.039":"¿Por dónde iba?<wait=40><br>Ah, sí, los gigantes.","story.map4-dungeon6.040":"En realidad no es tan complicado.","story.map4-dungeon6.041":"Hace mucho tiempo, una raza de gigantes<br>vivía aquí, en Cordelica.","story.map4-dungeon6.042":"Sin embargo, toda su raza fue<br>aniquilada por fuerzas que escapan a nuestra comprensión.","story.map4-dungeon6.043":"Todos, salvo uno de ellos:<br>el que hoy se conoce como el dios gigante.","story.map4-dungeon6.044":"Sumido en la ira y la desesperación<br>por sus compañeros caídos, ","story.map4-dungeon6.045":"el gigante se selló a sí mismo en esta tierra.","story.map4-dungeon6.046":"Esa es la leyenda tal como está inscrita en<br>la Torre de la Luz. <wait=40>Quién la escribió, no lo sabemos.","story.map4-dungeon6.047":"Lugina debió de toparse<br>con la misma inscripción.","story.map4-dungeon6.048":"Tras leerla, <wait=40>debió de<br>llegar a la misma conclusión que yo...","story.map4-dungeon6.049":"A saber, que el dios gigante pronto<br>despertará de su letargo, rebosante de ira.","story.map4-dungeon6.050":"Je...<wait=40> <br>Parece que por fin tengo toda tu atención.","story.map4-dungeon6.051":"Calma.<wait=40><br>A juzgar por la intensidad de los temblores,","story.map4-dungeon6.052":"el dios gigante aún no ha despertado del todo.","story.map4-dungeon6.053":"Según la inscripción de las ruinas,<br>cuando el gigante por fin despierte,","story.map4-dungeon6.054":"toda esta isla será engullida<br>en un instante.","story.map4-dungeon6.055":"Vamos.<wait=40><br>Debemos partir de inmediato.","story.map4-dungeon6.056":"Las ruinas donde yace el dios gigante deberían estar justo al otro lado de este túnel.","story.map4-dungeon7.001":"...Sí. <wait=40>Grantos sigue adormilado,<br>pero ya está despierto.","story.map4-dungeon7.002":"No, señor, <wait=40>eso no será<br>un problema.","story.map4-dungeon7.003":"Por supuesto, señor.<wait=40><br>Le informaré de cualquier novedad.","story.map4-dungeon7.004":"¡Eh, <wait=40>mujer!","story.map4-dungeon7.005":"¿Ya casi has terminado de cotillear<br>por ahí?","story.map4-dungeon7.006":"¿Me estás delatando a alguno de tus<br>amiguitos imperiales o qué?","story.map4-dungeon7.007":"Je. No se te escapa una, ¿eh?","story.map4-dungeon7.008":"El Imperio tiene un gran interés en<br>los Invocadores jóvenes con talento.","story.map4-dungeon7.009":"¡Bah!<wait=40><br>¡Pues el interés no es mutuo!","story.map4-dungeon7.010":"...!","story.map4-dungeon7.011":"¡Eh, <rep_handlename>!<br>¿Podrías darte un poco de prisa?","story.map4-dungeon7.012":"Por si no te habías dado cuenta, ¡estamos<br>en plena emergencia!","story.map4-dungeon7.013":"Si tanta prisa tienes,<br>¿por qué no te adelantaste sin nosotros?","story.map4-dungeon7.014":"¡Puede que no estéis a la altura del gran Lugina, pero hasta los aficionados servís para algo!","story.map4-dungeon7.015":"Je...","story.map4-dungeon7.016":"Bien, escuchad.<wait=40><br>Voy a acabar con Grantos,","story.map4-dungeon7.017":"el dios gigante que lleva dormido<br>cientos de años.","story.map4-dungeon7.018":"Como soy tan poderoso,<br>yo me encargaré del trabajo duro.","story.map4-dungeon7.019":"Dicho esto, no quiero que me molesten<br>unos esbirros pesados mientras tanto.","story.map4-dungeon7.020":"Ahí entráis vosotros.<wait=40> ¡Atraeréis su atención mientras yo me encargo del grandullón!","story.map4-dungeon7.021":"¿Vas a enfrentarte tú solo a un<br>monstruo tan grande? Qué caballeroso...","story.map4-dungeon7.022":"¿Sarcasmo, quizá?","story.map4-dungeon7.023":"¡Como si vosotros tuvierais lo que hace falta<br>para enfrentaros cara a cara a un gigante así!","story.map4-dungeon7.024":"Prefiero enfrentarme a él yo solo a tener que sacaros de apuros cuando todo se tuerza.","story.map4-dungeon7.025":"Ya veréis, <wait=40>os enseñaré lo que es el verdadero poder.","story.map4-dungeon7.026":"¿Ha quedado claro? <wait=40>¡Vosotros distraed a los esbirros mientras yo salvo el mundo!","story.map4-dungeon7.027":"Y recordad: si la fastidiáis,<br>¡os destripo con vuestras propias espadas!","story.map4-dungeon7.028":"Desde luego, es lo bastante mandón<br>para dirigir un regimiento de Cazademonios...","story.map4-dungeon7.029":"Su tono deja mucho que desear,","story.map4-dungeon7.030":"pero al menos parece capaz<br>y bien informado.","story.map4-dungeon7.031":"Por no hablar de que ha reunido más<br>datos de los que esperaba.","story.map4-dungeon7.032":"Aun así, a juzgar por lo que he descubierto,","story.map4-dungeon7.033":"es imposible que pueda enfrentarse<br>él solo a Grantos.","story.map4-dungeon7.034":"Supongo que tendré que echarle una mano.","story.map4-dungeon7.035":"Por supuesto,<wait=40><br>también necesitará tu ayuda.","story.map4-dungeon7.036":"Es hora de ver de qué eres capaz<br>de verdad.","story.map4-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map4-dungeon_ex_clear.002":"¡Lo lograste, <rep_handlename>!","story.map4-dungeon_ex_clear.003":"¡Muchísimas gracias!","story.map4-dungeon_ex_clear.004":"¡Sabía que podías hacerlo!","story.map4-dungeon_ex_clear.005":"¡Eres lo mejor!","story.map4-dungeon_ex_clear.006":"Jeje, <wait=20>perdona, me he dejado llevar un poco.","story.map4-dungeon_ex_clear.007":"En fin, ya sabemos qué era ese monstruo.","story.map4-dungeon_ex_clear.008":"Parece que en un principio los gigantes lo tenían para encargarse de la basura.","story.map4-dungeon_ex_clear.009":"Sin embargo, pronto creció tanto que ni siquiera ellos podían controlarlo. ","story.map4-dungeon_ex_clear.010":"Al final, cierto héroe lo encerró en aquel lugar.","story.map4-dungeon_ex_clear.011":"Ese héroe debía de ser increíblemente fuerte para someter a un monstruo que ni los gigantes podían controlar.","story.map4-dungeon_ex_clear.012":"Ah, <wait=20>¡pero claro que tú también eres fuerte!","story.map4-dungeon_ex_clear.013":"¡Es decir, derrotaste a ese monstruo enorme sin ayuda de nadie!","story.map4-dungeon_ex_clear.014":"Y era tan viscoso y asqueroso...","story.map4-dungeon_ex_clear.015":"¡Te admiro muchísimo, <rep_handlename>!","story.map4-dungeon_ex_clear.016":"Eh, ¿qué es eso?","story.map4-dungeon_ex_clear.017":"Tienes algo en el hombro. <wait=20>¿No será...?","story.map4-dungeon_ex_clear.018":"<size=21>¡Kyaaaaahh!</size>","story.map4-dungeon_ex_clear.019":"<size=21>¡Puaj, está todo viscoso!</size>","story.map4-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map4-dungeon_ex_open.002":"¡Señor, <wait=20>tenemos problemas! <wait=40>¡Problemas gordos!","story.map4-dungeon_ex_open.003":"¡Perdón! No pretendía causar el pánico...","story.map4-dungeon_ex_open.004":"Soy Lin Merylham, de Apoyo Logístico...","story.map4-dungeon_ex_open.005":"...de la Oficina de Investigación del Departamento de Exploración de Grand Gaia, a tu servicio.","story.map4-dungeon_ex_open.006":"¡¿C-<wait=20>Cómo puedes mantener la calma en un momento así?!","story.map4-dungeon_ex_open.007":"<rep_handlename>, como miembro del Ejército de Invocadores del Salón de Invocadores de Akras...","story.map4-dungeon_ex_open.008":"...¡te pedimos que investigues la Caverna de Ignia!","story.map4-dungeon_ex_open.009":"Parece que había un monstruo dormido tras las Cataratas de Ignia.","story.map4-dungeon_ex_open.010":"Sin embargo, el terremoto de Cordelica del otro día parece haberlo despertado.","story.map4-dungeon_ex_open.011":"Y en cuanto al monstruo...","story.map4-dungeon_ex_open.012":"¡Es todo húmedo y pegajoso, y se lo come todo!","story.map4-dungeon_ex_open.013":"Solo de imaginarme un monstruo tan enorme y asqueroso me dan escalofríos.","story.map4-dungeon_ex_open.014":"<size=21>¡Kyaaaaaahh! ¡Qué asco!</size>","story.map4-ending.001":"Je, <wait=40>tal como sospechaba.","story.map4-ending.002":"No me extraña que Karl te tenga en tan alta estima.","story.map4-ending.003":"(Uf... <wait=40>jadeo...)","story.map4-ending.004":"Vaya, <wait=40>¡mira quién ha llegado por fin!","story.map4-ending.005":"...<wait=40>Uf, ya empezamos otra vez.","story.map4-ending.006":"¿Supongo que ya te has enterado?","story.map4-ending.007":"<rep_handlename> acaba de derrotar<br>a Grantos.","story.map4-ending.008":"Al final no hicieron falta tus servicios.<br>Y después de tanto alardear...","story.map4-ending.009":"S-Serás...<wait=40><br>¡Si lo que quieres es pelea, te reto aquí mismo!","story.map4-ending.010":"Ya puedes dejar de fanfarronear.<wait=40><br>Tuviste tu oportunidad y la desperdiciaste.","story.map4-ending.011":"¡C-Cierra el pico!<wait=40><br>¡La información que descubrí era correcta!","story.map4-ending.012":"Ese maldito gigante debió de cambiar de posición o algo...","story.map4-ending.013":"Te concedo esto: llegaste a las mismas conclusiones que yo,","story.map4-ending.014":"y lograste despachar a algunos monstruos duros de camino aquí.","story.map4-ending.015":"Sin embargo, no lograste completar tu misión.","story.map4-ending.016":"¿De qué sirve lo bueno que seas si fallas cuando de verdad importa?","story.map4-ending.017":"Grr...<wait=40> ¡Ya te enseñaré yo!<br>¡¿Y tú qué sabrás?!","story.map4-ending.018":"¡Se acabó! ¡Me largo!","story.map4-ending.019":"¡Yo nunca pedí hacer de niñera de vosotros, y mira dónde he acabado!","story.map4-ending.020":"¡Me vuelvo a Elgaia!","story.map4-ending.021":"Además, tengo que entregar mi informe<br>a esos carcamales del Salón de Invocadores.","story.map4-ending.022":"......","story.map4-ending.023":"¡Eh!<wait=40> ¡<rep_handlename>!","story.map4-ending.024":"¡No te creas el rey del mundo solo porque tuviste suerte al derrotar a Grantos!","story.map4-ending.025":"¡Yo podría haberlo vencido con los ojos<br>cerrados y una mano a la espalda!","story.map4-ending.026":"¡De hecho, deberías darme las gracias!","story.map4-ending.027":"¡Sí, eso es! <wait=40>¡Dar las gracias al Invocador más poderoso de todo el Salón de Invocadores de Akras por cuidar de ti!","story.map4-ending.028":"Ejem.<wait=40> ¿No es Karl, del escuadrón Rebluens, el más poderoso del Salón de Invocadores?","story.map4-ending.029":"¿Es que buscas que te ponga<br>un ojo morado o qué?","story.map4-ending.030":"¡Deja de decir ese nombre!","story.map4-ending.031":"¡Tengo más talento en el meñique que ese farsante en todo el cuerpo!","story.map4-ending.032":"¡Ese aguafiestas solo estuvo en el sitio adecuado en el momento adecuado, nada más!","story.map4-ending.033":"En Randall dicen que derrotó él solo a Sagamur, el Dragón Infernal.","story.map4-ending.034":"Después de eso, dicen que lo reclutaron personalmente para la Guardia Imperial.","story.map4-ending.035":"¡Ja! ¡¿Él?!<wait=40><br>Puede que asestara el golpe final,","story.map4-ending.036":"¡pero fue otro regimiento el que<br>de verdad lo puso de rodillas!","story.map4-ending.037":"Y sí,<wait=40> por si te lo preguntas,<wait=40>","story.map4-ending.038":"¡ese otro regimiento era Sky Garden, muchas gracias!","story.map4-ending.039":"Ah, sí, <wait=40>ahora lo recuerdo.","story.map4-ending.040":"Algo sobre que el líder de Sky Garden se desmayó al oír aullidos en la oscuridad...","story.map4-ending.041":"¡¿Pero qué?!","story.map4-ending.042":"¡E-Eso no es lo que pasó!","story.map4-ending.043":"¡Arriesgué mi vida para proteger a esos debiluchos de lo que fuera que acechaba allí!","story.map4-ending.044":"¡Gracias a mí pudieron<br>siquiera luchar!","story.map4-ending.045":"¡Si yo no hubiera estado allí, no habrían tenido ni la más remota posibilidad de ganar!","story.map4-ending.046":"Jeje. <wait=40>En ese caso, debo<br>disculparme por dudar del gran líder de Sky Garden.","story.map4-ending.047":"¡Desde luego que sí!","story.map4-ending.048":"Tsk... <wait=40>Por esto no<br>soporto a ese farsante de Karl.","story.map4-ending.049":"¿Dónde está su respeto?<br>¡Soy su superior, por el amor de Dios!","story.map4-ending.050":"Me da igual que seas tú<br>o esa descarada imperial sin cerebro,","story.map4-ending.051":"¡cualquiera que se ponga del lado de Karl no es más que una espina clavada en mi costado!","story.map4-ending.052":"¡Escucha bien, <rep_handlename>, porque solo lo diré una vez!","story.map4-ending.053":"La próxima vez que te interpongas en mi camino,","story.map4-ending.054":"¡te daré tal paliza que no podrás sentarte en una semana!","story.map4-ending.055":"¡A menos que eso te apetezca, te sugiero que empieces a mostrarme algo de respeto!","story.map4-ending.056":"¡Soy el grande y poderoso Lugina, y que no se te olvide!","story.map4-ending.057":"Je...<wait=40> <br>Bueno, podría haber ido mejor.","story.map4-ending.058":"Hablando de lo cual,<wait=40><br>ya va siendo hora de que yo también me vaya.","story.map4-ending.059":"Si aún quieres dar con los Cuatro Dioses Caídos,<wait=40> quizá nuestros caminos vuelvan a cruzarse algún día.","story.map4-ending.060":"Espero con ganas luchar a tu lado<br>en el futuro.","story.map4-ending.061":"Buena suerte,<br>valiente guerrero.","story.map4-ending.062":"––Ya veo.<wait=40><br>Así que no estaba en Cordelica, después de todo...","story.map4-ending.063":"––Ya lo sospechaba,<wait=40><br>pero no puedo evitar sentirme algo decepcionado.","story.map4-ending.064":"––¿Hmm?<wait=40><br>No tienes nada de que disculparte.","story.map4-ending.065":"––Si acaso, soy yo quien debería<br>disculparse por enviarte a una búsqueda inútil.","story.map4-ending.066":"––Sí, por supuesto.<wait=40><br>Sigue así.","story.map4-ending.067":"––Recuerda, cuento contigo.","story.map4-ending.068":"Jeje...","story.map4-ending.069":"Así que <wait=40>el joven Invocador<br>logró derrotar a Grantos...","story.map4-ending.070":"Tal como esperaba.","story.map4-ending.071":"Parece que el mundo avanza<br>en la dirección correcta, en efecto.","story.map4-ending.072":"Ahora solo falta que Paris se dé prisa<br>y encuentre lo que de verdad duerme en Grand Gaia.","story.map4-ending.073":"......","story.map4-ending.074":"Me estás escuchando, supongo.","story.map4-ending.075":"El reloj ya está en marcha.<wait=40><br>Ya no hay vuelta atrás.","story.map4-ending.076":"Más vale que tu amo se prepare<br>para lo que se avecina.","story.map4-ending.077":"......","story.map4-ending.078":"...<wait=40>Jeje.","story.map4-ending.079":"<size=20>¡Muajaja!","story.map4-open.001":"(Toc, <wait=20>toc.)","story.map4-open.002":"Disculpe, señor.","story.map4-open.003":"Según nuestras fuentes del gobierno,","story.map4-open.004":"el Salón de Invocadores de Akras ha tomado<br>el control de la región sur de Mistral.","story.map4-open.005":"...<wait=40>Sí, <wait=40>eso he oído.","story.map4-open.006":"También se están convirtiendo en una<br>fuerza formidable en Grand Gaia.","story.map4-open.007":"Eso parece...","story.map4-open.008":"Paris,<wait=40><br>quiero que vayas a Cordelica.","story.map4-open.009":"Necesito que me mantengas informado<br>de cualquier novedad en la frontera.","story.map4-open.010":"...<wait=40>Por supuesto, señor.<wait=40><br>...<wait=40>¿Y en cuanto a mis tareas habituales?","story.map4-open.011":"Yo le explicaré la situación al Emperador.","story.map4-open.012":"Gracias, señor.<wait=40><br>En ese caso, me despido.","story.map4-open.013":"......","story.map4-open.014":"...Oh,<wait=40><br>no te había visto.","story.map4-open.015":"Nunca has sido de llamar a la puerta, ¿verdad?","story.map4-open.016":"......","story.map4-open.017":"El Salón de Invocadores de Akras <wait=40>y el Gobierno de la Federación de Elgaia...<wait=60><br>La Facción de Abel está moviendo ficha...","story.map4-open.018":"......","story.map4-open.019":"...<wait=40>Jeje.","story.map4-open.020":"<size=20>¡Muajaja!","story.map4-open.021":"Parece que las cosas están a punto<br>de ponerse interesantes...","story.map5-dungeon1.001":"...<wait=40>Este lugar es bastante deprimente. ","story.map5-dungeon1.002":"Parece que la lucha también llegó hasta aquí.","story.map5-dungeon1.003":"Qué trágico...","story.map5-dungeon1.004":"Debemos hacer todo lo posible para que esto no vuelva a ocurrir.","story.map5-dungeon1.005":"¡Vaya, <wait=40><rep_handlename>,<wait=40> qué cara de seguridad tienes!","story.map5-dungeon1.006":"¡Eso es, <wait=40>vamos a acabar con ese malvado Cardes!","story.map5-dungeon1.007":"¿Eh? <wait=40>¿Que quién es Cardes?","story.map5-dungeon1.008":"¡Ay, perdona!<wait=40> <br>¡¿No te había hablado de él?!","story.map5-dungeon1.009":"Ejem, <wait=40>bueno, <wait=40>¡llegó la hora de los cuentos de Tilith!","story.map5-dungeon1.010":"Este, el archipiélago de Palmyna, lo gobierna \\"Cardes el Malévolo\\", uno de los Cuatro Dioses Caídos. ","story.map5-dungeon1.011":"¡Nuestro objetivo ahora, <rep_handlename>, es derrotarlo!","story.map5-dungeon1.012":"¡Y tendrás que andarte con cuidado, porque es mucho más fuerte que Maxwell! ","story.map5-dungeon1.013":"¡Pero no hay de qué preocuparse!","story.map5-dungeon1.014":"De hecho, <wait=20>la mayor parte del poder de Cardes está sellada ahora mismo.","story.map5-dungeon1.015":"Dicen que lo sellaron durante la gran guerra en lo más profundo de Palmyna, en un lugar llamado \\"Mundo Espiritual\\"...","story.map5-dungeon1.016":"Aquí debió de haber humanos muy impresionantes aparte de ti, <rep_handlename>.","story.map5-dungeon1.017":"Espera,<wait=40> un momento...","story.map5-dungeon1.018":"Eso significa que Cardes siguió gobernando esta tierra incluso con sus poderes sellados, ¿no? ","story.map5-dungeon1.019":"Puede que sea aún más poderoso de lo que imaginaba...","story.map5-dungeon1.020":"...<wait=20>...","story.map5-dungeon1.021":"En fin, <wait=40>¡tenemos que derrotarlo de todos modos!","story.map5-dungeon1.022":"¡Aunque para ti no será ningún problema, <rep_handlename>!","story.map5-dungeon1.023":"Debería irme ya. <wait=20>¡Tengo que investigar más sobre Cardes!","story.map5-dungeon1.024":"¡¡Buena suerte!!","story.map5-dungeon2.001":"<size=14>¡<rep_handlename>!","story.map5-dungeon2.002":"<size=14>¿D-<wait=20>Dónde estás?","story.map5-dungeon2.003":"<size=20>¡¡Aaaah!!","story.map5-dungeon2.004":"...¡N-<wait=40>No me asustes así por la espalda!","story.map5-dungeon2.005":"¿Eh?<wait=40><br>¿Que de qué tengo miedo?","story.map5-dungeon2.006":"¡D-<wait=40>De nada!","story.map5-dungeon2.007":"¡N-<wait=41>No le tengo miedo a nada!","story.map5-dungeon2.008":"¡Los barcos fantasma y esas cosas no dan ningún miedo!","story.map5-dungeon2.009":"¡Vamos, <wait=40>que hasta podría vivir aquí!","story.map5-dungeon2.010":"¡Ah!<wait=40> ¡Ya entiendo!","story.map5-dungeon2.011":"Lo dices porque tú también tienes miedo, <wait=40>¡¿verdad, <rep_handlename>?!","story.map5-dungeon2.012":"¡Jiji, <wait=40><rep_handlename> es un miedica!","story.map5-dungeon2.013":"Haberlo dicho, <wait=40>yo te habría protegido.","story.map5-dungeon2.014":"¡Es que, <wait=20>como diosa, no solo soy guapa, también soy dura!","story.map5-dungeon2.015":"¡Sí, <wait=20>eso es!","story.map5-dungeon2.016":"Parece que por aquí hay un monstruo que devora almas humanas, ¡así que mantente alerta!","story.map5-dungeon2.017":"<size=18>*Chof*","story.map5-dungeon2.018":"<size=20>¿Eh?<wait=40> ¡¿Q-Qué ha sido eso?!","story.map5-dungeon2.019":"¿L-Lo has oído, <wait=20>ese ruido tan raro de ahora?","story.map5-dungeon2.020":"¿Eh?<wait=40> ¿Que eran tus pasos?","story.map5-dungeon2.021":"...<wait=40>...<wait=40>...","story.map5-dungeon2.022":"<size=20>¡<rep_handlename>, eres tonto!","story.map5-dungeon2.023":"Te traía información importante, <wait=40>¡pero ahora ya no me apetece contártela!","story.map5-dungeon2.024":"¡Me voy a casa!","story.map5-dungeon2.025":"Jiji, <wait=40>¿de verdad te lo has creído?","story.map5-dungeon2.026":"¿Te he asustado?","story.map5-dungeon2.027":"Una diosa nunca se enfadaría tanto. ","story.map5-dungeon2.028":"En fin, <wait=40>según lo que he averiguado, Palmyna, el lugar donde está sellado Cardes...","story.map5-dungeon2.029":"...está más allá de Encervis, <wait=40>que queda justo pasado Amdahl.","story.map5-dungeon2.030":"¡Primero tenemos que cruzar el Castillo de Amdahl, <wait=40>y luego podremos atravesar Encervis!","story.map5-dungeon2.031":"Así que démonos prisa en cruzar esta zona, <wait=40>que me da muchísimo repelús...","story.map5-dungeon2.032":"<size=18>*Chof* *Chof*","story.map5-dungeon2.033":"¿Eh?","story.map5-dungeon2.034":"*Chap* *Chap*","story.map5-dungeon2.035":"<size=20>¡¡Aaah!!","story.map5-dungeon3.001":"<speed=10>Vaya, qué tenemos aquí...<wait=40><br>Este es muy distinto de los otros Invocadores.","story.map5-dungeon3.002":"Lo he decidido, <wait=20>acabaré contigo aquí mismo.","story.map5-dungeon3.003":"No tienes por qué preocuparte.<wait=50><br>Todo terminará pronto.","story.map5-dungeon3.004":"Esta presencia...<wait=20>...","story.map5-dungeon3.005":"Ah, ya veo...","story.map5-dungeon3.006":"¡Ahí estás!","story.map5-dungeon3.007":"Oye, <wait=40>¿pasa algo?<wait=40> Tienes cara de preocupación.","story.map5-dungeon3.008":"¡Deberías estar más contento con este tiempo tan bueno! ¡Venga, sonríeme!","story.map5-dungeon3.009":"Además, me tienes a mí, <wait=40>¡así que anímate!","story.map5-dungeon3.010":"Y aparte, <wait=40>mira qué tranquilo es este lugar.","story.map5-dungeon3.011":"Me encantaría pasar un rato relajándome en sitios así contigo, <rep_handlename>.","story.map5-dungeon3.012":"Jiji, <wait=40>¡es broma!","story.map5-dungeon3.013":"Tienes una misión importante: acabar con los Cuatro Dioses Caídos, <rep_handlename>.","story.map5-dungeon3.014":"¡No tienes tiempo para holgazanear!","story.map5-dungeon3.015":"¿Eh? <wait=40>¿Y yo qué?","story.map5-dungeon3.016":"Pues claro que yo tampoco tengo tiempo...<wait=40> O sea...","story.map5-dungeon3.017":"¡¿No estarás pensando,<wait=40> por casualidad, que yo solo estoy aquí haciendo el tonto?!","story.map5-dungeon3.018":"¡¡Qué descaro!!","story.map5-dungeon3.019":"¡Hago todo lo que puedo para ayudarte, <rep_handlename>!","story.map5-dungeon3.020":"¿Eh? <wait=40>¿Por ejemplo?","story.map5-dungeon3.021":"P-<wait=40>Pues hay tantas cosas que no puedo explicarlo con palabras...<wait=40> *M<size=15>u<size=14>r<size=13>m<size=12>u<size=11>r* <size=12>*M<size=11>u<size=10>r<size=9>m<size=8>u<size=7>r<size=6>*","story.map5-dungeon3.022":"En fin, <wait=40>¡basta ya de hablar de mí!","story.map5-dungeon3.023":"¡Lo importante ahora es el camino que tenemos por delante!","story.map5-dungeon3.024":"Bueno, <wait=40>¡pongamos rumbo al Castillo de Amdahl!","story.map5-dungeon4.001":"Puaj, <wait=20>¡qué horror! <wait=40>¡Este sitio es asqueroso!","story.map5-dungeon4.002":"¡Ni siquiera Graham pondría un pie en un sitio así!","story.map5-dungeon4.003":"Ya te lo he explicado, ¿no?","story.map5-dungeon4.004":"Es muy probable que Graham esté en Edila, el pueblo fantasma que hay justo pasadas estas minas.","story.map5-dungeon4.005":"¡Deja ya de quejarte! <wait=40> ¡Tenemos que seguir adelante!","story.map5-dungeon4.006":"En cualquier caso, <wait=40>¡parece que el Salón de Invocadores no nos da más que información falsa!","story.map5-dungeon4.007":"De verdad, Seria, <wait=40>eres la mujer más dura que conozco...","story.map5-dungeon4.008":"¿Hm?<wait=40> ¡Oh!<wait=40> ¡<rep_handlename>!","story.map5-dungeon4.009":"Hmpf...","story.map5-dungeon4.010":"¡Así que al final tú también has venido al archipiélago de Palmyna!","story.map5-dungeon4.011":"Ya pensaba que, si alguien podía llegar, serías tú, <rep_handlename>.","story.map5-dungeon4.012":"Supongo que vas tras Cardes, ¿no?","story.map5-dungeon4.013":"Jaja, <wait=40>tengo la sensación de que no podrá contigo después de cómo te encargaste de Maxwell. ","story.map5-dungeon4.014":"¡Hmpf! <wait=40>No te lo creas tanto, <wait=40>que te puede pasar algo malo.","story.map5-dungeon4.015":"¿Qué dices ahora? <wait=50> ¿Por qué no tratas a <rep_handlename> con algo más de respeto?<wait=40>","story.map5-dungeon4.016":"*Coscorrón*","story.map5-dungeon4.017":"<size=18>¡N-<wait=20>No he dicho nada! <wait=40>¡De verdad, ya paro!","story.map5-dungeon4.018":"En fin, <wait=40>en el archipiélago de Palmyna hay un subordinado de Cardes al que temen hasta las fuerzas más poderosas...","story.map5-dungeon4.019":"¡Si dudas aunque sea un poco, estás acabado!","story.map5-dungeon4.020":"Ay, Seria...","story.map5-dungeon4.021":"Aunque, en realidad, <wait=40>algo de razón tiene. ","story.map5-dungeon4.022":"De hecho, <wait=40>aparte de Graham, al que estamos persiguiendo...","story.map5-dungeon4.023":"...Corren rumores de que por estos lares hay una bestia igual o más poderosa llamada Zebra. ","story.map5-dungeon4.024":"Toda precaución es poca, <wait=40>así que avancemos con cuidado. ","story.map5-dungeon4.025":"Por cierto, <wait=40>¿qué ha sido de esa diosa?","story.map5-dungeon4.026":"Ibais los dos pegados como uña y carne...","story.map5-dungeon4.027":"¡Ah, ya lo entiendo!<wait=40> ¡¿Por fin se ha hartado de lo soso que eres?!","story.map5-dungeon4.028":"Seria, <wait=40>ya basta.","story.map5-dungeon4.029":"...<wait=40>Solo era una bromita.","story.map5-dungeon4.030":"Vamos hacia Edila, que está justo delante, persiguiendo a Graham. ","story.map5-dungeon4.031":"Me gustaría que luchásemos juntos, <wait=40>pero con una compañera tan pesada como tú...","story.map5-dungeon4.032":"No estaba siendo pesada...","story.map5-dungeon4.033":"Jaja... <wait=40>Entonces, ¿piensas seguir tú solo?","story.map5-dungeon4.034":"Más adelante te esperan enemigos muy feroces,<wait=40> ¡pero creo que sobreviviremos para volver a vernos!","story.map5-dungeon4.035":"¡Karl! <wait=40>No tenemos tiempo que perder, ¡sigamos adelante!","story.map5-dungeon4.036":"¡Procura no acabar siendo presa de esos demonios!","story.map5-dungeon4.037":"¡E-<wait=40>Eh, <wait=40>espera!","story.map5-dungeon4.038":"Madre mía... <wait=40>Bueno, <wait=20>¡hasta la próxima, <rep_handlename>!","story.map5-dungeon5.001":"Ah, <wait=40>¡qué maravilla!","story.map5-dungeon5.002":"¡Oh, <wait=40><rep_handlename>!","story.map5-dungeon5.003":"Has llegado sano y salvo. <wait=40>¡Sabía que lo conseguirías!","story.map5-dungeon5.004":"Aunque confiaba en ti, me alivia verte.","story.map5-dungeon5.005":"¿Eh? <wait=40>¿Que qué estaba haciendo?","story.map5-dungeon5.006":"Jiji, <wait=40>¡pues disfrutar del santuario, claro!","story.map5-dungeon5.007":"Cada rincón bañado de luz, <wait=20>no hay nada como un buen santuario.","story.map5-dungeon5.008":"Este ambiente solemne y toda esta luz tan bonita son irresistibles para una diosa como yo.","story.map5-dungeon5.009":"¡Y aquí no hay ruidos raros como los que oímos en el barco fantasma!","story.map5-dungeon5.010":"<size=18>*Frus* *Frus*","story.map5-dungeon5.011":"¡¿Qué ha sido eso?!<wait=40> ¡¿Quién anda ahí?!","story.map5-dungeon5.012":"Jo, jo, jo. <wait=40><br>¿Te he asustado?","story.map5-dungeon5.013":"Perdóname, <wait=20>jovencita.","story.map5-dungeon5.014":"No pretendía asustarte, <wait=40>es que tienes una voz muy agradable. ","story.map5-dungeon5.015":"Ah, <wait=40>e-<wait=40>esto...","story.map5-dungeon5.016":"¿Quién eres, abuelo?","story.map5-dungeon5.017":"Jo, jo, jo. <wait=40><br>Discúlpame.","story.map5-dungeon5.018":"Me llamo Grah. <wait=40><br>Llámame Elder Grah, por favor.","story.map5-dungeon5.019":"Elder Grah, ¿eh?...","story.map5-dungeon5.020":"Jo, jo, jo. <wait=40><br>Un buen nombre, ¿no te parece?","story.map5-dungeon5.021":"Ya te he dicho mi nombre, <wait=40>¿no me dirás el tuyo?","story.map5-dungeon5.022":"Esto, <wait=40>¡me llamo Tilith! <wait=40>Soy una chica normal, como cualquier otra.","story.map5-dungeon5.023":"¡Y esta encantadora persona de aquí es <rep_handlename>!","story.map5-dungeon5.024":"¡<rep_handlename> es un Invocador increíblemente fuerte!","story.map5-dungeon5.025":"Qué valiente.","story.map5-dungeon5.026":"Y dime, Elder Grah, <wait=40>¿qué te trae a un lugar como este?","story.map5-dungeon5.027":"Bueno, <wait=40>solo iba a dar un paseo por allí.","story.map5-dungeon5.028":"Un paseo, dices...","story.map5-dungeon5.029":"Creía que esta zona estaba llena de monstruos...","story.map5-dungeon5.030":"Hmm, <wait=20>pues parece que no me hicieron ni caso. ","story.map5-dungeon5.031":"Hmm...<wait=40> Sigues pareciéndome un poco sospechoso...","story.map5-dungeon5.032":"Mira qué armas tan poderosas llevas...","story.map5-dungeon5.033":"Je, je, je...","story.map5-dungeon5.034":"¡Parece que me habéis descubierto!","story.map5-dungeon5.035":"En realidad, <wait=20>¡soy Grah, el dios que gobierna esta tierra!","story.map5-dungeon5.036":"¡Y ahora haré que desaparezcáis de ella ahora mismo!","story.map5-dungeon5.037":"¡¿Pero qué...?!","story.map5-dungeon5.038":"Solo os estoy tomando el pelo.","story.map5-dungeon5.039":"Jo, jo, jo. <wait=40><br>¿Os he asustado?","story.map5-dungeon5.040":"Estás monísima cuando te sorprendes, jovencita.","story.map5-dungeon5.041":"¡Pfffff!","story.map5-dungeon5.042":"Perdóname, por favor.","story.map5-dungeon5.043":"Hace mucho tiempo, viví una especie de aventura. ","story.map5-dungeon5.044":"Usé esta lanza en aquella época, <wait=40>aunque ahora apenas sirve de adorno.","story.map5-dungeon5.045":"He venido a investigar la leyenda de los Cuatro Héroes de antaño, <wait=40>pero dudo que encuentre aquí nada importante.","story.map5-dungeon5.046":"Bueno, <wait=40>creo que es hora de marcharme.","story.map5-dungeon5.047":"Haber conocido a un Invocador tan interesante, <wait=40>diría que ha sido un buen día. ","story.map5-dungeon5.048":"Bueno, <wait=40>espero con ganas nuestro próximo encuentro.","story.map5-dungeon5.049":"Ese abuelo, <wait=40>era un poco raro, ¿no?","story.map5-dungeon5.050":"No es que cualquier persona normal pueda pasearse por aquí así como así.","story.map5-dungeon5.051":"Seguro que esconde algo<wait=20>.<wait=20>.<wait=20>.","story.map5-dungeon5.052":"En fin, <wait=40>no sirve de nada preocuparse ahora.","story.map5-dungeon5.053":"¡No es que afecte en nada a nuestro objetivo!","story.map5-dungeon5.054":"Muy bien, <wait=40>¡crucemos esto rápido y vayamos hacia el Castillo de Amdahl!","story.map5-dungeon6.001":"¡Seria!<wait=40> ¡¿Cómo va por ahí?!","story.map5-dungeon6.002":"¡Nada!<wait=40> No hay ni rastro de él por ninguna parte...","story.map5-dungeon6.003":"¡Maldita sea! <wait=40>¡Se nos ha vuelto a escapar!","story.map5-dungeon6.004":"A este paso, <wait=40>nunca podremos vengarlos...","story.map5-dungeon6.005":"Karl...","story.map5-dungeon6.006":"<size=18>¡¿Eh?!<wait=40> <size=16>¿De dónde has salido?","story.map5-dungeon6.007":"Pero si es <rep_handlename>...","story.map5-dungeon6.008":"Jeje, <wait=40>parece que nos pillas en mal momento.","story.map5-dungeon6.009":"Una vez más, <wait=20>Graham se nos ha escurrido entre los dedos.","story.map5-dungeon6.010":"Comparados contigo, que has luchado con tanto valor contra los Cuatro Dioses Caídos, <wait=20>debemos de parecer patéticos...","story.map5-dungeon6.011":"¡Pero qué dices!","story.map5-dungeon6.012":"¡<rep_handlename> solo ha tenido suerte!<wait=40> ¡Karl, tú has vencido a enemigos cien veces más fuertes que los suyos!","story.map5-dungeon6.013":"Jaja, <wait=40>muchas gracias, Seria.","story.map5-dungeon6.014":"Es todo un privilegio recibir un cumplido tuyo.","story.map5-dungeon6.015":"¡Supongo que no tengo motivos para venirme abajo!","story.map5-dungeon6.016":"¿Qué quieres decir con \\"privilegio\\"?","story.map5-dungeon6.017":"Jaja, <wait=40>solo intento darte las gracias, nada más. ","story.map5-dungeon6.018":"Ah, y <rep_handlename>...","story.map5-dungeon6.019":"Si hemos vuelto a perder a Graham, no ha sido solo porque sea fuerte...","story.map5-dungeon6.020":"Cuando lo alcanzamos esta vez, <wait=40>había otro monstruo increíblemente fuerte con él.","story.map5-dungeon6.021":"Perdona que sea tan impreciso.","story.map5-dungeon6.022":"A decir verdad, <wait=40>no llegamos a ver a ese otro monstruo.","story.map5-dungeon6.023":"En cuanto sentimos su increíble poder, <wait=40>salimos literalmente volando.","story.map5-dungeon6.024":"Cuando recobramos el sentido, <wait=40>Graham había desaparecido.","story.map5-dungeon6.025":"Lo habríamos atrapado si no nos hubieran atacado así...","story.map5-dungeon6.026":"Seguramente tengas razón...","story.map5-dungeon6.027":"Sin embargo, <wait=40>lo único que sabemos con certeza es que ninguna persona normal podría tener semejante poder...","story.map5-dungeon6.028":"Y que lo digas...","story.map5-dungeon6.029":"En fin, <wait=40>hemos tenido la suerte de no sufrir muchas bajas.","story.map5-dungeon6.030":"Vamos a seguir buscando a Graham.","story.map5-dungeon6.031":"Tú vas hacia el Castillo de Amdahl, ahí delante, ¿verdad?","story.map5-dungeon6.032":"De allí también noto una presencia fuerte y peligrosa.","story.map5-dungeon6.033":"Asegúrate de tomar todas las precauciones.","story.map5-dungeon6.034":"¡Si te cruzas con ese monstruo, estás frito!","story.map5-dungeon6.035":"Jaja, <wait=40>tan dura con <rep_handlename> como siempre, por lo que veo.","story.map5-dungeon6.036":"N-<wait=40>No soy dura solo con <rep_handlename>...","story.map5-dungeon6.037":"¡Ahí estás!","story.map5-dungeon6.038":"¡¿Dónde estabas?! <wait=40>¡Te he buscado por todas partes!","story.map5-dungeon6.039":"¿Eh?<wait=40> ¿Y esto?<wait=40><br>A vosotros ya os conozco, ¿no?","story.map5-dungeon6.040":"...<wait=20>...","story.map5-dungeon6.041":"Hola, diosa.<wait=40> Cuánto tiempo sin vernos.","story.map5-dungeon6.042":"¡Ya lo creo que ha pasado tiempo!<wait=40> ¡Te veo en forma como siempre, Karl!","story.map5-dungeon6.043":"Y tú, <wait=40>¿has estado incordiando a mi querido <rep_handlename> como de costumbre?","story.map5-dungeon6.044":"<size=18>¡¿Cómo que \\"incordiando\\"?!","story.map5-dungeon6.045":"¡Y como ya te dije, <wait=40><rep_handlename> no es tuyo!","story.map5-dungeon6.046":"¿Por qué te pones así?<wait=40> ¿No será <wait=20>que tienes celos? ","story.map5-dungeon6.047":"...<wait=20>...","story.map5-dungeon6.048":"<size=18>*Clang*","story.map5-dungeon6.049":"<size=18>¡E-Esperad un momento!","story.map5-dungeon6.050":"¡Cálmate, Seria!","story.map5-dungeon6.051":"V-<wait=20>Venga, <wait=40>¡tenemos que volver a seguir la pista de Graham!","story.map5-dungeon6.052":"¡¿V-<wait=40>Verdad?!","story.map5-dungeon6.053":"<speed=14>¡Bueno, <wait=20><rep_handlename>!","story.map5-dungeon6.054":"<speed=14>¡Prometamos los dos darlo todo en el camino que nos espera!","story.map5-dungeon6.055":"<speed=14>¡Muy bien, nos vamos! ¡Tú también, Seria!","story.map5-dungeon6.056":"¡Karl! <wait=20> ¡Espera!<wait=40> ¡Ya lo entiendo, <wait=40>no hace falta que tires tan fuerte!","story.map5-dungeon6.057":"¡Diosa! <wait=40>¡Más te vale portarte bien!","story.map5-dungeon6.058":"¡¡Pfff!!","story.map5-dungeon6.059":"Uf, <wait=40>por fin se ha ido.","story.map5-dungeon6.060":"Aun así, <wait=40>¡espero que consigan derrotar a Graham!","story.map5-dungeon6.061":"Ya casi estamos. <wait=40>¡En cuanto crucemos esto, estaremos a las puertas del Castillo de Amdahl!","story.map5-dungeon6.062":"¡Cuento contigo!","story.map5-dungeon7.001":"Por fin hemos llegado.","story.map5-dungeon7.002":"Cruza el Castillo de Amdahl y tendrás vía libre hasta Encervis.","story.map5-dungeon7.003":"Y entonces estaremos un paso más cerca de Cardes y de la tierra donde está sellado.","story.map5-dungeon7.004":"Jiji, <wait=40>no pongas esa cara de nervios.","story.map5-dungeon7.005":"¡Sé que puedes hacerlo, <rep_handlename>!","story.map5-dungeon7.006":"¡Démonos prisa en cruzar este castillo!","story.map5-dungeon7.007":"¿De verdad crees que va a ser tan fácil?","story.map5-dungeon7.008":"¡¡Qué...!!","story.map5-dungeon7.009":"¿Te he vuelto a asustar?","story.map5-dungeon7.010":"¡Cómo te atreves! <wait=40>¡¡No me asustes así por la espalda!!","story.map5-dungeon7.011":"Jo, jo, jo.","story.map5-dungeon7.012":"Sigues tan mona como te recordaba, jovencita.","story.map5-dungeon7.013":"Hmpf, <wait=40>qué malo eres...","story.map5-dungeon7.014":"Jo, jo, jo.","story.map5-dungeon7.015":"En fin, <wait=40><rep_handlename>...","story.map5-dungeon7.016":"Tú también lo has notado, ¿verdad? <wait=40>La presencia malvada que hay más adelante...","story.map5-dungeon7.017":"Sí, <wait=40>lo veo en tu cara.","story.map5-dungeon7.018":"Muy bien, <wait=40>déjame hacerte el favor de contarte lo que te espera.","story.map5-dungeon7.019":"Justo más adelante te aguarda el antiguo señor de este castillo.","story.map5-dungeon7.020":"El último emperador del Imperio de Amdahl, que fue destruido por Palmyna. ","story.map5-dungeon7.021":"Ahora es un fantasma y guarda un gran rencor a los humanos.","story.map5-dungeon7.022":"Un fantasma que guarda rencor a los humanos...","story.map5-dungeon7.023":"Jo, jo, jo.","story.map5-dungeon7.024":"¿Qué esperabas?","story.map5-dungeon7.025":"No todo lo que existe aquí, en Grand Gaia, tiene por qué estar relacionado con los dioses.","story.map5-dungeon7.026":"Basta con mirar la historia de la humanidad para verlo...","story.map5-dungeon7.027":"Los humanos se han matado entre sí muchas más veces de las que los han destruido los dioses.","story.map5-dungeon7.028":"......","story.map5-dungeon7.029":"Jo, jo, jo.","story.map5-dungeon7.030":"En fin, <wait=40>ya soy un poco mayor para esto, <wait=40>creo que será mejor que me vaya.","story.map5-dungeon7.031":"Pero antes de irme, <wait=40>aunque sea una diosa, sigue teniendo sus debilidades.","story.map5-dungeon7.032":"Más te vale hacer lo posible por protegerla.","story.map5-dungeon7.033":"¿Eh?<wait=40> ¡Espera un momento!","story.map5-dungeon7.034":"Jo, jo, jo.","story.map5-dungeon7.035":"Se ha ido...","story.map5-dungeon7.036":"¿Cuándo le dije yo a Elder Grah que era una diosa?","story.map5-dungeon7.037":"Sabe tantas cosas, <wait=40>¿quién demonios es?","story.map5-dungeon7.038":"Ah, <wait=40>¡qué más da!","story.map5-dungeon7.039":"¡No sirve de nada preocuparse ahora! <wait=40>","story.map5-dungeon7.040":"¡Tenemos que cruzar esto antes de poder enfrentarnos a Cardes!","story.map5-dungeon7.041":"Bueno, <rep_handlename>, no sé qué pensar de todo este asunto del fantasma...","story.map5-dungeon7.042":"...pero, sea lo que sea, ¡vamos a tumbarlo! <wait=40>¡Seguro que eso sorprende a Elder Grah!","story.map5-ending.001":"¡Lo has conseguido, <rep_handlename>!","story.map5-ending.002":"¡Ese tipo era pan comido!","story.map5-ending.003":"¡Ni los fantasmas de los emperadores del pasado tienen nada que hacer contra ti, <rep_handlename>!","story.map5-ending.004":"<size=18>¡Vaya!","story.map5-ending.005":"¡¡Qué...!!","story.map5-ending.006":"Oye, <wait=40>¿por qué siempre intentas asustarme...?","story.map5-ending.007":"Perdona, <wait=40>es que yo siento lo mismo que tú, Tilith...","story.map5-ending.008":"A mí también me ha sorprendido cómo se ha encargado <rep_handlename> de ese espectro.","story.map5-ending.009":"Hmpf.","story.map5-ending.010":"Jo, jo, jo.","story.map5-ending.011":"Sin embargo, <wait=40>que <rep_handlename> haya vencido así al fantasma de un emperador...","story.map5-ending.012":"Jiji, <wait=40>¿a que sí?","story.map5-ending.013":"Significa que <rep_handlename> es un Invocador increíble de verdad, ¿no?","story.map5-ending.014":"Hmm, <wait=40>sin duda ha sido un magnífico choque de espadas.","story.map5-ending.015":"He de decir <wait=40>que lo has hecho muy bien.","story.map5-ending.016":"<size=18>¡<rep_handlename>!<wait=40> ¡¡Sigues vivo!!","story.map5-ending.017":"Uf... <wait=40>uf...","story.map5-ending.018":"E-<wait=40>Espera un momento...","story.map5-ending.019":"¿Q-<wait=40>Qué ha pasado con ese fantasma?","story.map5-ending.020":"¡<rep_handlename> lo ha derrotado!","story.map5-ending.021":"...<wait=40>...","story.map5-ending.022":"<size=14>Hmpf...<wait=40><br>¡¡Karrrrrrl!!","story.map5-ending.023":"¡¿Así que al final sí que estabas preocupada por <rep_handlename>, Seria?!","story.map5-ending.024":"Parece que tienes tu lado tierno.","story.map5-ending.025":"¡N-<wait=40>No es eso!<wait=40> Solo había oído que Graham había aparecido por aquí cerca...","story.map5-ending.026":"Venga, <wait=20>no hace falta que te escudes en una mentira tan descarada.","story.map5-ending.027":"Grrr...","story.map5-ending.028":"Jo, jo, jo.","story.map5-ending.029":"<size=20>¡¿?!","story.map5-ending.030":"Creo que no nos han presentado.","story.map5-ending.031":"Señorita Seria, <wait=40>llámame Elder Grah, por favor.","story.map5-ending.032":"¡¿Eh?!<wait=40> ¿E-<wait=40>Elder Grah?","story.map5-ending.033":"Así es.","story.map5-ending.034":"Eh, <wait=40>pero... <wait=40>o-<wait=40>o sea...","story.map5-ending.035":"Elder Grah.","story.map5-ending.036":"No lo olvides, <wait=40>señorita Seria.","story.map5-ending.037":"Elder Grah, <wait=40>¡sí que eres un abuelo raro!","story.map5-ending.038":"Siempre apareces de repente en sitios extraños, <wait=40>y sabes las cosas más rebuscadas.","story.map5-ending.039":"¡Y siempre intentas asustarme!","story.map5-ending.040":"¡¿Q-<wait=40>Q-<wait=40>Qué estás diciendo?!<wait=40> Este hombre es...","story.map5-ending.041":"...Elder Grah, un simple viejo bromista.","story.map5-ending.042":"¿Verdad, <wait=40>señorita Seria?","story.map5-ending.043":"¿Eh?<wait=40> A-<wait=40>Ah, <wait=20>sí...","story.map5-ending.044":"Jo, jo, jo.","story.map5-ending.045":"Hmpf, <wait=40>¡a ti te pasa algo raro, Seria!","story.map5-ending.046":"¡B-<wait=40>Bah, da igual! <wait=40>¡Solo tengo unas cuantas cosas en la cabeza!","story.map5-ending.047":"¿Como qué?","story.map5-ending.048":"¡N-<wait=40>No tienes por qué saberlo!","story.map5-ending.049":"Hmpf, <wait=40>¡pero qué te pasa!","story.map5-ending.050":"¿No estarás molesta porque Karl te engañó para que vinieras tras nosotros?","story.map5-ending.051":"¿Q-<wait=40>Qué? <wait=20>¡¿Cómo lo sabes?!","story.map5-ending.052":"¡Una diosa lo sabe todo!","story.map5-ending.053":"¡¿Y qué clase de diosa eres tú?!<wait=40> ¡Si no puedes hacer nada sola!","story.map5-ending.054":"¡Qué mala eres!","story.map5-ending.055":"Oye, <rep_handlename>, <wait=40>¡ayúdame y di algo!","story.map5-ending.056":"¿Para qué?<wait=40> Ya sabes lo que diría <rep_handlename>, ¿no?","story.map5-ending.057":"Jo, jo, jo.","story.map5-ending.058":"Los jóvenes rebosan vida.","story.map5-ending.059":"En fin, <rep_handlename>...","story.map5-ending.060":"Al derrotar a ese espectro, <wait=40>has roto la barrera que cubría esta región.","story.map5-ending.061":"Pronto se abrirá el camino hacia Encervis.","story.map5-ending.062":"Allí debería estar esperándote Zebra...","story.map5-ending.063":"...el demonio que gobierna ahora el archipiélago de Palmyna en lugar de Cardes.","story.map5-ending.064":"Entrena duro y no dejes que el orgullo se interponga en tu camino.","story.map5-ending.065":"¡Ah!<wait=40> ¡Eso iba a decirlo yo!","story.map5-ending.066":"Todo lo que dices son tonterías, <wait=40>deberías dejarle esto a Grahde...","story.map5-ending.067":"¡Elder Grah! ¡Déjaselo a Elder Grah!","story.map5-ending.068":"¡¿Cómo que tonterías?!","story.map5-ending.069":"¿Qué tiene de malo decirte lo que eres de verdad?","story.map5-ending.070":"¡Se acabó!<wait=40> ¡Te voy a enseñar el verdadero poder de una diosa!","story.map5-ending.071":"¡Adelante!<wait=50> ¡Te demostraré lo mucho más fuerte que soy que tú!","story.map5-ending.072":"<size=20>¡¡Más te vale estar preparada!!","story.map5-ending.073":"Jo, jo, jo.","story.map5-ending.074":"Menudo par de jovencitas con sangre caliente.","story.map5-ending.075":"En fin, <wait=40><rep_handlename>...","story.map5-ending.076":"Deberíamos volver a Elgaia.","story.map5-ending.077":"¡<rep_handlename>! <wait=40>¡Espera un segundo!","story.map5-ending.078":"¡Tengo un mensaje de Karl!","story.map5-ending.079":"Dice: \\"Creo en tu fuerza\\".","story.map5-ending.080":"¡¿De verdad es momento para eso?!","story.map5-ending.081":"¡<rep_handlename>!","story.map5-ending.082":"¡Vamos a Encervis después de darle a Seria una lección rápida de respeto!","story.map5-ending.083":"Si crees que puedes ganarme, <wait=40>¡inténtalo!","story.map5-ending.084":"¡¡Se acabó!!<wait=40> ¡Ahora verás mi inmenso poder mágico!","story.map5-ending.085":"Hmpf, <wait=40>parece que vas en serio. <wait=40>Vale, <wait=40>¡vamos allá!","story.map5-ending.086":"<size=20>¡¡Toma esto!!","story.map5-ending.087":"Bueno, <wait=40>supongo que nos vamos...","story.map5-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Tú, <rep_handlename>,<wait=40> que derrotaste a Maxwell, Diosa de la Creación…","story.map5-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>La crisis desatada por los Cuatro Dioses Caídos<wait=40> aún persiste…","story.map5-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Para traer una nueva esperanza a este mundo tan impregnado de tristeza…","story.map5-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Debes tener fe en tu poder <wait=20>y seguir avanzando…","story.map5-open.005":"<size=22>¡Llegas tarde!","story.map5-open.006":"¡¿Por qué has tardado tanto?!","story.map5-open.007":"¡Llevo muchísimo, muchísimo tiempo esperándote, <rep_handlename>!","story.map5-open.008":"¿No crees que te has relajado demasiado desde que derrotaste a Maxwell?","story.map5-open.009":"<size=20>Jiji, <wait=20>¡¡te pillé!!","story.map5-open.010":"Estaba hablando con Lucius, <wait=40>yo también acabo de llegar. ","story.map5-open.011":"En fin, <wait=40>¡lo siguiente es el archipiélago de Palmyna!","story.map5-open.012":"Después de ver lo poderoso que eres de verdad en St. Lamia...","story.map5-open.013":"...¡esta vez tengo muchas esperanzas puestas en ti!","story.map5-open.014":"¡Vamos a darlo todo！","story.map5-open.015":"*Toc* <wait=20>*Toc*","story.map5-open.016":"Disculpe la intromisión. ","story.map5-open.017":"Traigo nueva información del departamento de inteligencia.","story.map5-open.018":"Al parecer, la barrera que protegía el archipiélago de Palmyna se ha roto. ","story.map5-open.019":"...<wait=40>Sí, <wait=40>recibí el informe hace poco. ","story.map5-open.020":"Parece que cada vez son más ambiciosos. ","story.map5-open.021":"Iré a investigar de inmediato.","story.map5-open.022":"No, <wait=40>sigue con tus tareas actuales. ","story.map5-open.023":"No puedo permitir que mi valiosa subordinada se vea envuelta en lo que sea que esté tramando esa gente. ","story.map5-open.024":"M-<wait=20>Muchas gracias...<br>Bueno, <wait=20>debería volver a mi trabajo. ","story.map5-open.025":"Los Cuatro Dioses Caídos...","story.map5-open.026":"Dicen que tienen poder para destruir toda Grand Gaia. ","story.map5-open.027":"Me gustaría ver lo fuertes que son en realidad...","story.map6-dungeon1.001":"¡¡Qué calor, qué calor, qué calor!!","story.map6-dungeon1.002":"¡¿Por qué hace este calor achicharrante por aquí?!","story.map6-dungeon1.003":"¡No estaría mal una brisa fresquita de vez en cuando!","story.map6-dungeon1.004":"¡Mira cuánto estoy sudando!","story.map6-dungeon1.005":"Ya te lo dije una vez, <wait=40>¡pero odio los sitios calurosos!","story.map6-dungeon1.006":"¡Recuérdalo la próxima vez que elijas dónde quedar, <rep_handlename>!","story.map6-dungeon1.007":"Mmm, <wait=40>pero de todos modos, Lord Lucius cuenta de verdad contigo, <rep_handlename>...","story.map6-dungeon1.008":"Supongo que yo también tendré que esforzarme mucho más que antes...","story.map6-dungeon1.009":"¡¿Q-<wait=20>Qué es esa cara?!","story.map6-dungeon1.010":"¡¿C-<wait=40>Cómo que nunca parece que me esfuerce?!","story.map6-dungeon1.011":"Grr, <wait=40>qué malo eres.","story.map6-dungeon1.012":"¡Si no te atacan más a menudo es solo porque estoy a tu lado!","story.map6-dungeon1.013":"Nadie se atrevería a acercarse a mí, <wait=40>¡todos le tienen demasiado miedo a mi increíble poder!","story.map6-dungeon1.014":"Seguro que ahora mismo hay malos ahí fuera que te tienen en el punto de mira, <rep_handlename>.","story.map6-dungeon1.015":"Jeje, <wait=40>¡es broma!","story.map6-dungeon1.016":"¡Si alguien así anduviera cerca, no se me escaparía!","story.map6-dungeon1.017":"Al salir de este sitio tan caluroso encontrarás un lago...","story.map6-dungeon1.018":"Justo pasado el lago hay un castillo precioso, <wait=40>¡quedemos allí la próxima vez!","story.map6-dungeon1.019":"Intenta no meterte en líos hasta entonces.","story.map6-dungeon1.020":"¡Y si te ves en apuros, siempre puedes rezarle a tu preciosa diosa!","story.map6-dungeon2.001":"<size=18>*Clang*","story.map6-dungeon2.002":"<speed=10>Je, je, je...<wait=40> Nunca pensé que tendría que usar así mis poderes.","story.map6-dungeon2.003":"Parece que eres alguien peligroso de verdad.","story.map6-dungeon2.004":"Sea como sea, acabaré al instante con cualquiera que se interponga en mis planes.","story.map6-dungeon2.005":"Te borraré de este mundo antes de que te des cuenta.","story.map6-dungeon2.006":"¿De verdad crees que va a ser tan fácil?","story.map6-dungeon2.007":"¡¿?!","story.map6-dungeon2.008":"Aun siendo un dios, <wait=40>¿piensas fanfarronear así ante un simple Invocador?","story.map6-dungeon2.009":"Ahh...<wait=40> Veo que sabes quién soy.","story.map6-dungeon2.010":"Parece que me he topado con otro factor desconocido.","story.map6-dungeon2.011":"Sin embargo, da igual. <wait=40>Pase lo que pase ahora, el resultado será el mismo.","story.map6-dungeon2.012":"Lo que he puesto en marcha acabará con toda la humanidad.","story.map6-dungeon2.013":"¡¿Qué?! <wait=40>¿Quieres decir que ya has activado la fortaleza celeste?","story.map6-dungeon2.014":"...<wait=40>¿Quién eres tú, exactamente?","story.map6-dungeon2.015":"Quizá debería encargarme de ti aquí y ahora...","story.map6-dungeon2.016":"Jo, jo, jo.<wait=40> ¿Quieres que te lo repita?","story.map6-dungeon2.017":"¿De verdad crees que va a ser tan fácil?","story.map6-dungeon2.018":"Este poder...<wait=40>...","story.map6-dungeon2.019":"Ya veo. <wait=40>Así que tú debes de ser... ","story.map6-dungeon2.020":"Invocador, <wait=40>has despertado mi interés.","story.map6-dungeon2.021":"Además, parece que tienes a más de un dios de tu parte. ","story.map6-dungeon2.022":"Vigilaré tus movimientos un poco más...","story.map6-dungeon2.023":"Jo, jo, jo.<wait=40> Parece que hemos salido del apuro.","story.map6-dungeon2.024":"Sin embargo, <wait=40>la situación sigue siendo grave. ","story.map6-dungeon2.025":"Ese era Zebra, <wait=20>sirviente de Cardes el Malévolo, <wait=40>uno de los Cuatro Dioses Caídos.","story.map6-dungeon2.026":"Parece que de algún modo ha logrado resucitar la legendaria fortaleza celeste del Imperio de Amdahl.","story.map6-dungeon2.027":"Algo así no hace ninguna falta en este mundo.","story.map6-dungeon2.028":"Sacar a la luz algo así solo traerá más guerras.","story.map6-dungeon2.029":"Piensas ir a Palmyna, ¿verdad?","story.map6-dungeon2.030":"Ya que vas tras Zebra, <wait=40>¿por qué no derribas también la fortaleza celeste?","story.map6-dungeon2.031":"Jo, jo, jo.","story.map6-dungeon2.032":"¿Qué ocurre?<wait=40> No tienes de qué preocuparte.","story.map6-dungeon2.033":"Tienes contigo a la jovencita, ¿no es así?","story.map6-dungeon2.034":"Mientras tengas la protección de la diosa, <wait=40>no te pasará nada.","story.map6-dungeon2.035":"¡Solo te pido que le hagas caso!","story.map6-dungeon2.036":"Hmm<wait=40>...","story.map6-dungeon2.037":"Aunque,<wait=40> en vuestro caso ya no está claro quién salva a quién.","story.map6-dungeon2.038":"Jo, jo, jo.","story.map6-dungeon2.039":"Debo irme ya.<wait=40> Dale recuerdos a la jovencita.","story.map6-dungeon3.001":"¡Eh, <wait=40><rep_handlename>!","story.map6-dungeon3.002":"Te estaba esperando.","story.map6-dungeon3.003":"¿Eh? <wait=40>¿Qué ha pasado?<wait=40> ¿A qué viene esa cara tan seria?","story.map6-dungeon3.004":"¡¿Qué has dicho?!<wait=40> ¡¿Zebra ha resucitado la fortaleza celeste?!","story.map6-dungeon3.005":"¿Cómo ha podido...?","story.map6-dungeon3.006":"Pero espera, <wait=40>¿qué es una fortaleza celeste? ¿Es importante?","story.map6-dungeon3.007":"¡¿Q-<wait=20>Qué es esa cara?! <wait=40>¡Hay cosas que ni las diosas saben!","story.map6-dungeon3.008":"Jo, jo, jo.","story.map6-dungeon3.009":"Es natural, para una diosa esas armas humanas son una nimiedad.","story.map6-dungeon3.010":"Ah, <wait=40>Elder Grah.","story.map6-dungeon3.011":"¿Eh? <wait=40>¿Esta vez no vas a intentar asustarme?","story.map6-dungeon3.012":"Oh, <wait=40>disculpa.","story.map6-dungeon3.013":"Parece que he defraudado las expectativas de la jovencita.","story.map6-dungeon3.014":"Bien, <wait=40>permíteme empezar de nuevo desde el principio.","story.map6-dungeon3.015":"¡No hace ninguna falta!","story.map6-dungeon3.016":"Jo, jo, jo.","story.map6-dungeon3.017":"Por cierto, <wait=40>tengo algo que contaros. ¿Os importaría escucharme?","story.map6-dungeon3.018":"Esta es la historia de la legendaria «Fortaleza Celeste» del Imperio de Amdahl.","story.map6-dungeon3.019":"Es de lo que hablaba <rep_handlename>, <wait=40>lo que Zebra ha resucitado, ¿no?","story.map6-dungeon3.020":"Sí, <wait=40>así es.","story.map6-dungeon3.021":"En el pasado, los humanos también intentaron resucitarla una vez.","story.map6-dungeon3.022":"Nadie sabe quién la construyó, cuándo, ni siquiera cómo...","story.map6-dungeon3.023":"Por lo visto, en el Imperio de Amdahl solo quedaron instrucciones de uso y una explicación de sus capacidades.","story.map6-dungeon3.024":"Durante mucho tiempo, la familia imperial la consideró intocable... ","story.map6-dungeon3.025":"...pero entonces un emperador decidió desafiar esa norma.","story.map6-dungeon3.026":"Sellada durante generaciones por el Imperio de Amdahl...","story.map6-dungeon3.027":"...el último emperador de Amdahl, Myzelion IV, rompió el sello...","story.map6-dungeon3.028":"...y usó el poder de la fortaleza celeste para atacar a las naciones vecinas e intentar someterlas. ","story.map6-dungeon3.029":"Mientras tanto, <wait=20>el rey de Palmyna se enteró de los planes del emperador.","story.map6-dungeon3.030":"Suplicó a Myzelion IV, pero este, testarudo, se negó a ceder. ","story.map6-dungeon3.031":"Al final, <wait=20>el rey de Palmyna usó su poderío para someter a Amdahl...","story.map6-dungeon3.032":"...y lo aplastó antes de que pudiera resucitar la fortaleza celeste. ","story.map6-dungeon3.033":"Esto, <wait=40>o sea, que...","story.map6-dungeon3.034":"¿La fortaleza celeste es tan peligrosa que vale la pena destruir una nación entera para impedir que resucite?","story.map6-dungeon3.035":"Sí, <wait=40>exactamente.","story.map6-dungeon3.036":"¡¿En serio?!<wait=40> ¡¿Y eso es lo que Zebra ha devuelto a la vida?!","story.map6-dungeon3.037":"Exacto.","story.map6-dungeon3.038":"¡¡Entonces estamos en un buen lío!!","story.map6-dungeon3.039":"Aun así, <wait=40>¡no tiene nada que ver con nuestro objetivo!","story.map6-dungeon3.040":"¡<rep_handlename>!<wait=40> ¡Sigamos tras Cardes!","story.map6-dungeon3.041":"Y tú, Elder Grah, <wait=40>¡ya puedes ir a cargarte la fortaleza celeste!","story.map6-dungeon3.042":"¡¿Eh?!<wait=40> Jovencita, eso sería imposible.","story.map6-dungeon3.043":"¿No deberías ser tú quien aceptara este reto?","story.map6-dungeon3.044":"Jooo, <wait=40>pero me meteré en un lío si nos desviamos del camino...","story.map6-dungeon3.045":"¡No te preocupes!","story.map6-dungeon3.046":"La fortaleza celeste está de camino a Palmyna, <wait=40>¡solo tienes que seguir recto!","story.map6-dungeon3.047":"¿Te importaría encargarte de esto por mí?<wait=40> Considéralo el deseo de un anciano que se acerca al final de su vida.","story.map6-dungeon3.048":"¡Eh, <wait=40><rep_handlename>!","story.map6-dungeon3.049":"¿Me echarías una mano?","story.map6-dungeon3.050":"Vale, <wait=40>supongo que no me queda otra.","story.map6-dungeon3.051":"Si tanto insistes, podemos intentarlo...","story.map6-dungeon3.052":"...pero tú también nos ayudarás, ¿verdad, Elder Grah?","story.map6-dungeon3.053":"Jo, jo, jo,<wait=40> ¿seguro que quieres que os acompañe?","story.map6-dungeon3.054":"Jeje, <wait=40>¡pues claro!","story.map6-dungeon3.055":"Además, ¡la única que puede pedirle cosas a <rep_handlename> soy yo!","story.map6-dungeon3.056":"Ahh, <wait=40>ya veo.","story.map6-dungeon3.057":"Jo, jo, jo. <wait=40>Disculpa si te he faltado al respeto.","story.map6-dungeon3.058":"Haré lo que pueda, siendo el anciano que soy.","story.map6-dungeon3.059":"¡Adiós, <rep_handlename>!<wait=40> ¡Te espero en la fortaleza celeste!","story.map6-dungeon3.060":"Mmm, <wait=40>creo que Elder Grah es mucho más fuerte de lo que aparenta. <wait=20>¿Tú qué crees?","story.map6-dungeon3.061":"Bah, <wait=40>¡de todos modos no tiene nada que ver con nosotros!","story.map6-dungeon3.062":"¡Muy bien!<wait=40> ¡Vamos hacia la fortaleza celeste!","story.map6-dungeon4.001":"......<wait=40>Tus métodos son tan retorcidos como siempre.","story.map6-dungeon4.002":"Este es el territorio de Cardes.<wait=40> Me moveré como me plazca.","story.map6-dungeon4.003":"Je, <wait=40>me parece bien. <wait=40>Me gustaría ver de qué eres capaz de verdad, Zebra.","story.map6-dungeon4.004":"Qué mala suerte tienen ese Invocador y su séquito...","story.map6-dungeon4.005":"Poco saben que el dios al que persiguen sepultó una vez a decenas de miles de humanos.","story.map6-dungeon4.006":"...<wait=40>...<wait=40>Esta presencia.","story.map6-dungeon4.007":"Parece que han llegado.","story.map6-dungeon4.008":"Hmm...","story.map6-dungeon4.009":"Parece que tú también tienes mala suerte.","story.map6-dungeon4.010":"Defenderé tu honor<wait=40> y me aseguraré de que se marchen de aquí.","story.map6-dungeon4.011":"¡Vamos, <rep_handlename>!<wait=40> ¡Date prisa!","story.map6-dungeon4.012":"¿Eh? <wait=40>¿Adónde se ha ido?","story.map6-dungeon4.013":"No hay duda de que esa presencia siniestra venía de esta zona...","story.map6-dungeon4.014":"¡<rep_handlename>!<wait=40> Todo es culpa tuya por venir arrastrando los pies todo el camino.","story.map6-dungeon4.015":"En fin, ¿no notas algo raro aquí?<wait=40> Ya no percibo a nadie...","story.map6-dungeon4.016":"Estoy segura de que antes noté la presencia de un dios...","story.map6-dungeon4.017":"¿Habrán sido imaginaciones mías?","story.map6-dungeon4.018":"Mmm, <wait=40>bueno, ¡en cualquier caso deberíamos ir hacia la fortaleza celeste!","story.map6-dungeon4.019":"¡Vamos al Barranco de Gadillian!","story.map6-dungeon5.001":"<size=18>¡Eh!<wait=40> ¡<rep_handlename>!","story.map6-dungeon5.002":"Uf, uf, uf.<wait=40> Por fin te encuentro...","story.map6-dungeon5.003":"¡Seria!<wait=40> ¡Aquí!","story.map6-dungeon5.004":"Uf, uf, uf, uf.<wait=40> Quién iba a pensar que llegarías hasta aquí...","story.map6-dungeon5.005":"¡Idiota!<wait=40> ¡La próxima vez ponte en algún sitio más fácil de encontrar!","story.map6-dungeon5.006":"Eso es imposible, ¿no...?","story.map6-dungeon5.007":"Uf. <wait=40>Pero, sinceramente, te hemos buscado por todas partes.","story.map6-dungeon5.008":"Pensábamos que seguirías por los alrededores del Castillo Avenia...","story.map6-dungeon5.009":"...pero parece que tú también has llegado a Encervis.","story.map6-dungeon5.010":"Eres un estorbo.","story.map6-dungeon5.011":"¿Por qué tienen que buscar los Cazademonios a un idiota como tú?","story.map6-dungeon5.012":"Los del Salón de Invocadores deberían ocuparse de los asuntos del Salón de Invocadores.","story.map6-dungeon5.013":"¿Pedirnos de repente que apoyemos a <rep_handlename>? ¿En qué estarán pensando?","story.map6-dungeon5.014":"Basta ya.","story.map6-dungeon5.015":"No podemos hacer nada con la situación en la que estamos.","story.map6-dungeon5.016":"Detener la fortaleza celeste es más urgente que encargarnos de Graham. <wait=20>Hasta tú lo sabes, ¿verdad, Seria?","story.map6-dungeon5.017":"¡Que sí, que sí!","story.map6-dungeon5.018":"¡Lo que odio es que <rep_handlename> participe en este plan!","story.map6-dungeon5.019":"Jaja, <wait=40>eso es muy de ti, Seria.","story.map6-dungeon5.020":"Pero lo repito, <wait=40>hemos venido a detener a Zebra. ","story.map6-dungeon5.021":"No podemos dejar que use la fortaleza celeste para atacar Elgaia.","story.map6-dungeon5.022":"Sé que hasta ahora ha sido una lucha dura, <wait=40>¡pero a partir de aquí tendremos que esforzarnos un poco más!","story.map6-dungeon5.023":"...¿Qué pasa?","story.map6-dungeon5.024":"¿Eh? <wait=40>¿Dices que no te han informado? <wait=50>¿Lo dices en serio?","story.map6-dungeon5.025":"*Suspiro* <wait=40>Qué vergüenza...","story.map6-dungeon5.026":"¡Debo de parecer tonta, animándome yo sola!","story.map6-dungeon5.027":"¡Parece que alguien del Salón de Invocadores la ha fastidiado bien!","story.map6-dungeon5.028":"Qué lamentable. <wait=40>Se supone que estamos en estado de alerta máxima.","story.map6-dungeon5.029":"Supuse que habrías recibido la misma información que nosotros...","story.map6-dungeon5.030":"¿Quizá le dieron información equivocada?","story.map6-dungeon5.031":"Eso no es nada propio del Salón de Invocadores.","story.map6-dungeon5.032":"Seguramente tengas razón...","story.map6-dungeon5.033":"En fin, <wait=40>parece que tendré que contártelo yo misma.","story.map6-dungeon5.034":"Persigues a Zebra, el que resucitó la fortaleza celeste, <wait=40>¿me equivoco?","story.map6-dungeon5.035":"Bien, <wait=40>al menos eso lo sabes.","story.map6-dungeon5.036":"En cuanto a la fortaleza celeste, <wait=40>es algo realmente maligno. ","story.map6-dungeon5.037":"Si llegara a estar plenamente operativa...","story.map6-dungeon5.038":"...<wait=40>Zebra podría usarla para cruzar la Puerta de Lucius y atacar Elgaia.","story.map6-dungeon5.039":"Por eso, hasta los altos cargos del Salón de Invocadores han reconocido que estamos en estado de emergencia...","story.map6-dungeon5.040":"Y han pedido ayuda a todos los Invocadores que estén cerca de la fortaleza celeste...","story.map6-dungeon5.041":"Eso te incluye a ti, <rep_handlename>.","story.map6-dungeon5.042":"Aunque los Cazademonios podríamos encargarnos de todo esto solos...","story.map6-dungeon5.043":"...desde que venciste a Maxwell, Karl insiste en que yo también reconozca tus habilidades...","story.map6-dungeon5.044":"Esta vez vamos a ayudarte, <wait=40>¡así que más te vale estar agradecido!","story.map6-dungeon5.045":"Ja, ja, ja.","story.map6-dungeon5.046":"Dicho esto, <wait=40>solo necesitamos que sigas tras la fortaleza celeste como hasta ahora. ","story.map6-dungeon5.047":"Te ayudaremos a avanzar encargándonos de cualquier obstáculo que surja. ","story.map6-dungeon5.048":"Sinceramente, <wait=40>aquí nos toca la peor parte.","story.map6-dungeon5.049":"¡Más te vale devolvernos el favor después!","story.map6-dungeon5.050":"Según la información del Salón de Invocadores de Akras...","story.map6-dungeon5.051":"...parece que podremos llegar a la fortaleza celeste en cuanto crucemos la Tierra de los Muertos, justo delante. ","story.map6-dungeon5.052":"Te despejaremos el camino.","story.map6-dungeon5.053":"¡Tú sigue adelante sin perder de vista la fortaleza celeste!","story.map6-dungeon5.054":"¡Manos a la obra, Seria!","story.map6-dungeon5.055":"¡Eh, <wait=40>Karl, <wait=20>espérame!","story.map6-dungeon5.056":"¡<rep_handlename>!","story.map6-dungeon5.057":"¡Asegúrate de que esa diosa también ayude! <wait=40>¿Entendido?","story.map6-dungeon5.058":"En serio, <wait=40>¿por qué me preocupo siquiera por un mocoso como tú...?","story.map6-dungeon6.001":"¡Ah! <wait=40>¡Ahí estás!","story.map6-dungeon6.002":"¡<rep_handlename>!<wait=40> ¡Aquí!","story.map6-dungeon6.003":"Este sitio me pone los pelos de punta...","story.map6-dungeon6.004":"¿Por qué dan tanto miedo los lugares que gobiernan los Cuatro Dioses Caídos...?","story.map6-dungeon6.005":"¡Tienes que traer la luz a estas zonas, <rep_handlename>!","story.map6-dungeon6.006":"Ah, <wait=40>¡hoy tengo información especial para ti!","story.map6-dungeon6.007":"Te voy a contar cómo vamos a llegar a la fortaleza celeste. ","story.map6-dungeon6.008":"¡Escucha con atención lo que te explica tu preciosa diosa!","story.map6-dungeon6.009":"Para empezar, <wait=40>el nombre oficial de la fortaleza celeste es Solaris. ","story.map6-dungeon6.010":"No he podido averiguar cuánto tiempo lleva por la zona...","story.map6-dungeon6.011":"...pero parece que flota en el cielo justo pasada la Tierra de los Muertos.","story.map6-dungeon6.012":"Jaja, <wait=40>sabía que te sorprenderías. ","story.map6-dungeon6.013":"Seguro que te estás preguntando: «¿Cómo vamos a subir al cielo?», ¿a que sí?","story.map6-dungeon6.014":"¡Déjaselo a la diosa!","story.map6-dungeon6.015":"Cuando pases de aquí y llegues hasta la fortaleza celeste...","story.map6-dungeon6.016":"¡Te mandaré arriba con mis poderes especiales!","story.map6-dungeon6.017":"Jeje, <wait=40>¿qué harías sin mí?","story.map6-dungeon6.018":"¡Puedes darme las gracias todo lo que quieras!","story.map6-dungeon6.019":"¡Pero no te confíes!","story.map6-dungeon6.020":"Parece que más adelante hay una chica superterrorífica a la que le encantan las masacres...","story.map6-dungeon6.021":"Me adelanto a la fortaleza celeste, <rep_handlename>, <wait=40>¡así que no tardes!","story.map6-dungeon6.022":"¡Y-<wait=40>Y no pienses que me adelanto porque tengo miedo! ¡¿Entendido?!","story.map6-dungeon7.001":"¡Lo hemos conseguido!","story.map6-dungeon7.002":"¡Parece que te he dejado justo en medio de la fortaleza celeste!","story.map6-dungeon7.003":"Soy increíble, ¿a que sí?","story.map6-dungeon7.004":"Ay... <wait=40>¿Dónde estamos exactamente?","story.map6-dungeon7.005":"Estoy <wait=40>mareada...","story.map6-dungeon7.006":"¿No estábamos luchando contra demonios en la Tierra de los Muertos?","story.map6-dungeon7.007":"¡Ah! <wait=40>¡Karl!","story.map6-dungeon7.008":"¡Y tu amiguita Seria!","story.map6-dungeon7.009":"¡¿Cómo que «amiguita»?!","story.map6-dungeon7.010":"¡Pero si es <rep_handlename>!","story.map6-dungeon7.011":"Pero si estás aquí, <wait=40>eso significa que...","story.map6-dungeon7.012":"¡Estamos dentro de la fortaleza celeste!","story.map6-dungeon7.013":"...<wait=40>Eso parece.","story.map6-dungeon7.014":"<size=18>¡¿Pero tú eres tonta?!","story.map6-dungeon7.015":"¡¿Es todo culpa tuya que estemos aquí arriba, verdad?!","story.map6-dungeon7.016":"¿No ves que todos siguen luchando ahí abajo?","story.map6-dungeon7.017":"¡Deberías pararte a entender la situación antes de actuar, diosa!","story.map6-dungeon7.018":"¿D-<wait=40>De qué hablas? <wait=40>Yo no he hecho nada malo...","story.map6-dungeon7.019":"¡Hay que ser muy creída para decir algo así!","story.map6-dungeon7.020":"¿Podemos dejarlo estar? Tenemos problemas mucho más importantes, ¿no?","story.map6-dungeon7.021":"Además, ahora nos será más fácil apoyar a <rep_handlename>.","story.map6-dungeon7.022":"Y además, <wait=40>que nosotros dos faltemos no cambiará nada para los que siguen luchando abajo.","story.map6-dungeon7.023":"Seguramente tengas razón, pero...","story.map6-dungeon7.024":"En cualquier caso, <wait=40>sigues siendo una diosa tan increíble como siempre.","story.map6-dungeon7.025":"Nos has facilitado un poco las cosas pese a la peligrosa situación en la que estamos. ","story.map6-dungeon7.026":"Si alguien podía proponérselo y conseguirlo, <wait=40>sabía que tenías que ser tú.","story.map6-dungeon7.027":"¡Te equivocas, Karl!<wait=40> ¡Eres demasiado confiado!","story.map6-dungeon7.028":"Jaja...","story.map6-dungeon7.029":"<size=18>¡¿?!<wait=40> ¡¿Quién anda ahí?!","story.map6-dungeon7.030":"<speed=10>Ah...","story.map6-dungeon7.031":"<speed=10>Parece que hasta vosotros, humanos, podéis percibir mi presencia.","story.map6-dungeon7.032":"¡¡Zebra!!","story.map6-dungeon7.033":"Es Zebra, el dios loco... <wait=40>Cuidado, es tan peligroso como parece...","story.map6-dungeon7.034":"¡Vas a pagar por lo que hiciste en Edila!","story.map6-dungeon7.035":"¡Prepárate!","story.map6-dungeon7.036":"No me servís de nada, patéticos gusanos.","story.map6-dungeon7.037":"A quien busco <wait=40>es a Tilith, la discípula de Lucius.","story.map6-dungeon7.038":"<size=18>¡Ahí estás!","story.map6-dungeon7.039":"<size=18>*Pum*","story.map6-dungeon7.040":"¡¡Kyaaah!!","story.map6-dungeon7.041":"Pareces agotada.<wait=40> Es de esperar, después de usar tanto poder para traerlos hasta aquí.","story.map6-dungeon7.042":"Te has esforzado muchísimo por estos patéticos gusanos.","story.map6-dungeon7.043":"Si lo que quieres es una batalla con los dioses, seguro que Lucius te detendría...","story.map6-dungeon7.044":"...pero si piensas atacarnos ahora, ¡no tendré piedad contigo!","story.map6-dungeon7.045":"<size=18>¡Atrás todos!","story.map6-dungeon7.046":"Qué poder es este...<wait=40> Ugh...<wait=40>No me puedo mover...","story.map6-dungeon7.047":"Gyah...<wait=40> ¿Cómo puedes tener aún tanto poder después de todo eso...?<wait=40> ¿Acaso...?","story.map6-dungeon7.048":"Uf... uf... ","story.map6-dungeon7.049":"Puede que ahora esté algo débil...<wait=40> pero no pienso perder contra ti...","story.map6-dungeon7.050":"<size=18>¡No creas que puedes jugar conmigo! <wait=40>¡¡No eres más que el perrito faldero de Lucius!!","story.map6-dungeon7.051":"<size=18>¡¡Kyaaaah!!","story.map6-dungeon7.052":"<size=20>¡¡Tilith!!","story.map6-dungeon7.053":"Ngh... <wait=40>Ha opuesto más resistencia de la que esperaba...","story.map6-dungeon7.054":"Aunque ya da igual. <wait=40>He eliminado lo que se interponía en mi camino. ","story.map6-dungeon7.055":"No queda ningún dios para defenderos.","story.map6-dungeon7.056":"Seréis un buen entrenamiento para mis subordinados. ","story.map6-dungeon7.057":"¿Crees que vamos a dejarte escapar?","story.map6-dungeon7.058":"Vuestras intenciones me traen sin cuidado.","story.map6-dungeon7.059":"Patéticos gusanos, sois incapaces de dar un solo paso en mi presencia.","story.map6-dungeon7.060":"Uso esta fortaleza celeste con el único fin de liberar a Lord Cardes de sus ataduras.","story.map6-dungeon7.061":"Si de verdad estáis decididos a enfrentaros a mí, <wait=40>me encontraréis esperando en lo más profundo. ","story.map6-dungeon7.062":"¡Os inculcaré a todos el temor a los dioses!","story.map6-dungeon7.063":"<size=18>¡¡Alto ahí!!","story.map6-dungeon7.064":"¡Maldición! <wait=40>¡Se ha escapado!","story.map6-dungeon7.065":"<size=18>¡¡Karl!!","story.map6-dungeon7.066":"<size=18>¡¿Pero qué?!<wait=40> ¡¿De dónde han salido todos estos monstruos?!","story.map6-dungeon7.067":"N-<wait=40>Ngh...","story.map6-dungeon7.068":"L-<wait=40>Lo siento...<wait=40> <rep_handlename>...","story.map6-dungeon7.069":"¡No hables!<wait=40> ¡Tienes que guardar fuerzas!","story.map6-dungeon7.070":"Karl, <wait=40>¡ya sabes lo que tenemos que hacer!","story.map6-dungeon7.071":"¡Sí! <wait=40>¡<rep_handlename>!","story.map6-dungeon7.072":"Tú ve tras Zebra. <wait=20>¡Seria y yo nos encargamos de esto!","story.map6-dungeon7.073":"No tengo ni idea de cómo piensa usar esta fortaleza...","story.map6-dungeon7.074":"...¡pero si logra liberar a Cardes, estaremos en un buen lío!","story.map6-dungeon7.075":"No te quedes ahí parado, <wait=40>¡muévete de una vez!","story.map6-dungeon7.076":"¿Crees que unos monstruos como estos suponen un reto para nosotros?","story.map6-dungeon7.077":"¡Cómo te atreves a dudar del líder de los Cazademonios!","story.map6-dungeon7.078":"Si tienes tiempo para preocupaciones inútiles, <wait=40>¡deja de perder el tiempo y ve tras él!","story.map6-dungeon7.079":"Además, <wait=40>tú mejor que nadie sabes que a esta diosa todavía le quedan ganas de pelea, ¿verdad?","story.map6-dungeon7.080":"Así es, Seria.","story.map6-dungeon7.081":"Estos monstruos no son ninguna amenaza para nosotros.","story.map6-dungeon7.082":"Y no temas por la diosa, ahora está bajo nuestra protección.","story.map6-dungeon7.083":"Así que ve ya <wait=40>y derrota a ese vil Zebra.","story.map6-dungeon7.084":"¡Contamos contigo, <rep_handlename>!","story.map6-dungeon7.085":"¡Demuéstranos qué clase de Invocador eres de verdad!","story.map6-dungeon7.086":"¡¡Seria!!","story.map6-dungeon7.087":"¡Sí!","story.map6-dungeon7.088":"<speed=20><size=20>¡¡Allá vamos!!","story.map6-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map6-dungeon_ex_clear.002":"¡Lo conseguiste, <rep_handlename>!","story.map6-dungeon_ex_clear.003":"Acabaste con la criatura incluso antes de que llegaran nuestros oficiales de logística.","story.map6-dungeon_ex_clear.004":"¡Sabía que podrías, señor!","story.map6-dungeon_ex_clear.005":"Ah, <wait=20>pero por lo visto van a ir de todos modos a esas ruinas.","story.map6-dungeon_ex_clear.006":"Parece que en origen estas ruinas albergaban algo enorme.","story.map6-dungeon_ex_clear.007":"Tiene aire de astillero o algo parecido, pero supongo que era la única opción.","story.map6-dungeon_ex_clear.008":"¿Mmm? <wait=40>¿Has notado algo desde que entraste, señor?","story.map6-dungeon_ex_clear.009":"Por cierto, parece que hay registros que indican que Valmodora también apareció durante la batalla con los dioses.","story.map6-dungeon_ex_clear.010":"Al parecer, ya entonces habitaba unas ruinas en alguna parte.","story.map6-dungeon_ex_clear.011":"Sin embargo, se suponía que un guerrero lo había exterminado.","story.map6-dungeon_ex_clear.012":"Seguro que tú también pasarás a la historia por lo que acabas de hacer.","story.map6-dungeon_ex_clear.013":"Aun así, <wait=20>¡intenta no ser tan temerario en el futuro!","story.map6-dungeon_ex_clear.014":"Pero de todas formas vas a ir digas lo que diga, ¿verdad?","story.map6-dungeon_ex_clear.015":"¡Que me preocupo mucho por ti, eh!","story.map6-dungeon_ex_clear.016":"......","story.map6-dungeon_ex_clear.017":"Jeje, <wait=20>hacía mucho que no te veía esa cara de apuro.","story.map6-dungeon_ex_clear.018":"En fin, ¡sigue investigando otras zonas, por favor!","story.map6-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map6-dungeon_ex_open.002":"¿Me oye, <wait=40>señor?","story.map6-dungeon_ex_open.003":"<size=20>¡<rep_handlename>!</size>","story.map6-dungeon_ex_open.004":"¿Me oyes?","story.map6-dungeon_ex_open.005":"Soy Lin Merylham, de Apoyo Logístico...","story.map6-dungeon_ex_open.006":"...de la Oficina de Investigación del Departamento de Exploración de Grand Gaia, a tu servicio.","story.map6-dungeon_ex_open.007":"Te contacto hoy con nueva información.","story.map6-dungeon_ex_open.008":"El Salón de Invocadores ha hecho un descubrimiento aterrador en las antiguas ruinas de Encervis.","story.map6-dungeon_ex_open.009":"Parece que una criatura increíblemente peligrosa se ha instalado en ellas.","story.map6-dungeon_ex_open.010":"Por ahora, <wait=20>todo parece tranquilo.","story.map6-dungeon_ex_open.011":"Sin embargo, parece que está absorbiendo fuerza de las ruinas que la rodean para ampliar su territorio.","story.map6-dungeon_ex_open.012":"Vamos a enviar de nuevo allí a nuestros oficiales de logística, así que hasta entonces, ¡mantente alejado, por favor!","story.map6-dungeon_ex_open.013":"......","story.map6-dungeon_ex_open.014":"¿Q-<wait=20>Qué dices, señor? <wait=40>¿Que ya estás allí?","story.map6-dungeon_ex_open.015":"Hmm, <wait=40>señor, ¡eres demasiado temerario!","story.map6-dungeon_ex_open.016":"Pero de todas formas vas a ir digas lo que diga, ¿verdad?","story.map6-dungeon_ex_open.017":"¡Entendido!","story.map6-dungeon_ex_open.018":"¡No intentaré detenerte!","story.map6-dungeon_ex_open.019":"El monstruo que te espera dentro se llama Valmodora.","story.map6-dungeon_ex_open.020":"Parece que es un monstruo bastante grande, así que ten muchísimo cuidado.","story.map6-dungeon_ex_open.021":"Siempre me preocupo tanto por ti, <wait=20>¿sabes...?","story.map6-ending.001":"<speed=10>I-<wait=40>Idiota...","story.map6-ending.002":"<speed=10>T-<wait=40>Típico humano...","story.map6-ending.003":"¡Gyah!<wait=40> <speed=10>Como discípulo...<wait=40> de Lord Cardes...","story.map6-ending.004":"<speed=10>N-<wait=40>No puedo ser..<wait=40> derrotado...<wait=40> tan fácilmente...","story.map6-ending.005":"<speed=10>Ngh...<wait=40> No me queda otra...","story.map6-ending.006":"<speed=10>¡¡Voy a derribar la fortaleza celeste, <wait=40>y os voy a llevar a todos conmigo!!","story.map6-ending.007":"<size=18>*Clang*","story.map6-ending.008":"<size=18>¡¡M-<wait=40>Malditoooos!!","story.map6-ending.009":"Hasta un dios debe saber cuándo rendirse.","story.map6-ending.010":"No saberlo te convierte en poco más que un demonio de segunda, diría yo.","story.map6-ending.011":"Deberías tomarte un tiempo para reflexionar sobre ello. ","story.map6-ending.012":"<size=18>¡¡Gwaaaahhh!!","story.map6-ending.013":"¡¿Mmm?!","story.map6-ending.014":"¿A qué viene esa cara de sorpresa?","story.map6-ending.015":"No importa, <wait=40>date prisa y llama a la jovencita.","story.map6-ending.016":"Sin Zebra, <wait=40>es probable que la fortaleza celeste vuelva a quedar sellada.","story.map6-ending.017":"¡¿Mmm?! <wait=40>Esta luz...","story.map6-ending.018":"<speed=10>¿Será que viene... <wait=40>del Lago Aldela?","story.map6-ending.019":"<size=18>¡¡<rep_handlename>!!","story.map6-ending.020":"Aaay...<wait=40> ¿Adónde hemos ido a parar esta vez?","story.map6-ending.021":"¡¡<rep_handlename>!!","story.map6-ending.022":"...<wait=40>...<wait=40>¡Lo conseguiste!","story.map6-ending.023":"¡Eres increíble, de verdad!","story.map6-ending.024":"Ngh, <wait=40>qué daño en el trasero...","story.map6-ending.025":"¡Oye, tú!<wait=40> ¡A ver si la próxima vez aterrizamos con más suavidad!","story.map6-ending.026":"Jo, jo, jo.","story.map6-ending.027":"Con un trasero tan grande como el tuyo no debería ser ningún problema, ¿no crees, Seria?","story.map6-ending.028":"G-<wait=40>Grahde...<wait=40> ¡Elder Grah!<wait=40> ¡¿Qué haces tú aquí?!","story.map6-ending.029":"¿Elder Grah?<wait=40> ¿Qué nombre es ese?","story.map6-ending.030":"Un momento, <wait=40>¿no eres Grahdens?","story.map6-ending.031":"¿Qué hace un Invocador Anciano como tú en un sitio como este?","story.map6-ending.032":"¡Cómo te atreves, <wait=40>insensato!","story.map6-ending.033":"Y pensar <wait=40>que por fin había conseguido que Tilith me viera como un simple anciano bondadoso...","story.map6-ending.034":"¡Y ahora apareces tú y lo estropeas todo!","story.map6-ending.035":"¿Eh?<wait=40> ¿Cómo que «anciano bondadoso»?","story.map6-ending.036":"Como uno de los jefes del Salón de Invocadores,<wait=40> ¡¿no deberías estar trabajando allí?!","story.map6-ending.037":"Mmm, <wait=40>no entiendo muy bien qué pasa, <wait=40>pero parece que Elder Grah era alguien muy importante desde el principio.","story.map6-ending.038":"No es solo el viejo raro que creíamos conocer...","story.map6-ending.039":"Oye, <wait=40>ahora que sabes quién es Lord Grahdens, ¡deberías tratarlo con un poco más de respeto!","story.map6-ending.040":"Pero a mí eso no me afecta...","story.map6-ending.041":"Y además, no sé cómo veis las cosas aquí, en el mundo humano...","story.map6-ending.042":"...pero puestos a elegir, como diosa, ¿no dirías que soy más importante yo?","story.map6-ending.043":"¡Deberías tratarme a mí con más respeto, Seria!","story.map6-ending.044":"Si eso piensas, ¿por qué no intentas comportarte más como una diosa?","story.map6-ending.045":"¡¿Qué insinúas?!","story.map6-ending.046":"Calmaos, <wait=40>¿de verdad pensáis pelearos pese a la victoria de <rep_handlename> sobre Zebra?","story.map6-ending.047":"Jo, jo, jo.","story.map6-ending.048":"Seria, <wait=40>es tal como dice Tilith.","story.map6-ending.049":"Comparado con los dioses, <wait=40>mi existencia es bastante insignificante. ","story.map6-ending.050":"Tilith, <wait=40>me gustaría que siguieras llamándome simplemente Elder Grah.","story.map6-ending.051":"Pensaba hacerlo de todos modos.","story.map6-ending.052":"Ya sé quién eres de verdad, Elder Grah.<wait=40> ¡No eres como otra rarita que yo me sé!","story.map6-ending.053":"¡¿De quién estás hablando?!","story.map6-ending.054":"Mmm, ¿de quién será...?","story.map6-ending.055":"En serio, <wait=40>¿algún día cambiaréis vosotras dos?","story.map6-ending.056":"En fin, <wait=40>Grahdens...","story.map6-ending.057":"Volviendo a lo que quería saber antes, <wait=40>¿por qué estás aquí?","story.map6-ending.058":"Karl...","story.map6-ending.059":"Tú también eres Invocador, <wait=40>¿por qué no me muestras un poco más de respeto?","story.map6-ending.060":"Déjate de rodeos. <wait=40>No voy a dejar que vuelvas a cambiar de tema.","story.map6-ending.061":"Te conozco desde hace mucho y estoy acostumbrado a tus mañas.","story.map6-ending.062":"Jo, jo, jo.<wait=40> Brutalmente sincero como siempre, ya veo.","story.map6-ending.063":"Karl, <wait=40>permíteme explicarte los detalles más tarde.","story.map6-ending.064":"Antes tengo que hablar de algo con <rep_handlename>.","story.map6-ending.065":"<rep_handlename>, <wait=40>por derrotar a Zebra tal como te pedí...","story.map6-ending.066":"te expreso mi gratitud como Invocador Anciano del Departamento de Defensa del Salón de Invocadores de Akras.","story.map6-ending.067":"Jeje, <wait=40>¿esperabas menos de un buen amigo mío?","story.map6-ending.068":"¡Sabía que podías hacerlo, mi <rep_handlename>!","story.map6-ending.069":"Eh, <wait=20>¡deja de decir que es tuyo!","story.map6-ending.070":"E-<wait=40>En fin, ya que <rep_handlename> ha cumplido la petición de Lord Grahdens...","story.map6-ending.071":"supongo que puedo justificar elogiarte como compañero Invocador.","story.map6-ending.072":"¡Qué sincera eres!","story.map6-ending.073":"¡¿Q-<wait=40>Qué estás diciendo?!","story.map6-ending.074":"Jo, jo, jo.<wait=40> Parece que todos te están muy agradecidos por lo que has hecho.","story.map6-ending.075":"Sin embargo, <wait=40>por fuerte que fuera, <wait=40>no olvides que Zebra era un mero discípulo de Cardes.","story.map6-ending.076":"El poder de Zebra no es nada comparado con el del dios caído que persigues ahora. ","story.map6-ending.077":"Sin duda, <wait=40>en Palmyna te esperan batallas de una ferocidad sin igual.","story.map6-ending.078":"Ahora, más que nunca, <wait=40>debes avanzar con cautela.","story.map6-ending.079":"No te preocupes por él. <wait=40>Está bajo mi protección.","story.map6-ending.080":"¿Cómo que «mi protección»? <wait=40>Hace un momento estabas al borde de la muerte, ¿no te acuerdas?","story.map6-ending.081":"¡Seria!","story.map6-ending.082":"¡¿Q-<wait=40>Qué?!","story.map6-ending.083":"Gracias...<wait=40> por protegerme antes.","story.map6-ending.084":"¿Q-<wait=20>Q-<wait=10>Qué te p-<wait=10>pasa de repente?","story.map6-ending.085":"N-<wait=40>No es que buscara que me lo agradecieras ni nada...","story.map6-ending.086":"S-<wait=40>Solo estaba... <wait=20>*Murmullo* <size=14>*Murmullo* <size=12>*Murmullo*","story.map6-ending.087":"Jaja, <wait=40>qué tímida estás, ¿eh?","story.map6-ending.088":"Jo, jo, jo.","story.map6-ending.089":"¡<rep_handlename>!","story.map6-ending.090":"¡Por fin vamos a Palmyna, la tierra donde está sellado Cardes!","story.map6-ending.091":"Creo en ti...","story.map6-ending.092":"<rep_handlename>, <wait=40>¡tú eres el Invocador que va a salvar el mundo!","story.map6-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Tú, <rep_handlename>,<wait=39> que has abierto Amdahl...","story.map6-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Usa mi poder al comenzar tu viaje por esta nueva tierra...","story.map6-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Para traer una nueva esperanza a este mundo tan impregnado de tristeza…","story.map6-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Debes tener fe en tu poder <wait=20>y seguir avanzando…","story.map6-open.005":"¡Ah, <wait=40>ya te has despertado!","story.map6-open.006":"¡Mira! <wait=40>Estamos en Encervis.","story.map6-open.007":"Con sus aguas profundas y sus altos volcanes, <wait=40>este lugar es famoso por sus entornos extremos.","story.map6-open.008":"Hace mucho tiempo, <wait=40>aquí tuvo lugar una batalla entre humanos...","story.map6-open.009":"...<wait=40>...","story.map6-open.010":"¡Pero no es muy interesante, así que olvidémoslo!","story.map6-open.011":"Además, <wait=40>¡hay muchas otras cosas que vas a tener que aprender!","story.map6-open.012":"Y de todos modos, no tiene mucho que ver con nosotros.","story.map6-open.013":"Aquí, en medio del archipiélago de Palmyna, aún estamos bastante lejos de Palmyna en sí...","story.map6-open.014":"¡Pero no te confíes <wait=20>y mantén siempre la concentración!","story.map6-open.015":"¡Aquí también espero grandes cosas de ti!","story.map6-open.016":"Muy bien, <wait=20>¡demos lo mejor de nosotros y esforcémonos por derrotar a Cardes!!","story.map7-dungeon1.001":"¡<rep_handlename>!","story.map7-dungeon1.002":"¡Tenemos problemas!<wait=40> ¡¡Problemas gordos!!","story.map7-dungeon1.003":"¡Kyaah!","story.map7-dungeon1.004":"<size=18>*Pum*","story.map7-dungeon1.005":"Aaayyy...","story.map7-dungeon1.006":"¡Oye!<wait=40> ¡<rep_handlename>! <wait=40>¡No te quedes ahí parado!","story.map7-dungeon1.007":"¿Eh? <wait=40>¿Creías que te iba a esperar en el Castillo de Obselion?","story.map7-dungeon1.008":"¡No hay tiempo para preocuparse por esos detallitos!","story.map7-dungeon1.009":"¡Tenemos problemas gordísimos!","story.map7-dungeon1.010":"¡¡El sello que encierra a Cardes ha empezado a deshacerse!!","story.map7-dungeon1.011":"No sé por qué ha empezado a deshacerse de repente...","story.map7-dungeon1.012":"...¡pero está claro que se prepara para escapar!","story.map7-dungeon1.013":"Aunque no creo que nadie de fuera haya tenido nada que ver.","story.map7-dungeon1.014":"¡Jo!","story.map7-dungeon1.015":"Después de cómo te encargaste de Zebra, creía que acabar con él sería pan comido.","story.map7-dungeon1.016":"Hmpf, <wait=40>parece que vuelve a haber mucho jaleo...","story.map7-dungeon1.017":"Aún tengo un montón de cosas que hacer para Lord Lucius...","story.map7-dungeon1.018":"Y ahora encima tengo que ocuparme de lo que esté tramando Cardes...","story.map7-dungeon1.019":"¡¿Por qué nunca me puedo tomar un respiro?!","story.map7-dungeon1.020":"¡Ah, <wait=40>casi se me olvida!","story.map7-dungeon1.021":"¡Aún no he encontrado la forma de llegar al Mundo Espiritual!","story.map7-dungeon1.022":"Pero te prometo que lo habré averiguado para cuando llegues al Castillo de Obselion, <rep_handlename>.","story.map7-dungeon1.023":"¡Suerte, <wait=40>y esta vez sí que nos vemos en el Castillo de Obselion!","story.map7-dungeon2.001":"Jo, jo, jo. <wait=40>¿Pero si es <rep_handlename>?","story.map7-dungeon2.002":"Vas camino de la tierra donde está sellado Cardes, ¿verdad?","story.map7-dungeon2.003":"¿Hmm? <wait=40>¿Qué ocurre?<wait=40> Te veo inquieto.","story.map7-dungeon2.004":"Si buscas a Tilith, no la he visto por aquí. ","story.map7-dungeon2.005":"¿A qué viene esa cara de preocupación? <wait=40>No tienes por qué preocuparte por ella, ¿sabes?","story.map7-dungeon2.006":"Está fuera del alcance de las preocupaciones de simples Invocadores como nosotros. ","story.map7-dungeon2.007":"Aunque esa forma tan adorable que tiene de mirarte también me pondría nervioso a mí. ","story.map7-dungeon2.008":"Jo, jo, jo.","story.map7-dungeon2.009":"Hmm. <wait=40>Parece que hace tiempo que no estábamos los dos a solas. ","story.map7-dungeon2.010":"Ya que tenemos un rato, <wait=40>¿por qué no te cuento una pequeña historia?","story.map7-dungeon2.011":"Una historia sobre una cruenta batalla entre los humanos y los dioses.","story.map7-dungeon2.012":"Hace mucho tiempo, <wait=40>el Castillo de Obselion era el hogar de la Familia Real de Palmyna. ","story.map7-dungeon2.013":"En origen era un castillo pintoresco, <wait=40>rodeado de vegetación. ","story.map7-dungeon2.014":"Sin embargo, esto es lo que quedó de él tras la batalla contra los dioses. ","story.map7-dungeon2.015":"¿Conoces a los Cuatro Héroes de Palmyna?","story.map7-dungeon2.016":"Cuenta la leyenda que cuatro guerreros lucharon contra Cardes para salvar esta tierra.","story.map7-dungeon2.017":"Incluso se dice que Edea, la Princesa de Palmyna, estaba entre ellos.","story.map7-dungeon2.018":"Si la leyenda es cierta, fueron estos Cuatro Héroes quienes sellaron a Cardes. ","story.map7-dungeon2.019":"Sin embargo, se dice que a cambio de poder sellar a Cardes...","story.map7-dungeon2.020":"...los Cuatro Héroes tuvieron que sacrificar sus propias vidas. ","story.map7-dungeon2.021":"Me pregunto qué pensarían al final. ","story.map7-dungeon2.022":"¿Fueron felices creyendo que sellar a Cardes salvaría Palmyna? ","story.map7-dungeon2.023":"¿Fue así como pudieron afrontar la muerte sin miedo?","story.map7-dungeon2.024":"Por muy valientes que fueran al arriesgar sus vidas por proteger este lugar...","story.map7-dungeon2.025":"...cuando empezaron a luchar, ya estaba perdido.","story.map7-dungeon2.026":"Una historia muy triste, sin duda...","story.map7-dungeon2.027":"<rep_handlename>, <wait=40>¿entiendes lo que intento decirte?","story.map7-dungeon2.028":"Jo, jo, jo. <wait=40>No te preocupes.","story.map7-dungeon2.029":"Seguro que <wait=40>algún día te verás en una situación igual de inimaginable. ","story.map7-dungeon2.030":"Hasta entonces, <wait=40>vigila con atención tu entorno mientras sigue cambiando. ","story.map7-dungeon2.031":"Lo que descubras te servirá de combustible en tu camino. ","story.map7-dungeon2.032":"Jo, jo, jo.<wait=40> Perdona el sermón tan largo. ","story.map7-dungeon2.033":"Cuando vuelvas a ver a Tilith, dale este mensaje de mi parte.","story.map7-dungeon2.034":"El sello de Cardes está a punto de romperse.","story.map7-dungeon2.035":"Hasta pronto, y cuídate.","story.map7-dungeon3.001":"<size=18>*Zas*","story.map7-dungeon3.002":"Uf. <wait=40>Parece que ya casi hemos acabado con los monstruos de esta zona. ","story.map7-dungeon3.003":"Aunque tengo que admitir <wait=40>que son mucho más fuertes de lo que esperaba.","story.map7-dungeon3.004":"¿Hmm?","story.map7-dungeon3.005":"¡Eh! <wait=40>¡<rep_handlename>!","story.map7-dungeon3.006":"¡Bienvenido a Palmyna!","story.map7-dungeon3.007":"No estamos muy lejos de donde está sellado Cardes. <wait=40>¡Demos todo lo que tenemos en este último empujón!","story.map7-dungeon3.008":"¡Eh! <wait=40>¡Seria!<wait=40> ¡<rep_handlename> también ha llegado!","story.map7-dungeon3.009":"No hace falta que me avises cada vez. <wait=40>Además, estaba ignorando a <rep_handlename>.","story.map7-dungeon3.010":"Ja, ja. <wait=40>Igual que siempre, ¿eh, Seria?","story.map7-dungeon3.011":"En fin, <wait=40>¿dónde está esa diosa que siempre te sigue a todas partes?","story.map7-dungeon3.012":"...Hmm, así que está buscando el camino al Mundo Espiritual.","story.map7-dungeon3.013":"Parece que no nos queda otra que ir allí si queremos enfrentarnos a Cardes...","story.map7-dungeon3.014":"¿Qué te pasa?<wait=40> Estás un poco pálida.","story.map7-dungeon3.015":"¡N-<wait=40>No es nada!","story.map7-dungeon3.016":"¡Solo estoy un poco molesta!","story.map7-dungeon3.017":"O sea, <wait=40>¡¿no ves lo que está pasando, Karl?!","story.map7-dungeon3.018":"¡Nuestro objetivo siempre ha sido acabar con Graham!","story.map7-dungeon3.019":"¡¿Por qué tenemos que perder el tiempo ayudando a <rep_handlename>?!","story.map7-dungeon3.020":"Vamos, <wait=40>derrotar a los Cuatro Dioses Caídos es más importante que Graham. ","story.map7-dungeon3.021":"¡Ya lo sé, ya lo sé!","story.map7-dungeon3.022":"Pero sabes cómo me siento, ¿verdad, Karl?","story.map7-dungeon3.023":"¡Más que nada en el mundo, quiero acabar con Graham!","story.map7-dungeon3.024":"Sí, <wait=40>entiendo cómo te sientes. <wait=50>Perdóname, <wait=40>Seria...","story.map7-dungeon3.025":"No quería echarte la culpa ni nada, Karl...","story.map7-dungeon3.026":"¡¡Grrr!!<wait=40> ¡Todo es culpa tuya!","story.map7-dungeon3.027":"¡¿Por qué no te enfrentas tú solo a Cardes?!","story.map7-dungeon3.028":"Un poco absurdo,<wait=40> ¿no crees?","story.map7-dungeon3.029":"¡He dicho que ya lo sé!","story.map7-dungeon3.030":"Karl, <wait=40>¡últimamente es imposible discutir contigo!","story.map7-dungeon3.031":"No, <wait=40>es que últimamente dices unas cosas absurdas...","story.map7-dungeon3.032":"¡No tengo ni idea de qué hablas!","story.map7-dungeon3.033":"¡<rep_handlename>! <wait=40>Date prisa, encuentra a esa diosa...","story.map7-dungeon3.034":"...¡y averigua cómo se supone que llegamos al Mundo Espiritual!","story.map7-dungeon3.035":"¡E-<wait=20>Eh!<wait=40> ¡Espérame!","story.map7-dungeon3.036":"¡<rep_handlename>! Nosotros despejaremos el camino.","story.map7-dungeon3.037":"¡Tú asegúrate de estar listo para enfrentarte a Cardes!","story.map7-dungeon4.001":"...<rep_handlename>.","story.map7-dungeon4.002":"Me alegro de verte... <wait=40>Parece que estás bien...","story.map7-dungeon4.003":"Uf...<wait=40> uf...","story.map7-dungeon4.004":"E-<wait=40>Estoy bien...","story.map7-dungeon4.005":"Ngh...<wait=40> Parece que la he fastidiado un poco...","story.map7-dungeon4.006":"Mientras intentaba averiguar cómo llegar al Mundo Espiritual <wait=40>surgió algo inesperado...","story.map7-dungeon4.007":"Siento haberte preocupado.","story.map7-dungeon4.008":"Estaré bien, <wait=20>solo necesito descansar un poco.","story.map7-dungeon4.009":"Pero lo más importante, <wait=40>tengo algo que contarte...","story.map7-dungeon4.010":"<rep_handlename>...","story.map7-dungeon4.011":"El sello de Cardes...<wait=40> no solo se estaba agrietando...","story.map7-dungeon4.012":"Cardes... <wait=40>lo está destruyendo... <wait=40>desde dentro...","story.map7-dungeon4.013":"Ahora está debilitado por haber estado sellado tanto tiempo...","story.map7-dungeon4.014":"Pero sus poderes de dios siguen siendo tremendos...","story.map7-dungeon4.015":"Ya han empezado a desbordarse desde el Mundo Espiritual, <wait=40>destruyendo todo a su paso...","story.map7-dungeon4.016":"Intenté reparar el sello, pero fracasé...","story.map7-dungeon4.017":"Uf...<wait=40> uf...","story.map7-dungeon4.018":"P-<wait=40>Pero... <wait=40>aún tenemos una oportunidad.","story.map7-dungeon4.019":"El camino al Mundo Espiritual ya está abierto.","story.map7-dungeon4.020":"Ve al Campo de Batalla de Noera. <wait=40>La entrada al Mundo Espiritual está justo pasado ese lugar...","story.map7-dungeon4.021":"¡Adelántate, <wait=40>y no te preocupes por mí!","story.map7-dungeon4.022":"Y de paso pide ayuda a Karl, a Seria y a Elder Grah. ","story.map7-dungeon4.023":"Voy a descansar antes de reunirme contigo...","story.map7-dungeon4.024":"No te preocupes por mí...","story.map7-dungeon4.025":"¡Soy una diosa hermosa e invencible!","story.map7-dungeon4.026":"Es solo que <wait=40>ahora estoy un poco cansada...","story.map7-dungeon4.027":"Pero no te preocupes... <wait=50>Nos vemos en primera línea...","story.map7-dungeon5.001":"Pero si es <rep_handlename>.","story.map7-dungeon5.002":"¿A qué viene esa cara tan seria?","story.map7-dungeon5.003":"¡¿Qué has dicho?!<wait=40> ¡¿Qué le ha pasado a Tilith?!","story.map7-dungeon5.004":"Hmm. <wait=40>La situación parece más apremiante de lo que imaginaba. ","story.map7-dungeon5.005":"Lo siento, pero tengo algo de lo que ocuparme por aquí, <wait=40>así que no puedo ayudarte. ","story.map7-dungeon5.006":"Ya les he pedido a Karl y a Seria que te ayuden. ","story.map7-dungeon5.007":"Deberíais trabajar juntos para derrotar a Cardes.","story.map7-dungeon5.008":"......<wait=50><rep_handlename>.","story.map7-dungeon5.009":"Tengo algo que contarte antes de que te enfrentes al Dios Caído.","story.map7-dungeon5.010":"Uno de los Cuatro Héroes de Palmyna trabajaba aquí, en el Seminario de Arlind.","story.map7-dungeon5.011":"Se llamaba Lorand, y era profesor. ","story.map7-dungeon5.012":"Aunque ya se había retirado de la vida de soldado...","story.map7-dungeon5.013":"...Edea, la Princesa de Palmyna, <wait=40>lo convenció para luchar contra los dioses invasores. ","story.map7-dungeon5.014":"Terminó tal como te conté antes. ","story.map7-dungeon5.015":"Los Cuatro Héroes sacrificaron sus vidas para sellar a Cardes. ","story.map7-dungeon5.016":"Sin embargo, <wait=40>hay muchas otras historias de gente que luchó igual que los Cuatro Héroes. ","story.map7-dungeon5.017":"Hace mucho tiempo, <wait=40>muchos humanos lucharon aquí contra los dioses.","story.map7-dungeon5.018":"La mayoría acabaron perdiendo la vida.","story.map7-dungeon5.019":"Según la leyenda, <wait=40>Lucius permitió que algunos supervivientes escaparan a Elgaia. ","story.map7-dungeon5.020":"Todos los que se quedaron en Grand Gaia perecieron. ","story.map7-dungeon5.021":"<rep_handlename>.<wait=50> ¿Por qué crees que los dioses destruyeron a los humanos?","story.map7-dungeon5.022":"Hay incontables teorías, <wait=40>pero aún no se ha hallado una respuesta.","story.map7-dungeon5.023":"Aunque, pasado mucho tiempo, <wait=40>Lucius volvió a abrir el camino a Grand Gaia.","story.map7-dungeon5.024":"Para derrotar a los Cuatro Dioses Caídos, debe de necesitar también la fuerza de los humanos. ","story.map7-dungeon5.025":"Dicho esto, ¿por qué exactamente andan desatados los Cuatro Dioses Caídos?","story.map7-dungeon5.026":"¿Y por qué el Sagrado Emperador Karna Masta, señor de los dioses, no ha reaccionado ante esta situación?","story.map7-dungeon5.027":"Hay demasiadas cosas que los humanos sencillamente nunca entenderemos.","story.map7-dungeon5.028":"Aunque seguro que Tilith, como discípula de Lucius, lo entiende, ¿no crees?","story.map7-dungeon5.029":"¿Seguro que no lo sabe? <wait=40>Quizá solo intenta ocultarte cierta información.","story.map7-dungeon5.030":"O quizá <wait=40>simplemente no piensa en nada. ","story.map7-dungeon5.031":"Jo, jo, jo.","story.map7-dungeon5.032":"Tilith es una chica tan buena y tan guapa que espero que solo sea eso. ","story.map7-dungeon5.033":"En fin, <wait=40><rep_handlename>.","story.map7-dungeon5.034":"Perdona que me haya enrollado así, <wait=40>pero seguro que entiendes lo que intento transmitirte.","story.map7-dungeon5.035":"No te dejes arrastrar por todo lo que está pasando; <wait=40>actúa según tus propias ideas y voluntad. ","story.map7-dungeon5.036":"Tu papel en esto ya es más de lo que un solo Invocador debería poder soportar. ","story.map7-dungeon5.037":"Deberías ponerte en camino.","story.map7-dungeon5.038":"Pasado el Campo de Batalla de Noera, justo delante, está la entrada al Mundo Espiritual.","story.map7-dungeon5.039":"Y no lo olvides: <wait=20>Tilith y los dioses no son los únicos que cuentan contigo.","story.map7-dungeon6.001":"¡Hola, <rep_handlename>!<wait=40> Ya estás aquí.","story.map7-dungeon6.002":"¡Mira!<wait=40> La entrada al Mundo Espiritual está justo delante de nosotros.","story.map7-dungeon6.003":"Oye, <wait=40>esa diosa te dijo cómo se supone que entramos al Mundo Espiritual, ¿no?","story.map7-dungeon6.004":"¿Y dónde está? <wait=40>¡¿Cómo puede estar por ahí haciendo el tonto en un momento tan crítico?!","story.map7-dungeon6.005":"Eh......<wait=50> Ah, ya veo......","story.map7-dungeon6.006":"P-<wait=40>Pero no hay de qué preocuparse, ¿verdad?<wait=40> ¡¿Al fin y al cabo es una diosa, no?!","story.map7-dungeon6.007":"¡Seguro que tarde o temprano aparece con esa cara de engreída!","story.map7-dungeon6.008":"¡Así que quita esa cara de pena y haz tu trabajo!","story.map7-dungeon6.009":"¡Si hizo lo que hizo es porque creía que podías derrotar a Cardes!","story.map7-dungeon6.010":"¡Ahora tienes que darlo todo! <wait=40>¡No puedes dejar que todo lo que ha hecho se desperdicie!","story.map7-dungeon6.011":"Tiene razón.","story.map7-dungeon6.012":"Sé que estás preocupado, <rep_handlename>, <wait=40>pero antes que nada tenemos que derrotar a Cardes.","story.map7-dungeon6.013":"Si la entrada al Mundo Espiritual está de verdad abierta...","story.map7-dungeon6.014":"...entonces nada nos impide ayudarte a ti también.","story.map7-dungeon6.015":"¡Por la diosa, <wait=40>haremos todo lo posible por ayudar!","story.map7-dungeon6.016":"¡Y-<wait=40>Yo solo voy a cumplir las órdenes del Salón de Invocadores!","story.map7-dungeon6.017":"¡Lo que yo haga no tiene nada que ver con esa diosa tonta!","story.map7-dungeon6.018":"En fin, <wait=40>estaría bien que por una vez fuera ella la que nos debiera algo. ","story.map7-dungeon6.019":"Supongo que esta vez me esforzaré un poco más de lo normal.","story.map7-dungeon6.020":"Je, <wait=40>seguro que hasta ella se quedaría tranquila viéndote tan motivada, Seria.","story.map7-dungeon6.021":"¡¿Q-<wait=40>Qué estás diciendo?!","story.map7-dungeon6.022":"Solo digo que parece que podemos contar contigo, Seria. <wait=40>¿Verdad, <rep_handlename>?","story.map7-dungeon6.023":"¡No le sigas la corriente!","story.map7-dungeon6.024":"Muy bien, <wait=40>¡abrámonos paso hasta el Mundo Espiritual!","story.map7-dungeon6.025":"¡<rep_handlename>!<wait=40> ¡Seria!<wait=40> ¡Vamos!","story.map7-dungeon7.001":"Así que este es el Mundo Espiritual Palmyna...<wait=40> Da bastante mal rollo, la verdad.","story.map7-dungeon7.002":"Me alegra ver que es mucho más espacioso de lo que pensaba.","story.map7-dungeon7.003":"¿Eh?<wait=40> ¿Que sea más espacioso no hará más difícil encontrar a Cardes?","story.map7-dungeon7.004":"B-<wait=20>Bueno, o sea...<wait=40> No me refería a eso...","story.map7-dungeon7.005":"Solo pensaba que sería duro luchar contra Cardes en un espacio reducido. ","story.map7-dungeon7.006":"Sí, <wait=40>en eso tienes razón.","story.map7-dungeon7.007":"Con tanto espacio, <wait=40>nuestras opciones para enfrentarnos a Cardes son ilimitadas. ","story.map7-dungeon7.008":"Sí, <wait=40>eso parece.","story.map7-dungeon7.009":"<size=16>*Retumbo*","story.map7-dungeon7.010":"¡¿Q-<wait=20>Qué ha sido eso?!<wait=20> ¿Por qué tiembla todo?","story.map7-dungeon7.011":"¡Maldita sea! <wait=40>¡Parece que las cosas no son tan tranquilas como parecían!","story.map7-dungeon7.012":"Esperaba tener más tiempo para buscar a Cardes...","story.map7-dungeon7.013":"¡<rep_handlename>!<wait=40> ¡Seria!","story.map7-dungeon7.014":"¡Separémonos y busquemos a Cardes!","story.map7-dungeon7.015":"¡¿De verdad crees que es buena idea en un momento así?!","story.map7-dungeon7.016":"Se nos acaba el tiempo.","story.map7-dungeon7.017":"Si no derrotamos a Cardes antes de que se libere...","story.map7-dungeon7.018":"...es muy probable que desaparezcamos junto con el Mundo Espiritual.","story.map7-dungeon7.019":"......<wait=40>Entendido.","story.map7-dungeon7.020":"Si oís el choque de espadas, <wait=40>sin duda es allí donde ha empezado la lucha. ","story.map7-dungeon7.021":"¡Aguzad el oído y vigilad bien vuestro entorno!","story.map7-dungeon7.022":"¡<rep_handlename>!","story.map7-dungeon7.023":"Todavía eres un novato, <wait=40>¡así que si ves a Cardes, más te vale quedarte quieto y esperarnos!","story.map7-dungeon7.024":"Tiene razón. <wait=40>¡Pase lo que pase, ninguno debe enfrentarse a él solo!","story.map7-dungeon7.025":"¡Quiero que todos sobrevivamos y volvamos juntos a Elgaia!","story.map7-ending.001":"Uf...<wait=40> uf...<wait=40> ¡Hemos llegado tarde!","story.map7-ending.002":"<size=20>*Retumbo*","story.map7-ending.003":"<anchor=center><speed=10>Seria...<wait=40> Toma mi mano......","story.map7-ending.004":"¡Hola a todos! <wait=40>¡¡Siento llegar tarde!!","story.map7-ending.005":"¡<rep_handlename>! <wait=40>¡Sabía que podías conseguirlo!","story.map7-ending.006":"¡T-<wait=20>Tú! <wait=40>¡¿Qué haces aquí?!","story.map7-ending.007":"Creía que estabas malherida...","story.map7-ending.008":"Presentí que <rep_handlename> estaba en apuros, <wait=40>así que dejé mi recuperación para luego y vine a ayudar.","story.map7-ending.009":"Aunque todavía me duele un poquito.","story.map7-ending.010":"¡Qué insensatez hacer algo así por una corazonada!","story.map7-ending.011":"Me alegro de haber llegado a tiempo para ayudarte a ti también, <wait=40>Seria.","story.map7-ending.012":"......","story.map7-ending.013":"G-<wait=40>Gracias por eso...","story.map7-ending.014":"¡No hay de qué! <wait=40>¡Me alegra que estéis todos a salvo!","story.map7-ending.015":"Sí, <wait=40>¡gracias por salvarnos!","story.map7-ending.016":"Habría sido una pena acabar en un sitio así, <wait=40> justo después de haber derrotado a Cardes. ","story.map7-ending.017":"Gracias, <wait=40>diosa.","story.map7-ending.018":"¡Ese es el Karl que recuerdo! <wait=40>¡Tú también puedes darme las gracias todo lo que quieras, Seria!","story.map7-ending.019":"¡N-<wait=40>No te pases!","story.map7-ending.020":"O sea, <wait=40>si eres una diosa, ¡¿por qué llegas siempre en el último momento?!","story.map7-ending.021":"¡¿Q-<wait=40>Qué te pasa?!","story.map7-ending.022":"Y otra cosa, ¡¿por qué no nos dijiste cómo salir del Mundo Espiritual?!","story.map7-ending.023":"E-<wait=40>Eh, <wait=20>se me debió de...","story.map7-ending.024":"Dejemos las cosas como están.","story.map7-ending.025":"Y aunque no lo parezca, Seria de verdad te agradece lo que hiciste por ella.","story.map7-ending.026":"Sí, <wait=40>ya lo sé.","story.map7-ending.027":"¡Se nota por cómo se sonroja!","story.map7-ending.028":"¡Yo también quiero mucho a Seria!","story.map7-ending.029":"¡Basta ya! <wait=40>¡¡Me das náuseas!!","story.map7-ending.030":"<size=12>Mira que eres tonta...","story.map7-ending.031":"¡Karl! <wait=40>¡Me voy!","story.map7-ending.032":"¡Ya hemos hecho lo que nos pidió el Salón de Invocadores!","story.map7-ending.033":"¡Ahora toca ir a por Graham!","story.map7-ending.034":"¡E-<wait=20>Espera!","story.map7-ending.035":"¡<rep_handlename>!","story.map7-ending.036":"¡Nunca he estado tan orgulloso de llamarte amigo!","story.map7-ending.037":"Cuando las cosas se calmen, <wait=20>¡vivamos juntos una aventura en Grand Gaia!","story.map7-ending.038":"¡No te lo creas tanto solo porque hayas derrotado a Cardes!","story.map7-ending.039":"Tu suerte se acabará tarde o temprano, ¿sabes?","story.map7-ending.040":"La próxima vez que nos veamos te mostraré el verdadero poder de la Invocadora al mando de los Cazademonios. ","story.map7-ending.041":"Pero hasta entonces, <wait=20>¡más te vale seguir de una pieza!","story.map7-ending.042":"Se han ido.","story.map7-ending.043":"¡Espero que algún día volvamos a luchar juntos!","story.map7-ending.044":"¡<rep_handlename>! <wait=40>¡Muchísimas gracias por derrotar a Cardes!","story.map7-ending.045":"Reconozco que al principio no podía confiar mucho en ti, <wait=40>pero ya has derrotado a dos de los Cuatro Dioses Caídos.","story.map7-ending.046":"¡Qué interesantes sois los humanos!","story.map7-ending.047":"Desde que os conocí a Karl, a Seria<wait=40> y a ti...","story.map7-ending.048":"...¡me gustáis los humanos más que nunca!","story.map7-ending.049":"Tengo ganas de vivir más aventuras contigo, <wait=40>mi <rep_handlename>.","story.map7-ending.050":"......<wait=40>Parece que el gran Cardes ha sido derrotado.","story.map7-ending.051":"Los únicos Dioses Caídos que quedan son Zevalhua el Supremo <wait=40>y el Dios Bestia Afla Dilith. ","story.map7-ending.052":"Sin duda ya va siendo hora de que ellos también intervengan.","story.map7-ending.053":"Debemos apresurar nuestros preparativos.","story.map7-ending.054":"<rep_handlename>...","story.map7-ending.055":"Tengo curiosidad por ver qué camino tomas en la próxima batalla...","story.map7-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Tú, <rep_handlename>,<wait=39> que desbloqueaste Encervis...","story.map7-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Usa mi poder al avanzar hacia Palmyna, <wait=40>tierra del Dios Caído sellado...","story.map7-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Para traer nueva esperanza a este mundo tan impregnado de tristeza...","story.map7-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Debes tener fe en tu poder <wait=20>y seguir avanzando...","story.map7-open.005":"¡<rep_handlename>!<wait=40> ¡Por fin has llegado a Palmyna!","story.map7-open.006":"¡Ya falta poco para el Mundo Espiritual donde está encerrado Cardes!","story.map7-open.007":"Como pudiste derrotar a Zebra, seguro que llegas allí sin problemas y a tiempo, <rep_handlename>.","story.map7-open.008":"Pero aun así, <wait=40>¡no te confíes!","story.map7-open.009":"Hace mucho tiempo aquí había un reino llamado Palmyna que luchó con valentía contra los dioses. ","story.map7-open.010":"Aún hoy se ven los restos de aquella guerra...","story.map7-open.011":"...junto con todos los espíritus y monstruos que siguen vagando por ahí.","story.map7-open.012":"Muy bien, <wait=40>déjame buscarnos un camino al Mundo Espiritual. ","story.map7-open.013":"Avanza a tu ritmo, <rep_handlename>.","story.map7-open.014":"¡Te esperaré justo más adelante, en el Castillo de Obselion!","story.map8-dungeon1.001":"¡Rayos! <wait=40>Todavía queda muchísimo.","story.map8-dungeon1.002":"Pero bueno, <wait=20>de nada sirve quejarse ahora.","story.map8-dungeon1.003":"¿Hmm? <wait=40>¡Eh, tú!","story.map8-dungeon1.004":"Tsk, <wait=20>pero si es nuestro querido <rep_handlename>.","story.map8-dungeon1.005":"¿Por qué estás aquí?","story.map8-dungeon1.006":"¡¿No será que...?!","story.map8-dungeon1.007":"¡¿Has venido a llevarte el mérito de mi duro trabajo, verdad?!","story.map8-dungeon1.008":"En fin, <wait=20>¿qué es eso que he oído sobre Cordelica?","story.map8-dungeon1.009":"Corre el rumor de que acabaste tú solo con uno de los Cuatro Dioses Caídos, ¿no?","story.map8-dungeon1.010":"Hmpf, <wait=40>¿o quizá, <wait=20>Karl y Seria tuvieron que venir a rescatarte?","story.map8-dungeon1.011":"Da igual, <wait=20>tampoco es que cambie nada.","story.map8-dungeon1.012":"¡Cierra el pico! <wait=40>¡No te he pedido ninguna explicación!","story.map8-dungeon1.013":"¡Si tienes dos dedos de frente, escucharás lo que tengo que decir!","story.map8-dungeon1.014":"En<wait=20> f<wait=20>in.","story.map8-dungeon1.015":"¡Más te vale no interponerte en mi camino! ¡Eso es todo!","story.map8-dungeon1.016":"Estoy en mitad de una misión importantísima en nombre del Salón de Invocadores.","story.map8-dungeon1.017":"Aunque no es nada que una élite como yo no pueda manejar.","story.map8-dungeon1.018":"Si me entiendes, ¡más te vale largarte a otra parte!","story.map8-dungeon1.019":"Y te lo prometo: si te encuentro merodeando por Cordelica, acabaré contigo en un santiamén.","story.map8-dungeon1.020":"¿Te ha quedado claro?","story.map8-dungeon2.001":"Uf, <wait=40>este lugar es más peligroso de lo que pensaba.","story.map8-dungeon2.002":"A este paso, aún me queda un largo camino hasta la torre.","story.map8-dungeon2.003":"Vaya, <wait=40>pero si es <rep_handlename>.","story.map8-dungeon2.004":"¿Qué estás haciendo aquí?","story.map8-dungeon2.005":"Jeje, <wait=40>supongo que no hace falta que lo pregunte.","story.map8-dungeon2.006":"El Salón de Invocadores debe de ir muy en serio para enviarte hasta aquí.","story.map8-dungeon2.007":"Aun así, <wait=20>no tengo intención de ceder.","story.map8-dungeon2.008":"La Guardia Imperial se hará con el poder oculto en Lizeria.","story.map8-dungeon2.009":"Jeje, <wait=40>no hace falta que pongas esa cara.","story.map8-dungeon2.010":"Vi de lo que eres capaz de verdad en Cordelica.","story.map8-dungeon2.011":"¿Por qué no dejas a esa panda de Akras y te unes a nosotros?","story.map8-dungeon2.012":"¡Para construir una paz verdadera, debes liberarte del control de los Ancianos!","story.map8-dungeon2.013":"¡¿Qué estás diciendo, <wait=40>perro imperial?!","story.map8-dungeon2.014":"Nada de lo que le digas a <rep_handlename> servirá.","story.map8-dungeon2.015":"Esa voz tan vulgar...","story.map8-dungeon2.016":"Cuánto tiempo...","story.map8-dungeon2.017":"Señorita Guardia Imperial.","story.map8-dungeon2.018":"Qué sorpresa. <wait=40>¿Cómo diablos has llegado hasta aquí?","story.map8-dungeon2.019":"No fue nada, la verdad.","story.map8-dungeon2.020":"Resulta que soy el Invocador elegido especialmente por el Salón de Invocadores para venir aquí a investigar.","story.map8-dungeon2.021":"Ese Invocador con cara de tonto de ahí es solo un turista en busca de emociones baratas.","story.map8-dungeon2.022":"<rep_handlename> no tiene ni idea de lo que pasa aquí.","story.map8-dungeon2.023":"Vamos, que no le estarías contando nada importante a este idiota, ¿verdad?","story.map8-dungeon2.024":"Ngh...","story.map8-dungeon2.025":"En fin, <wait=20>los verdaderos tontos aquí son los del Salón de Invocadores.","story.map8-dungeon2.026":"¿Cómo se les ocurre enviar a un Invocador de segunda como tú a un lugar como este?","story.map8-dungeon2.027":"Eso solo demuestra que no tienen ni idea de lo valiosa que es esta zona.","story.map8-dungeon2.028":"Y si de verdad es así, <wait=20>no debería tener problemas para hacerme con el poder oculto aquí.","story.map8-dungeon2.029":"¡Eh! <wait=40>¡Cuidado con lo que dices!","story.map8-dungeon2.030":"¡No tendrías ninguna oportunidad contra mí si lo diera todo!","story.map8-dungeon2.031":"Jeje, <wait=40>menuda cara que pones.","story.map8-dungeon2.032":"Pero, de verdad, <wait=20>no hace falta que te hagas el duro.","story.map8-dungeon2.033":"Tampoco es que tenga tiempo para jugar contigo.","story.map8-dungeon2.034":"¿Estás huyendo?","story.map8-dungeon2.035":"No, <wait=40>simplemente evito cualquier enfrentamiento inútil para cumplir mi objetivo.","story.map8-dungeon2.036":"<rep_handlename>, <wait=40>piensa en lo que hemos hablado hace un momento.","story.map8-dungeon2.037":"Seguro que te beneficiaría más que tener aliados tan tontos como él.","story.map8-dungeon2.038":"<size=22>¡¿De qué estás hablando?!</size>","story.map8-dungeon2.039":"Je, <wait=40>al final ha huido.","story.map8-dungeon2.040":"¡Eh! <wait=40>¡<rep_handlename>!","story.map8-dungeon2.041":"¿Por qué siempre te encuentro en sitios como este?","story.map8-dungeon2.042":"¿Me estás diciendo que no piensas hacerme caso?","story.map8-dungeon2.043":"¿O quizá, <wait=20>piensas aceptar su oferta y traicionar al Salón de Invocadores?","story.map8-dungeon2.044":"Aunque a mí me da igual lo que hagas.","story.map8-dungeon2.045":"Si vuelves a ignorar mi advertencia, <wait=20>la próxima vez que te vea...","story.map8-dungeon2.046":"...no me quedará más remedio que reducirte a polvo.","story.map8-dungeon2.047":"Je, <wait=40>¡menudo fastidio eres!","story.map8-dungeon2.048":"Pero tranquilo, <wait=40>no intento amenazarte ni nada.","story.map8-dungeon2.049":"¡Solo quería que supieras que no dejo que nadie se interponga en mi camino!","story.map8-dungeon2.050":"¿Te ha quedado claro?","story.map8-dungeon3.001":"Eh, <wait=40><rep_handlename>.","story.map8-dungeon3.002":"Pareces estar de buen humor.","story.map8-dungeon3.003":"¡Espera!","story.map8-dungeon3.004":"Si has ignorado mi advertencia viniendo aquí, solo puede significar que piensas traicionar al Salón de Invocadores, ¿me equivoco?","story.map8-dungeon3.005":"¿Qué condiciones te ha puesto esa mujer?","story.map8-dungeon3.006":"¿Hmm? <wait=40>¿Dices que no eres un traidor?","story.map8-dungeon3.007":"<size=22>¡Ja, ja, ja!</size>","story.map8-dungeon3.008":"Para ser tan tonto, has tomado una decisión interesante.","story.map8-dungeon3.009":"Lo cual solo puede significar una cosa...","story.map8-dungeon3.010":"Has venido con la intención de causarme problemas, ¿verdad?","story.map8-dungeon3.011":"¡Ja, ja, ja! <wait=40>¡Qué gracioso eres!","story.map8-dungeon3.012":"<size=22>¡No te lo tengas tan creído!</size>","story.map8-dungeon3.013":"¿Quieres que te enseñe lo inferior que eres a mí?","story.map8-dungeon3.014":"Qué idiota.","story.map8-dungeon3.015":"Es que no te soporto.","story.map8-dungeon3.016":"Ah, y por cierto, he oído que también eres amigo de ese zoquete de Karl.","story.map8-dungeon3.017":"Parece que no me queda más remedio que darte una lección y mostrarte lo increíble que soy.","story.map8-dungeon3.018":"¿Qué te parece? <wait=20>Te esperaré al otro lado de este lago helado.","story.map8-dungeon3.019":"¡Te daré la lección en persona, así que más te vale estar deseándolo!","story.map8-dungeon4.001":"¡N-<wait=20>No puede ser! <wait=40>Es imposible.","story.map8-dungeon4.002":"¡¿También derrotó a Cardes?!","story.map8-dungeon4.003":"N-<wait=20>No, <wait=40>no dudo de usted...","story.map8-dungeon4.004":"Entendido. <wait=40>Me encargaré de esto con el mayor cuidado posible.","story.map8-dungeon4.005":"Sí. <wait=40>No hay de qué preocuparse.","story.map8-dungeon4.006":"Haré todo lo posible por no decepcionarle.","story.map8-dungeon4.007":"Uf... <wait=40>Las cosas se están complicando mucho más rápido de lo que esperaba.","story.map8-dungeon4.008":"¿Eh? <wait=20>¿Acaso es...?","story.map8-dungeon4.009":"Jeje, <wait=40>volvemos a encontrarnos.","story.map8-dungeon4.010":"¿Debo suponer que has derrotado a Lugina?","story.map8-dungeon4.011":"Seguro que derrotar a un Invocador tan débil no fue problema para ti, habiendo derrotado ya a dos de los Cuatro Dioses Caídos, ¿no?","story.map8-dungeon4.012":"Jeje, <wait=20>no me mires así.","story.map8-dungeon4.013":"Sé lo mucho más poderoso que eres en realidad comparado con él.","story.map8-dungeon4.014":"Así que, <wait=20>deja que te lo pregunte una vez más.","story.map8-dungeon4.015":"¿No dejarías atrás el Salón de Invocadores de Akras para trabajar con nosotros?","story.map8-dungeon4.016":"La última vez no tuvimos tiempo de hablar, porque nos interrumpieron de tan malas maneras.","story.map8-dungeon4.017":"Pero lo digo en serio.","story.map8-dungeon4.018":"Jeje, <wait=20>es lógico que una invitación tan repentina te desconcierte.","story.map8-dungeon4.019":"Solo deja que te diga una cosa. <wait=40>El sistema de gobierno de Elgaia está roto.","story.map8-dungeon4.020":"Y nosotros somos los únicos que podemos arreglarlo.","story.map8-dungeon4.021":"Tú también ves lo que está pasando, ¿verdad?","story.map8-dungeon4.022":"En lugar de una república, el mundo lo dirige una organización de Invocadores.","story.map8-dungeon4.023":"Hace mucho tiempo, <wait=20>unos pocos escaparon del trágico choque con los dioses.","story.map8-dungeon4.024":"Ellos guiaron al pueblo y fundaron el Imperio de Randall.","story.map8-dungeon4.025":"Luego, <wait=20>mucho tiempo después de fundarse el imperio...","story.map8-dungeon4.026":"...surgieron varios grupos opuestos a la clase privilegiada del Imperio de Randall.","story.map8-dungeon4.027":"Ellos fundaron la Federación de Elgaia.","story.map8-dungeon4.028":"Más recientemente, fue Elgaia la primera en empezar a cambiar.","story.map8-dungeon4.029":"Durante este cambio aparecieron los Invocadores, <wait=20>así como alguien que deseaba unirlos a todos.","story.map8-dungeon4.030":"Ellos fundaron el Salón de Invocadores de Akras.","story.map8-dungeon4.031":"Los Invocadores de antaño que crearon el Salón de Invocadores de Akras...","story.map8-dungeon4.032":"...también conocidos como los \\"Invocadores Originales\\" por ser los primeros en cruzar la puerta...","story.map8-dungeon4.033":"...usando los asombrosos poderes de invocación que habían adquirido...","story.map8-dungeon4.034":"...formaron una de las mayores organizaciones de todo Elgaia.","story.map8-dungeon4.035":"Con el inmenso poder de los Invocadores, esta organización fue tomando también el control económico.","story.map8-dungeon4.036":"Antes de que nadie se diera cuenta, la república se había convertido en una mera sombra de lo que fue.","story.map8-dungeon4.037":"Ahora, tanto el Imperio de Randall como la Federación de Elgaia no son más que cascarones vacíos.","story.map8-dungeon4.038":"Jeje, <wait=40>tu cara me dice que ya lo has entendido.","story.map8-dungeon4.039":"Sin embargo, <wait=40>parece que no te supone ningún problema.","story.map8-dungeon4.040":"Claro, <wait=20>quién controla qué no tiene nada que ver con la gente corriente.","story.map8-dungeon4.041":"Pero el mundo no debería tomarse tan a la ligera.","story.map8-dungeon4.042":"Me pregunto si seguirías del lado del Salón de Invocadores si conocieras su lado oscuro.","story.map8-dungeon4.043":"Si prometes aliarte con nosotros a partir de ahora, te lo contaré todo.","story.map8-dungeon4.044":"Jeje, <wait=20>pero no hay prisa.","story.map8-dungeon4.045":"Porque pase lo que pase, en cuanto me haga con el poder que se oculta aquí...","story.map8-dungeon4.046":"...no te quedará más remedio que seguirnos por nuestro justo camino.","story.map8-dungeon4.047":"......","story.map8-dungeon4.048":"Bueno, <wait=40>debería irme ya.","story.map8-dungeon4.049":"Espero volver a hablar contigo sin que nos interrumpa ese tonto vulgar.","story.map8-dungeon5.001":"<rep_handlename>.","story.map8-dungeon5.002":"Eh, <wait=40>¿qué mosca te ha picado de repente?","story.map8-dungeon5.003":"¿No pensarás que fuiste más fuerte que yo en esa última pelea?","story.map8-dungeon5.004":"Parece que no te has dado cuenta de lo blando que fui contigo.","story.map8-dungeon5.005":"Parece que necesitas que te lo recuerde.","story.map8-dungeon5.006":"¿Eh? <wait=40>¿Que si conozco el lado oscuro del Salón de Invocadores?","story.map8-dungeon5.007":"Idiota, <wait=20>¿qué clase de historia disparatada te ha metido esa mujer en la cabeza?","story.map8-dungeon5.008":"¡Te dije que no escucharas a esa mujer!","story.map8-dungeon5.009":"Además, lo que haga el Salón de Invocadores no tiene nada que ver con nosotros.","story.map8-dungeon5.010":"Básicamente, lo único que importa es quién es el más poderoso de Elgaia.","story.map8-dungeon5.011":"¿Será la Federación de Elgaia y sus entusiastas masas?","story.map8-dungeon5.012":"¿O el Imperio de Randall y su anticuado ejército?","story.map8-dungeon5.013":"O quizá ninguno de los dos.","story.map8-dungeon5.014":"Aunque yo creo que el Salón de Invocadores de Akras es el más fuerte.","story.map8-dungeon5.015":"La élite del Salón de Invocadores es la élite de Elgaia.","story.map8-dungeon5.016":"No hay más que hablar.","story.map8-dungeon5.017":"Y por eso tengo que dar lo mejor de mí por el Salón de Invocadores.","story.map8-dungeon5.018":"Pero que te metas en mi camino cuando ya estoy trabajando duro empieza a sacarme de quicio.","story.map8-dungeon5.019":"Por eso hoy no voy a ser blando contigo.","story.map8-dungeon5.020":"Te estaré esperando más adelante.","story.map8-dungeon5.021":"<size=20>¡Te demostraré lo diferentes que somos!</size>","story.map8-dungeon5.022":"<size=20>¡Más te vale prepararte!</size>","story.map8-dungeon6.001":"<rep_handlename>. <wait=40>Así que has venido.","story.map8-dungeon6.002":"Mira. <wait=40>¿No es increíble?","story.map8-dungeon6.003":"Hace mucho tiempo, aquí se alzaba la República de La Veda, donde la gente rezaba al dios de la luz.","story.map8-dungeon6.004":"Sin embargo, <wait=20>esa misma gente fue destruida por el mismo dios al que rezaba.","story.map8-dungeon6.005":"Qué escena tan terrible.","story.map8-dungeon6.006":"Existen varios registros de la batalla contra los dioses.","story.map8-dungeon6.007":"El primero y más importante es la leyenda de los Seis Héroes.","story.map8-dungeon6.008":"Sin embargo, <wait=20>aún hay mucho que se desconoce.","story.map8-dungeon6.009":"En concreto, <wait=20>poco se sabe de lo que ocurrió en Grand Gaia...","story.map8-dungeon6.010":"...después de que Lucius salvara a la gente.","story.map8-dungeon6.011":"¿Qué estaba haciendo Lucius exactamente...","story.map8-dungeon6.012":"...mientras los Cuatro Dioses Caídos cometían tantas crueldades?","story.map8-dungeon6.013":"¿Y por qué el gran líder de los dioses, Carna Masta, aún no ha movido ficha?","story.map8-dungeon6.014":"Jeje, <wait=20>pensar en ello hace que te preocupes por lo seguros que estamos en realidad.","story.map8-dungeon6.015":"Yo...","story.map8-dungeon6.016":"No, <wait=20>nosotros vivimos con miedo ante la situación actual.","story.map8-dungeon6.017":"En tiempos tan inciertos como estos...","story.map8-dungeon6.018":"...¿quién sabe cuándo podrían decidir los dioses volver a destruir y apuntar a Elgaia?","story.map8-dungeon6.019":"Por eso necesitamos hacernos con el gran poder que descansa aquí.","story.map8-dungeon6.020":"El poder que, según dicen, descansa en la tierra donde antaño la gente adoraba al dios de la luz.","story.map8-dungeon6.021":"Jeje, <wait=40>otra vez esa cara de preocupación.","story.map8-dungeon6.022":"No hay prisa. <wait=40>Tómate tu tiempo para asimilar todo esto.","story.map8-dungeon6.023":"Pero también, <wait=20>me gustaría que pensaras en el futuro.","story.map8-dungeon6.024":"¿Cuál es el camino justo para crear un mundo donde la gente pueda vivir en paz?","story.map8-dungeon6.025":"Bueno, <wait=20>debo marcharme.","story.map8-dungeon6.026":"Ah, <wait=20>y una cosa más...","story.map8-dungeon6.027":"Hace un rato vi a Lugina dirigiéndose a un puente negro un poco más adelante con una cara muy amenazante.","story.map8-dungeon6.028":"Ten cuidado, ¿de acuerdo?","story.map8-dungeon6.029":"Jejeje.","story.map8-dungeon7-2.001":"I-<wait=40>Imposible...","story.map8-dungeon7-2.002":"¿Cómo he podido perder contra...?","story.map8-dungeon7-2.003":"Ngh...","story.map8-dungeon7-2.004":"<size=18>Esto no puede ser verdad...</size>","story.map8-dungeon7-2.005":"<size=24>¡Me niego a aceptarlo!</size>","story.map8-dungeon7-2.006":"¡Es imposible que yo pierda contra ti!","story.map8-dungeon7-2.007":"Imposible...","story.map8-dungeon7-2.008":"<size=20>¡No! <wait=40>¡No! <wait=40>¡No!","story.map8-dungeon7-2.009":"<size=18>¿Cómo he podido perder...?</size>","story.map8-dungeon7-2.010":"Hmpf, <wait=40>¿qué miras?","story.map8-dungeon7-2.011":"¡Lárgate de una vez!","story.map8-dungeon7-2.012":"<size=20>¡¡Maldito seas!!</size>","story.map8-dungeon7-2.013":"Maldita sea...","story.map8-dungeon7.001":"Me he cansado de esperar, <rep_handlename>.","story.map8-dungeon7.002":"Estaba seguro de que pasarías por aquí.","story.map8-dungeon7.003":"Lo que buscamos esa mujer y yo está, al parecer, en la torre de un poco más adelante.","story.map8-dungeon7.004":"<size=20>¡Argh!</size>","story.map8-dungeon7.005":"¡Otra vez esa cara tan irritante!","story.map8-dungeon7.006":"A pesar de esa cara de desinterés, no eres diferente de ella: tu curiosidad se interpone en mi camino.","story.map8-dungeon7.007":"Sin tener ni idea de nada, ¿de verdad piensas ir tras mi trofeo?","story.map8-dungeon7.008":"Empiezas a sacarme de mis casillas.","story.map8-dungeon7.009":"Esta misión es mi oportunidad de mostrarles mi verdadero poder a esos vejestorios.","story.map8-dungeon7.010":"¡No puedo dejar que un novato como tú se interponga en mi camino!","story.map8-dungeon7.011":"¡No dejaré que este logro se lo lleve nadie más!","story.map8-dungeon7.012":"¡Aplastaré a cualquiera que se interponga en mi camino!","story.map8-dungeon7.013":"Ngh, <wait=20>¡¿qué es esa cara?! ¡No te asustes ahora!","story.map8-dungeon7.014":"Da igual.","story.map8-dungeon7.015":"Esta es mi última advertencia.","story.map8-dungeon7.016":"La próxima vez que me cruce contigo...","story.map8-dungeon7.017":"<size=22>¡Será tu fin!</size>","story.map8-dungeon7.018":"<size=22>¿Te enteras?</size>","story.map8-dungeon8.001":"Ngh...","story.map8-dungeon8.002":"Esto es inesperado, <wait=20>no pensé que sería tan duro.","story.map8-dungeon8.003":"Aun así, <wait=20>¡estas heridas insignificantes no van a hacer que me rinda!","story.map8-dungeon8.004":"Tengo que encontrar la puerta para Eriole sin falta.","story.map8-dungeon8.005":"¡Eh! <wait=40>¡<rep_handlename>!","story.map8-dungeon8.006":"No puedo creer que me hayas alcanzado.","story.map8-dungeon8.007":"Si estás aquí, debe ser que pudiste derrotar a Lugina, ¿verdad?","story.map8-dungeon8.008":"Quizá sea algo tosco, <wait=20>pero como líder de los Cazademonios, es más que temible.","story.map8-dungeon8.009":"Debes de tener un gran poder para haber podido derrotarlo.","story.map8-dungeon8.010":"Ngh...","story.map8-dungeon8.011":"Jeje, <wait=20>estas heridas no son nada, no te preocupes.","story.map8-dungeon8.012":"Solo tuve un pequeño contratiempo.","story.map8-dungeon8.013":"Ahora más que nunca, mi objetivo es obtener el poder oculto que aguarda aquí.","story.map8-dungeon8.014":"Ni siquiera a ti te dejaría interponerte en mi camino.","story.map8-dungeon8.015":"Jaja, <wait=40>qué expresión tan aterradora.","story.map8-dungeon8.016":"Aun así, <wait=20>lo digo en serio.","story.map8-dungeon8.017":"Creo que el poder que descansa aquí puede devolver el mundo a como debería ser.","story.map8-dungeon8.018":"¿Sabes qué es lo que nos espera aquí?","story.map8-dungeon8.019":"Es una torre que, según dicen, existe desde antes incluso de que se fundara La Veda.","story.map8-dungeon8.020":"Puede que La Veda incluso se construyera para vigilar la torre.","story.map8-dungeon8.021":"En otras palabras, <wait=40>lo que nos espera aquí es más que importante.","story.map8-dungeon8.022":"Probablemente también haya incontables trampas colocadas para protegerla.","story.map8-dungeon8.023":"¿Entiendes lo que quiero decir?","story.map8-dungeon8.024":"Si es así, <wait=40>más te vale no avanzar más.","story.map8-dungeon8.025":"No querrás acabar luchando contra mí, ¿verdad?","story.map8-dungeon8.026":"Jejeje.","story.map8-dungeon8.027":"Espero que sigas mi consejo y des media vuelta.","story.map8-dungeon8.028":"Bueno, <wait=40>me marcho.","story.map8-dungeon8.029":"Volveremos a hablar cuando haya cumplido mi objetivo.","story.map8-dungeon8.030":"No creas que he renunciado a intentar ganarte para nuestro bando.","story.map8-dungeon8.031":"Jejeje.","story.map8-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map8-dungeon_ex_clear.002":"¡Señor! <wait=40>¿Estás bien?","story.map8-dungeon_ex_clear.003":"*Suspiro* <wait=20>Qué alivio.","story.map8-dungeon_ex_clear.004":"Los agentes del Salón de Invocadores siguieron investigando el lago subterráneo después de que te fueras.","story.map8-dungeon_ex_clear.005":"Parece que el dios Lagzal descansaba allí.","story.map8-dungeon_ex_clear.006":"También apareció en Grand Gaia durante la gran batalla entre los dioses y los humanos.","story.map8-dungeon_ex_clear.007":"Según nuestros registros, en su día lo derrotó un solo héroe.","story.map8-dungeon_ex_clear.008":"Sin embargo, parece que no fue destruido del todo, sino que se retiró aquí.","story.map8-dungeon_ex_clear.009":"El corazón me dio un vuelco cuando encontramos esta información.","story.map8-dungeon_ex_clear.010":"¡Es que se cobró la vida de muchísimas personas en batalla!","story.map8-dungeon_ex_clear.011":"Estaba muy preocupada cuando supe que te enfrentarías a él...","story.map8-dungeon_ex_clear.012":"......","story.map8-dungeon_ex_clear.013":"¡Ya es tarde para disculparse!","story.map8-dungeon_ex_clear.014":"......","story.map8-dungeon_ex_clear.015":"*Suspiro* <wait=40>Pero, al fin y al cabo, eres un Invocador.","story.map8-dungeon_ex_clear.016":"A partir de ahora investigarás lugares cada vez más peligrosos.","story.map8-dungeon_ex_clear.017":"Si de verdad quiero apoyarte, no debería intentar detenerte.","story.map8-dungeon_ex_clear.018":"¡Entendido!","story.map8-dungeon_ex_clear.019":"¡Creo en ti, señor!","story.map8-dungeon_ex_clear.020":"¡Y siempre puedes contar conmigo, señor!","story.map8-dungeon_ex_clear.021":"Jejeje.","story.map8-dungeon_ex_clear.022":"¡Bueno, me pondré en contacto si llega más información!","story.map8-dungeon_ex_clear.023":"¡Cuídate mucho hasta entonces!","story.map8-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map8-dungeon_ex_open.002":"Señor, <wait=40>¿me oyes?","story.map8-dungeon_ex_open.003":"Genial, <wait=20>esta vez he conseguido comunicarme a la primera.","story.map8-dungeon_ex_open.004":"Soy Lin Merylham, de Apoyo Logístico...","story.map8-dungeon_ex_open.005":"...de la Oficina de Investigación del Departamento de Exploración de Grand Gaia, a tu servicio.","story.map8-dungeon_ex_open.006":"<rep_handlename>, como miembro del Ejército de Invocadores del Salón de Invocadores de Akras...","story.map8-dungeon_ex_open.007":"...¡hoy te pedimos que investigues el Lago Subterráneo de Golzo!","story.map8-dungeon_ex_open.008":"Hace unos días, el Salón de Invocadores detectó la desaparición de una gran fuerza en Lizeria.","story.map8-dungeon_ex_open.009":"Justo después, detectamos una fuerza aún mayor aquí, en este lago subterráneo.","story.map8-dungeon_ex_open.010":"Nos gustaría que investigaras qué está pasando exactamente aquí.","story.map8-dungeon_ex_open.011":"Personalmente, tengo un mal presentimiento, así que no pasa nada si prefieres no ir...","story.map8-dungeon_ex_open.012":"...pero tu tono de voz dice lo contrario.","story.map8-dungeon_ex_open.013":"¡Tan ambicioso como siempre!","story.map8-dungeon_ex_open.014":"¡Entendido!","story.map8-dungeon_ex_open.015":"¡Por muy preocupada que esté, te animaré como siempre!","story.map8-dungeon_ex_open.016":"Así que, por favor, <wait=40>¡vuelve sano y salvo!","story.map8-dungeon_ex_open.017":"¿Entendido?","story.map8-dungeon_ex_open.018":"Hmpf...","story.map8-ending.001":"Haber acabado con un sistema de defensa como ese...","story.map8-ending.002":"Supongo que es el poder que cabía esperar de alguien que ha derrotado a un Dios Caído.","story.map8-ending.003":"Aun así, <wait=20>¡no pienso renunciar a lo que está sellado tras la puerta de ahí delante!","story.map8-ending.004":"Mírate, <rep_handlename>.","story.map8-ending.005":"Ni siquiera estás tan malherido, ¿y aun así no puedes moverte?","story.map8-ending.006":"Tsk, <wait=40>me fastidia muchísimo pensar que me costó tanto lidiar contigo.","story.map8-ending.007":"¿Eh? <wait=40>¿Qué quieres decir con que me dé prisa?","story.map8-ending.008":"Je, <wait=20>no te han contado nada, ¿verdad?","story.map8-ending.009":"Ven conmigo.","story.map8-ending.010":"Vamos a ver en qué lío interesante se ha metido esa mujer.","story.map8-ending.011":"E-<wait=20>Espera. <wait=20>¿Cómo puede no haber nada?","story.map8-ending.012":"¿Significa esto que nos engañaron?","story.map8-ending.013":"¿Cómo pudimos...?","story.map8-ending.014":"¿Qué se gana engañándonos así?","story.map8-ending.015":"¡Eh, <rep_handlename>! <wait=40>¡Mira!","story.map8-ending.016":"Es justo lo que dije.","story.map8-ending.017":"Parece que la señorita Guardia Imperial está en un pequeño apuro.","story.map8-ending.018":"Lugina...","story.map8-ending.019":"Jejeje. <wait=40>Deja ya esas caras de miedo.","story.map8-ending.020":"El poder que buscas no está por aquí.","story.map8-ending.021":"Está en las ruinas de la puerta.","story.map8-ending.022":"Lo sé porque los Invocadores Ancianos me enviaron a investigarlo.","story.map8-ending.023":"Aun así, me ha divertido escuchar tu enfática cháchara.","story.map8-ending.024":"Imbécil vulgar.","story.map8-ending.025":"<size=20>¡Bua, ja, ja, ja!</size>","story.map8-ending.026":"Ya puedes fulminarme con la mirada todo lo que quieras, que la puerta no se va a abrir.","story.map8-ending.027":"Ngh...","story.map8-ending.028":"<rep_handlename>.","story.map8-ending.029":"¿Cómo soportas estar tanto tiempo con un hombre tan vulgar?","story.map8-ending.030":"Sabes a qué me refiero, ¿verdad?","story.map8-ending.031":"¡Este hombre es pura basura!","story.map8-ending.032":"Solo espero el día en que aceptes mi invitación.","story.map8-ending.033":"Oh, <wait=20>¡qué celos! <wait=40>¡Yo también quería que me invitaran, ¿sabes?!","story.map8-ending.034":"Aunque sería una pena perder el tiempo en tu inútil causa.","story.map8-ending.035":"Ngh.","story.map8-ending.036":"Recuerda esto.","story.map8-ending.037":"Algún día haré que te arrepientas de todo lo que has hecho.","story.map8-ending.038":"Je, <wait=20>por fin se ha ido.","story.map8-ending.039":"Eh, <rep_handlename>.","story.map8-ending.040":"¿Por qué pareces tan tranquilo de repente?","story.map8-ending.041":"No pensarás que te he perdonado, ¿verdad?","story.map8-ending.042":"Me haré aún más poderoso de lo que era antes.","story.map8-ending.043":"Y cuando lo consiga, voy a aprovecharme de ti todo lo que pueda.","story.map8-ending.044":"¡No lo olvides!","story.map8-ending.045":"Je.","story.map8-ending.046":"Ah, <wait=20>y una cosa más...","story.map8-ending.047":"Parece que de verdad no tenías ni idea de lo que buscábamos esta vez.","story.map8-ending.048":"Al principio pensé que solo intentabas engañarme para tomarme la delantera.","story.map8-ending.049":"¡Pero al final parece que eras tan tonto como parecías!","story.map8-ending.050":"<size=20>¡Bua, ja, ja, ja!</size>","story.map8-ending.051":"El próximo logro será mío.","story.map8-ending.052":"¡Y más te vale agradecer todo lo que yo, el Invocador más increíblemente poderoso del mundo, he hecho por ti!","story.map8-ending.053":"Ya veo, <wait=20>así que la puerta ha desaparecido.","story.map8-ending.054":"No pasa nada. <wait=20>No hace falta que te disculpes.","story.map8-ending.055":"Hiciste lo que pudiste con una tarea difícil.","story.map8-ending.056":"Sí, <wait=20>cuídate y vuelve sana y salva.","story.map8-ending.057":"Jejeje.","story.map8-ending.058":"Parece que todo era exactamente como dijiste.","story.map8-ending.059":"Parece que el contrato se ha cumplido.","story.map8-ending.060":"Ya es hora de que nosotros también nos pongamos en marcha.","story.map8-ending.061":"Sí, <wait=40>mi amo también espera tu despliegue.","story.map8-ending.062":"Jejeje.","story.map8-ending.063":"<size=20>¡Devolvamos el mundo a su verdadera forma!</size>","story.map8-ending.064":"<size=20>¡Lo veremos cambiar y evolucionar ante nuestros propios ojos!</size>","story.map8-ending.065":"<size=20>¡Ya lo veréis!</size>","story.map8-ending.066":"<size=20>¡Pronto nacerá un nuevo héroe!</size>","story.map8-open.001":"Randall,<wait=40> capital del Imperio de Randall.","story.map8-open.002":"La sala privada de los guardaespaldas de la familia imperial, <wait=40>la Guardia Imperial.","story.map8-open.003":"*Toc* <wait=20>*toc*","story.map8-open.004":"Adelante.","story.map8-open.005":"Disculpe la intromisión.","story.map8-open.006":"Vaya, <wait=40> qué cara tan agradable. <wait=20>¿Debo suponer que me traes buenas noticias?","story.map8-open.007":"Sí, <wait=20>y le pido disculpas por haber tardado tanto.","story.map8-open.008":"Nuestra investigación nos lleva a creer que la puerta que buscamos está en Lizeria.","story.map8-open.009":"...Lizeria.","story.map8-open.010":"Si no recuerdo mal, se supone que allí existió La Veda.","story.map8-open.011":"Ya veo. <wait=20>Parece que, después de todo, no nos mintieron.","story.map8-open.012":"Así es.","story.map8-open.013":"Aunque dudo que toda la información que recibimos sea exacta, creo que al menos esto lo era.","story.map8-open.014":"......","story.map8-open.015":"Me gustaría ir allí para confirmarlo en persona.","story.map8-open.016":"¿Me concede permiso para hacerlo?","story.map8-open.017":"Que yo sepa, el Ejército de Invocadores ha iniciado una nueva investigación en esa zona.","story.map8-open.018":"Entendido. <wait=40>Haré lo posible por terminar cuanto antes.","story.map8-open.019":"Es una empresa bastante peligrosa, ¿sabes?","story.map8-open.020":"Estoy dispuesta a sacrificarme por la verdadera paz.","story.map8-open.021":"Cuento contigo.","story.map8-open.022":"No hace falta que diga esas cosas.","story.map8-open.023":"¡Me aseguraré de que todo salga bien!","story.map8-open.024":"Buena suerte.","story.map8-open.025":"¡¿Quién anda ahí?!","story.map8-open.026":"Parece que tienes algo que decir.","story.map8-open.027":"¿Estabas escuchando? <wait=40>¿Por qué no sales?","story.map8-open.028":"......","story.map8-open.029":"Ya veo. <wait=40>Ni siquiera hace falta que lo digas.","story.map8-open.030":"No hay tiempo que perder. <wait=20>Debemos devolver el mundo a su forma correcta.","story.map8-open.031":"Me pregunto si esa panda del Ejército de Invocadores llegará a entenderlo algún día...","story.map8-open.032":"...cómo estaba destinado a ser este mundo en realidad.","story.map9-dungeon1.001":"¡Hola, <wait=20><rep_handlename>!","story.map9-dungeon1.002":"Así que tú también has venido a Ryvern, <wait=20>la entrada a la región de Agni. ","story.map9-dungeon1.003":"Supongo que vas tras Zevalhua, <wait=20>el siguiente de los Dioses Caídos. ","story.map9-dungeon1.004":"¡Por supuesto, esta vez también te ayudaremos, así que no debería haber ningún problema!","story.map9-dungeon1.005":"¡Karl! <wait=40>¡¿Recuerdas que tenemos nuestros propios objetivos?!","story.map9-dungeon1.006":"No tengo ningunas ganas de ayudar a <rep_handlename>, <wait=20>sobre todo porque el Salón de Invocadores ni siquiera nos lo ha pedido.","story.map9-dungeon1.007":"Jaja, <wait=20>igual que siempre, ¿eh, Seria?","story.map9-dungeon1.008":"<rep_handlename> ya ha derrotado a dos de los Cuatro Dioses Caídos. ","story.map9-dungeon1.009":"¿No crees que al menos deberías reconocerlo?","story.map9-dungeon1.010":"Hum, <wait=20>reconozco el poder que ha hecho falta.","story.map9-dungeon1.011":"¡Pero mira qué cara de suficiencia!","story.map9-dungeon1.012":"¡Solo te lo advierto, <wait=20>nada más!","story.map9-dungeon1.013":"¡<rep_handlename>! <wait=20>¡Deberías estarme agradecido!","story.map9-dungeon1.014":"¡Ah! <wait=20>¡Estás aquí!","story.map9-dungeon1.015":"¡<rep_handlename>! <wait=20>¿Por qué has tardado tanto?","story.map9-dungeon1.016":"¡Oh, <wait=20>Karl y Seria!","story.map9-dungeon1.017":"Hola, <wait=20>diosa.","story.map9-dungeon1.018":"Al final ha aparecido...","story.map9-dungeon1.019":"¡Eh, vosotros dos!","story.map9-dungeon1.020":"Esta vez también vais a ayudar a <rep_handlename>, ¿verdad?","story.map9-dungeon1.021":"¡Nosotros vamos tras Graham!","story.map9-dungeon1.022":"No te preocupes por eso ahora.","story.map9-dungeon1.023":"Seguro que se os vuelve a escapar, <wait=20>así que ¿por qué no ayudáis desde el principio esta vez?","story.map9-dungeon1.024":"Eso ha sido bastante cruel.","story.map9-dungeon1.025":"¡Serás...!","story.map9-dungeon1.026":"Es muy divertido vivir aventuras así con todos vosotros.","story.map9-dungeon1.027":"Siento que, por muy dura que sea la lucha, de algún modo saldremos adelante, ¿no creéis?","story.map9-dungeon1.028":"Jaja, <wait=20>si la diosa lo dice, supongo que no nos queda otra.","story.map9-dungeon1.029":"¿Verdad, <wait=20>Seria?","story.map9-dungeon1.030":"Eres un blando, Karl...","story.map9-dungeon1.031":"En fin, <wait=20>seguro que Lord Grahdens nos lo pedirá de todos modos, así que supongo que podemos ayudar. ","story.map9-dungeon1.032":"¡Al final eres un encanto, Seria!","story.map9-dungeon1.033":"¡Q-<wait=20>¿Qué te pasa?!","story.map9-dungeon1.034":"Solo ayudo porque no nos queda otra opción.","story.map9-dungeon1.035":"Ja, ja, ja. <wait=20>Parece que ya hemos decidido.","story.map9-dungeon1.036":"Dicho esto, ¡estamos todos juntos en esto, <rep_handlename>!","story.map9-dungeon1.037":"¡Demos lo mejor de nosotros y démosle una paliza a ese Zevalhua!","story.map9-dungeon1.038":"¡Genial! <wait=40>¡Dadlo todo, chicos!","story.map9-dungeon1.039":"*Suspiro* <wait=20>Sigo sin estar segura de esto...","story.map9-dungeon1.040":"Hum. <wait=40>Qué patético...","story.map9-dungeon2.001":"Hola, <rep_handlename>. <wait=40>Llegas un poco tarde. ","story.map9-dungeon2.002":"La diosa estaba aquí hace un momento.","story.map9-dungeon2.003":"Luego tuvo una especie de pelea con Seria, <wait=20>y las dos se adelantaron. ","story.map9-dungeon2.004":"Ja, ja, ja. <wait=40>Esas dos <wait=40>se han hecho muy amigas, ¿no crees?","story.map9-dungeon2.005":"¡Ayudémonos mutuamente para no quedarnos atrás!","story.map9-dungeon2.006":"Qué seres tan patéticos sois los humanos.","story.map9-dungeon2.007":"¿Quién anda ahí?","story.map9-dungeon2.008":"No hace falta que tengáis miedo.","story.map9-dungeon2.009":"Me llamo Mare.","story.map9-dungeon2.010":"Soy discípula de Zevalhua el Supremo.","story.map9-dungeon2.011":"¿Una discípula de Zevalhua?","story.map9-dungeon2.012":"¿Así que has venido a matarnos? ","story.map9-dungeon2.013":"Qué irrespetuoso hablar así de Lord Zevalhua...","story.map9-dungeon2.014":"No es más que otra muestra de vuestra ignorancia. Qué triste...","story.map9-dungeon2.015":"Aun así, no me malinterpretéis.","story.map9-dungeon2.016":"Acabar con vosotros dos no es algo en lo que tenga que jugarme mi nombre.","story.map9-dungeon2.017":"Mi objetivo no eres tú, Invocador, <wait=40>sino el del pelo azul. <wait=40>Voy a por ti.","story.map9-dungeon2.018":"¿Yo soy tu objetivo?","story.map9-dungeon2.019":"¿Qué quieres de mí?","story.map9-dungeon2.020":"He pensado en hacer de dios y revelarte la verdad. ","story.map9-dungeon2.021":"¿La verdad?","story.map9-dungeon2.022":"Te has dejado engañar por ese necio de Grahdens y ahora tu vida es un caos.","story.map9-dungeon2.023":"Serás... <wait=60>¿Qué es exactamente lo que tramas?","story.map9-dungeon2.024":"No hace falta que desconfíes. ","story.map9-dungeon2.025":"Fueron tus mayores quienes te dejaron al cuidado de otro nada más encontrarte.","story.map9-dungeon2.026":"Tuviste una infancia triste, sin conocer nunca el calor de unos padres.","story.map9-dungeon2.027":"Por eso a ti, que fuiste acogido por esos viejos irresponsables...","story.map9-dungeon2.028":"...yo, una diosa compasiva, te contaré la verdad.","story.map9-dungeon2.029":"¡Déjate de tonterías!","story.map9-dungeon2.030":"¡¿Qué sabrás tú del Anciano Grahdens?!","story.map9-dungeon2.031":"Como uno de los Invocadores Ancianos, siempre estaba muy ocupado...","story.map9-dungeon2.032":"...¡Pero siempre se preocupó por mí!","story.map9-dungeon2.033":"¡No se parece en nada a la persona que describes, discípula de un Dios Caído!","story.map9-dungeon2.034":"Eres tan hábil con las palabras como Grahdens. ","story.map9-dungeon2.035":"Parece que te lavaron bien el cerebro. ","story.map9-dungeon2.036":"¡Cállate! <wait=40>¡No dejaré que digas ni una palabra más contra él!","story.map9-dungeon2.037":"Eres un idiota ignorante y necio.","story.map9-dungeon2.038":"Yo te mostraré el camino.","story.map9-dungeon2.039":"Te esperaré en las Ruinas de Azura, un poco más adelante. ","story.map9-dungeon2.040":"Ven solo si quieres conocer la verdad.","story.map9-dungeon2.041":"<rep_handlename>, <wait=40>se lo debo todo al Anciano Grahdens.","story.map9-dungeon2.042":"Puede que sea un poco raro, ¡pero es una persona de confianza y lo aprecio muchísimo!","story.map9-dungeon2.043":"No puedo perdonar lo que ha dicho de él. ","story.map9-dungeon2.044":"Lo siento, pero vas a tener que seguir sin mí.","story.map9-dungeon2.045":"Voy a las Ruinas de Azura a enfrentarme a ella.","story.map9-dungeon2.046":"¡Te dejo a Zevalhua a ti!","story.map9-dungeon2.047":"¡Te lo ruego, <rep_handlename>, <wait=20>por favor!","story.map9-dungeon3.001":"¡<rep_handlename>!","story.map9-dungeon3.002":"¿Has visto a Karl?","story.map9-dungeon3.003":"Me dijo que me adelantara cuando estábamos en Khelne, <wait=20>así que lo hice, pero...","story.map9-dungeon3.004":"Parecía tranquilo, <wait=20>pero creo que en realidad estaba muy alterado. ","story.map9-dungeon3.005":"La verdad es que nunca lo había visto tan alterado.","story.map9-dungeon3.006":"¿Eh? <wait=40>¿Apareció una discípula de Zevalhua hablando de él y de Lord Grahdens?","story.map9-dungeon3.007":"Ya veo.","story.map9-dungeon3.008":"Lord Grahdens es una persona muy importante para Karl.","story.map9-dungeon3.009":"Sois amigos desde niños, ¿verdad? <wait=40>Conoces toda la historia, ¿no?","story.map9-dungeon3.010":"Aun así, <wait=40>a Karl no le gusta nada hablar de sí mismo, ¿verdad?...","story.map9-dungeon3.011":"Si nos contara lo que pasa, <wait=20>quizá podríamos ayudarle.","story.map9-dungeon3.012":"En fin, <wait=20>¡démonos prisa en llegar a las Ruinas de Azura!","story.map9-dungeon3.013":"Seguro que Karl está bien, pero no puedo evitar preocuparme.","story.map9-dungeon3.014":"Eres bastante considerada <wait=40>para el gusano que eres.","story.map9-dungeon3.015":"Él ya es nuestro.","story.map9-dungeon3.016":"No volverá más con vosotros. ","story.map9-dungeon3.017":"¡Así que tú eres Mare!","story.map9-dungeon3.018":"Humanos necios. <wait=40>¿Tenéis miedo de ver la verdad?","story.map9-dungeon3.019":"Si es así, deberíais venir también.","story.map9-dungeon3.020":"Deberíais verlo ahora que ha aceptado la verdad.","story.map9-dungeon3.021":"¡Ya basta!","story.map9-dungeon3.022":"¡Tilith!","story.map9-dungeon3.023":"Jeje, <wait=20>es la primera vez que me llamas por mi nombre.","story.map9-dungeon3.024":"¡T-<wait=20>Tonta! <wait=40>¡No es momento para eso!","story.map9-dungeon3.025":"Tienes razón. <wait=20>Tenemos que hacer algo con Mare.","story.map9-dungeon3.026":"¿Qué asunto tiene conmigo una diosa de bajo rango como tú?","story.map9-dungeon3.027":"¡Qué mala!","story.map9-dungeon3.028":"¡Soy la maravillosa discípula de Lord Lucius, que lo sepas!","story.map9-dungeon3.029":"Una cosa más, Seria. <wait=20>No te dejes engañar.","story.map9-dungeon3.030":"A Mare se le da bien confundir el corazón de los demás. ","story.map9-dungeon3.031":"Hay muy poca verdad en lo que dice.","story.map9-dungeon3.032":"¿Eres capaz de decidir qué es verdad y qué no?","story.map9-dungeon3.033":"Tú, <wait=20>que sigues ciegamente cada palabra de Lucius, <wait=20>prestando tus poderes a los humanos y demás.","story.map9-dungeon3.034":"¿Estás diciendo que Lord Lucius se equivoca?","story.map9-dungeon3.035":"Da igual. <wait=40>No se puede esperar otra cosa tratando con deidades tan necias. ","story.map9-dungeon3.036":"Hablo de ti, que lo sepas.","story.map9-dungeon3.037":"Si quieres conocer la verdad, solo tienes que creer lo que yo digo.","story.map9-dungeon3.038":"Y así podrás volver a ver a ese hombre. ","story.map9-dungeon3.039":"¡Espera un momento!","story.map9-dungeon3.040":"¡Jo! <wait=40>¡Es tan desagradable como me habían dicho!","story.map9-dungeon3.041":"¡Seria! <wait=20>¡Seguro que Karl está bien!","story.map9-dungeon3.042":"¡Así que no hagas ninguna locura!","story.map9-dungeon3.043":"Lo sé. <wait=40>Ya estoy bien.","story.map9-dungeon3.044":"Pero aun así, me preocupa Karl.","story.map9-dungeon3.045":"Sé que podría ser una trampa...","story.map9-dungeon3.046":"...pero seguro que Karl ya va de camino hacia allí.","story.map9-dungeon3.047":"<rep_handlename>, quiero que armes todo el jaleo que puedas por aquí.","story.map9-dungeon3.048":"Necesitaré una distracción si quiero llegar rápido hasta Karl. ","story.map9-dungeon3.049":"Sí, <wait=20>¡la verdad es que se te ve bien!","story.map9-dungeon3.050":"¡Hasta esa forma de hacerte la dura con <rep_handlename> te queda genial!","story.map9-dungeon3.051":"¡No me estoy haciendo nada!","story.map9-dungeon3.052":"*Suspiro* <wait=40>En fin, basta de eso.","story.map9-dungeon3.053":"Tilith, <wait=20>protege a <rep_handlename> por mí.","story.map9-dungeon3.054":"Quién sabe lo que intentará esa discípula, Mare.","story.map9-dungeon3.055":"No creo que deje en paz a alguien que ya ha derrotado a dos de los Cuatro Dioses Caídos.","story.map9-dungeon3.056":"Entendido. <wait=40>Pero, <wait=20>por favor, no hagas ninguna imprudencia.","story.map9-dungeon3.057":"No te preocupes por mí.","story.map9-dungeon3.058":"No soy tan débil como para que una diosa necia como tú tenga que preocuparse por mí.","story.map9-dungeon3.059":"¡Tan poco modesta como siempre, Seria!","story.map9-dungeon3.060":"Jeje, <wait=40>en fin, me voy.","story.map9-dungeon3.061":"<rep_handlename>, <wait=40>tú también cuídate, ¿vale?","story.map9-dungeon4.001":"<rep_handlename>...","story.map9-dungeon4.002":"Lo siento...","story.map9-dungeon4.003":"Mare...<wait=20> Nos engañó...","story.map9-dungeon4.004":"¡Seria! <wait=40>¿Estás bien?","story.map9-dungeon4.005":"Estoy...<wait=40>bien...","story.map9-dungeon4.006":"Pero...<wait=20>Karl...","story.map9-dungeon4.007":"¡No te esfuerces!","story.map9-dungeon4.008":"Mare...<wait=20>y Karl estaban...<wait=20>igualados...","story.map9-dungeon4.009":"Pensé en intentar ayudar...","story.map9-dungeon4.010":"Pero <wait=40>parece que eso era...<wait=20>justo lo que ella quería...","story.map9-dungeon4.011":"En cuanto me centré en ella...","story.map9-dungeon4.012":"Llamó a sus esbirros, que estaban escondidos. <wait=20>Vinieron todos a por mí a la vez...","story.map9-dungeon4.013":"Y justo cuando intentaba esquivar sus ataques...<wait=20>Mare me atacó por la espalda...","story.map9-dungeon4.014":"Karl...<wait=20>me protegió <wait=20>de su ataque...","story.map9-dungeon4.015":"Luego, <wait=20>mientras intentaba proteger a Karl después de que cayera, <wait=20>pasó esto...","story.map9-dungeon4.016":"Seria...","story.map9-dungeon4.017":"Me dijo...","story.map9-dungeon4.018":"\\"Te dejo como mensaje para <rep_handlename>...","story.map9-dungeon4.019":"...Es la única razón por la que te dejo vivir.\\"","story.map9-dungeon4.020":"¡Qué necia he sido!","story.map9-dungeon4.021":"No solo caí en su trampa, sino que encima pasa esto. <wait=20>¿Cómo voy a vivir con semejante vergüenza? ","story.map9-dungeon4.022":"Aun así, me alegra oír eso.","story.map9-dungeon4.023":"¡¿Qué te alegra oír?!","story.map9-dungeon4.024":"Estás viva, ¿no? <wait=20>Me alegra que sigas aquí.","story.map9-dungeon4.025":"Tilith...","story.map9-dungeon4.026":"Y si capturaron a Karl, <wait=20>¡eso significa que también sigue vivo!","story.map9-dungeon4.027":"¡Seguro que mi <rep_handlename> puede salvarlo!","story.map9-dungeon4.028":"No me gusta que digas que <rep_handlename> es tuyo, <wait=20>ni lo ciegamente que confías...","story.map9-dungeon4.029":"Pero...<wait=20>tienes razón...","story.map9-dungeon4.030":"Parece que tienen a Karl retenido en un lugar llamado la Torre Blanca. ","story.map9-dungeon4.031":"Mare dijo que te estaría esperando allí.","story.map9-dungeon4.032":"Sin duda es una trampa.","story.map9-dungeon4.033":"Pero aun así, te ruego que lo intentes.","story.map9-dungeon4.034":"<size=20><rep_handlename>, <wait=40>¡salva a Karl!</size>","story.map9-dungeon4.035":"Hum, <wait=20>¿qué es eso de asentir y hacerte el interesante?","story.map9-dungeon4.036":"Irías a salvarlo aunque yo no dijera nada, ¿verdad?","story.map9-dungeon4.037":"Ngh...","story.map9-dungeon4.038":"¡Seria! <wait=20>¡No te esfuerces!","story.map9-dungeon4.039":"¡<rep_handlename>! <wait=40>¡Deja a Seria en mis manos!","story.map9-dungeon4.040":"La llevaré sana y salva a Elgaia. ","story.map9-dungeon4.041":"Así que, por favor, <rep_handlename>, <wait=20>ve a rescatar a Karl.","story.map9-dungeon4.042":"Seria y yo <wait=20>creemos en ti, <rep_handlename>.","story.map9-dungeon4.043":"Yo no es que crea en ti...","story.map9-dungeon4.044":"Seria, <wait=20>tranquila.","story.map9-dungeon4.045":"¡Mi <rep_handlename> es el más fuerte de todos!","story.map9-dungeon4.046":"¿A quién llamas tuyo?","story.map9-dungeon4.047":"Bah, <wait=40>da igual...","story.map9-dungeon4.048":"<rep_handlename>...","story.map9-dungeon4.049":"Por favor...<wait=40>trae a Karl de vuelta...","story.map9-dungeon5.001":"<rep_handlename>. <wait=40>Te estaba esperando.","story.map9-dungeon5.002":"Pensé que pasarías por aquí de camino a la Torre Blanca.","story.map9-dungeon5.003":"La Torre Blanca está al otro lado de las Montañas de Ryvern, <wait=20>justo al salir de la cueva. ","story.map9-dungeon5.004":"Dudo que sea fácil atravesarlas, incluso con tu habilidad.","story.map9-dungeon5.005":"Sin embargo, <wait=20>no temas. ","story.map9-dungeon5.006":"Yo salvaré al joven Karl.","story.map9-dungeon5.007":"Al fin y al cabo, es mi querido hijo. ","story.map9-dungeon5.008":"Jo, jo, jo. <wait=40>¿A qué viene esa cara de duda?","story.map9-dungeon5.009":"No tengo ni idea de lo que dijo esa discípula, Mare.","story.map9-dungeon5.010":"Pero fui yo quien recogió a aquel bebé abandonado y lo crio como si fuera mío.","story.map9-dungeon5.011":"Dicho esto, <wait=20>es cierto que al final lo dejé al cuidado de un conocido de confianza. ","story.map9-dungeon5.012":"La vida de un Invocador Anciano es demasiado ajetreada.","story.map9-dungeon5.013":"Pero el resto de la historia ya lo conoces, ¿no?","story.map9-dungeon5.014":"Te agradezco que siempre jugaras con Karl cuando erais niños. ","story.map9-dungeon5.015":"Jo, jo, jo.","story.map9-dungeon5.016":"Sin embargo, por muy ocupado que estuviera...","story.map9-dungeon5.017":"...nunca me habría limitado a dejarlo con otra persona.","story.map9-dungeon5.018":"De vez en cuando me escapaba sin que nadie se diera cuenta para ir a ver cómo estaba. ","story.map9-dungeon5.019":"Me habría metido en un buen lío si alguien hubiera sabido que yo, un Invocador Anciano, tenía un hijo.","story.map9-dungeon5.020":"Sin embargo, <wait=20>pese a tener que hacerlo a escondidas, él me aceptó igualmente.","story.map9-dungeon5.021":"Jo, jo, jo. <wait=40>Qué nostalgia.","story.map9-dungeon5.022":"Bueno, <wait=20>supongo que debería ponerme en marcha.","story.map9-dungeon5.023":"Recuperar a un hijo perdido es responsabilidad de sus padres.","story.map9-dungeon5.024":"Y además, <wait=20>debo castigar a quien se ha atrevido a engañar a mi querido hijo.","story.map9-dungeon5.025":"Jo, jo, jo. <wait=20>No te preocupes.","story.map9-dungeon5.026":"Puede que me haya hecho mayor, <wait=20>pero seguramente sigo siendo muchas veces más fuerte que cualquiera de vosotros.","story.map9-dungeon5.027":"Además, <wait=20>aunque me pasara algo...","story.map9-dungeon5.028":"...ya les he pedido a los demás Invocadores Ancianos que cuiden de vosotros. ","story.map9-dungeon5.029":"Jo, jo, jo. <wait=40>¿Quizá soy demasiado precavido?","story.map9-dungeon5.030":"No temas y dirígete hacia Zevalhua.","story.map9-dungeon5.031":"Seguro que Karl tampoco quiere retenerte.","story.map9-dungeon5.032":"Pero aun así, piensas ir a la Torre Blanca, ¿verdad?","story.map9-dungeon5.033":"Karl tiene muy buenos amigos. ","story.map9-dungeon5.034":"Bueno, entonces, <wait=20>salvaré a Karl y te esperaré en la Torre Blanca. ","story.map9-dungeon5.035":"Jo, jo, jo.","story.map9-dungeon6.001":"Parece que ya solo queda uno. ","story.map9-dungeon6.002":"Parece que los humanos sois de verdad unos seres necios. ","story.map9-dungeon6.003":"Te destruiré igual que hice con el resto de esos guerreros necios.","story.map9-dungeon6.004":"<size=20>¡No lo permitiré!</size>","story.map9-dungeon6.005":"¡Yo protegeré a <rep_handlename>!","story.map9-dungeon6.006":"Eres tú...","story.map9-dungeon6.007":"Has vuelto mucho antes de lo que pensaba.","story.map9-dungeon6.008":"Te llamaría necia, <wait=20>pero ¿qué otra cosa podía esperar de una discípula de Lucius?","story.map9-dungeon6.009":"En fin...","story.map9-dungeon6.010":"Invocador, <wait=40>te estaré esperando en la Torre Blanca.","story.map9-dungeon6.011":"Y tu amigo estará conmigo.","story.map9-dungeon6.012":"<rep_handlename>, ¿estás bien?","story.map9-dungeon6.013":"Si te preocupa Seria, no hace falta.","story.map9-dungeon6.014":"La llevé sana y salva a Elgaia, y ahora descansa tranquila en el Salón de Invocadores. ","story.map9-dungeon6.015":"Así que <wait=20>¡vamos a salvar a Karl juntos!","story.map9-dungeon6.016":"Tú y yo podemos hacerlo, <wait=20>¡da igual cuántas trampas ponga Mare!","story.map9-dungeon6.017":"¡No hay enemigo que no podamos vencer mientras estemos juntos!","story.map9-dungeon6.018":"¡Karl! ¡Aguanta un poco más!","story.map9-dungeon7.001":"Aunque haya tanta luz, este lugar me pone los pelos de punta.","story.map9-dungeon7.002":"¿Será otra de las trampas de Mare?","story.map9-dungeon7.003":"No necesito malgastar ninguna de mis valiosas trampas con vosotros.","story.map9-dungeon7.004":"¡Es la voz de Mare!","story.map9-dungeon7.005":"Os he preparado un rival.","story.map9-dungeon7.006":"Granvalm, guardián de esta torre. <wait=40>¡Destruye a estos intrusos!","story.map9-dungeon7.007":"<size=20>¡Kyaaaah! <wait=40>¡Mira ese dragón!</size>","story.map9-dungeon7.008":"Debería ser el rival perfecto para un par de necios como vosotros.","story.map9-dungeon7.009":"¡Espera!","story.map9-dungeon7.010":"¡Ahora sí que me he enfadado! <wait=40><rep_handlename>, ¡apártate!","story.map9-dungeon7.011":"Ja, ja, ja...","story.map9-dungeon7.012":"Han huido...","story.map9-dungeon7.013":"Pero <wait=20>parecía que ese dragón volvía corriendo a proteger algo...","story.map9-dungeon7.014":"Quizá quería asegurarse de que Karl no escapara.","story.map9-dungeon7.015":"¡<rep_handlename>!","story.map9-dungeon7.016":"¡Seguro que es eso!","story.map9-dungeon7.017":"¡Persigue a ese dragón, yo estaré bien!","story.map9-dungeon7.018":"¡Solo necesito descansar aquí un momento!","story.map9-dungeon7.019":"Tenemos que estar a la altura de la confianza que Seria ha puesto en nosotros.","story.map9-dungeon7.020":"¡Para mi <rep_handlename> no será ningún problema!","story.map9-dungeon7.021":"¡Cumple tu promesa a Seria y rescata a Karl!","story.map9-ending.001":"Invocador. <wait=40>Parece que sigues en pie.","story.map9-ending.002":"Tranquilo. <wait=40>Me aseguraré de que tu final sea rápido e indoloro.","story.map9-ending.003":"Después de ti, no quedará nadie que amenace a Lord Zevalhua. ","story.map9-ending.004":"¿A qué viene esa cara de sorpresa?","story.map9-ending.005":"Iba a por ti desde el principio.","story.map9-ending.006":"Tú, el Invocador elegido por Lucius.","story.map9-ending.007":"Ahora que he acabado con todos los que una vez te protegieron...","story.map9-ending.008":"...no queda nadie que pueda salvarte.","story.map9-ending.009":"Incluso el viejo cayó luchando por salvar a alguien que ni siquiera estaba aquí.","story.map9-ending.010":"Encima, <wait=20>el poder de esa diosa necia que puso su fe en ti también se ha agotado.","story.map9-ending.011":"Da igual cuántos discípulos envíe Lucius.","story.map9-ending.012":"Seguro que entienden que, débiles como son, el dragón blanco los dejará inmóviles sin más.","story.map9-ending.013":"Se ha vuelto necio por pasar tanto tiempo rodeado de vosotros, los humanos.","story.map9-ending.014":"Los gusanos humanos sois realmente lamentables.","story.map9-ending.015":"Os emocionáis enseguida y luego actuáis por vuestra cuenta.","story.map9-ending.016":"Aun sabiendo que algo es una trampa, decís que es para salvar a vuestros amigos mientras arrastráis a otros a los problemas con vosotros. ","story.map9-ending.017":"Actuar solo cuando se tiene tanta responsabilidad solo conduce al fracaso. ","story.map9-ending.018":"Además, <wait=20>quienes tienen grandes metas y se centran en las pequeñas acaban perdiéndolo todo.","story.map9-ending.019":"Qué forma tan necia de vivir.","story.map9-ending.020":"Seguro que tú no eres diferente.","story.map9-ending.021":"Invocador...","story.map9-ending.022":"Hum, <wait=40>me he aburrido.","story.map9-ending.023":"Hablé pensando que quizá opondrías algo de resistencia, pero parece que ya estás al límite.","story.map9-ending.024":"Está bien. <wait=40>¡Parece que tendré que acabar contigo aquí mismo!","story.map9-ending.025":"<size=20>¡Detente ahí mismo!</size>","story.map9-ending.026":"......","story.map9-ending.027":"......","story.map9-ending.028":"Parece que aún te quedan algunos aliados.","story.map9-ending.029":"Pero da igual.","story.map9-ending.030":"El hombre que buscas está retenido en la capital de Agni. ","story.map9-ending.031":"Más vale que lo persigas si quieres salvarlo.","story.map9-ending.032":"Y no tienes tiempo de esperar a que tus amigos se recuperen.","story.map9-ending.033":"Si lo haces, llegarás demasiado tarde para salvarlo.","story.map9-ending.034":"......","story.map9-ending.035":"Oye, <rep_handlename>, <wait=20>¡no te quedes ahí parado!","story.map9-ending.036":"Ya hablaremos luego. <wait=40>Por ahora, deberíamos ir hacia la capital de Agni.","story.map9-ending.037":"Tengo algo que contarte cuando lleguemos.","story.map9-ending.038":"¡Deberías estarme agradecido!","story.map9-ending.039":"<size=20>¡Ja, ja, ja, ja!</size>","story.map9-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Soy Lucius...<br><wait=40>Dios de esta Puerta...","story.map9-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>La crisis que provocaron los Cuatro Dioses Caídos<wait=40> aún persiste...","story.map9-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Usa mi poder <wait=40>y adéntrate en nuevas tierras...","story.map9-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Para traer una nueva esperanza a este mundo sin orden...","story.map9-open.005":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Debes tener fe en tu poder <wait=20>y seguir avanzando...","story.map9-open.006":"¡<rep_handlename>! <wait=40>¡Siento haberte hecho esperar!","story.map9-open.007":"Pero como siempre soy yo la que te espera, <rep_handlename>...","story.map9-open.008":"...¡esta vez pensé en hacerte esperar a ti!","story.map9-open.009":"¿Cómo? <wait=20>¿Dices que no has esperado tanto?","story.map9-open.010":"¡Eso no es justo!","story.map9-open.011":"¡Esperaba que al menos sudaras un poco esperándome!","story.map9-open.012":"¡Pero da igual! <wait=40>¡Lo importante es derrotar cuanto antes al siguiente Dios Caído!","story.map9-open.013":"¡Solo queda la mitad de los Cuatro Dioses Caídos!","story.map9-open.014":"Y el siguiente al que te enfrentarás es...","story.map9-open.015":"...el gran emperador Zevalhua, que controla la región de Agni. ","story.map9-open.016":"Dicen que se lleva mal con Afla Dilith, otro de los Dioses Caídos...","story.map9-open.017":"...pero seguro que ya se ha dado cuenta de que hemos llegado.","story.map9-open.018":"¡Seguramente intentará tendernos trampas!","story.map9-open.019":"Pero tú no caerías en ellas, ¿verdad, <rep_handlename>?","story.map9-open.020":"Muy bien, <wait=20>¡voy a ir hacia Milvana, donde nos espera Zevalhua!","story.map9-open.021":"Randall,<wait=40> capital del Imperio de Randall.","story.map9-open.022":"Castillo de Randall, sala privada de los guardaespaldas de la familia imperial, <wait=40>la Guardia Imperial.","story.map9-open.023":"*Toc* <wait=20>*toc*","story.map9-open.024":"Con permiso.","story.map9-open.025":"......","story.map9-open.026":"Los preparativos para partir hacia la región de Agni están listos. ","story.map9-open.027":"¿Ah, sí?","story.map9-open.028":"Bien, entonces pongámonos nosotros también en marcha. ","story.map9-open.029":"Hacia Grand Gaia, la tierra controlada por los dioses. ","storylog.category.10000.description":"Viajando por Grand Gaia junto a sus amigos y una poderosa diosa, un Invocador se enfrenta a demonios en feroces batallas.","storylog.category.10000.name":"Memorias de Grand Gaia","storylog.category.10100.description":"Guiado por Tilith, servidora del dios Lucius, el Invocador inicia una gran aventura. Debe derrotar a los Cuatro Dioses Caídos, empezando por Maxwell.","storylog.category.10100.name":"Mistral","storylog.category.10101.description":"Una isla habitada antaño por gigantes parece ser el próximo destino del Invocador. Sin embargo, Paris, de la Guardia Imperial, también se dirige a Cordelica...","storylog.category.10101.name":"Cordelica","storylog.category.10102.description":"El Invocador llega a la tierra que Cardes el Malévolo quiere destruir. Comienza una nueva batalla donde antaño lucharon los legendarios 4 Héroes de Palmyna.","storylog.category.10102.name":"Palmyna","storylog.category.10103.description":"Paris llega a la isla de la antigua República de La Veda en busca de una puerta de la que corren rumores, pero el Salón de Invocadores ya ha empezado a investigar.","storylog.category.10103.name":"Lizeria","storylog.category.10104.description":"Hay que acabar con Zevalhua el Supremo antes de que lo destruya todo. Se dice que está enfrentado con Afla Dilith, uno de los Cuatro Dioses Caídos.","storylog.category.10104.name":"Región de Agni","storylog.category.11001.description":"Mientras Karl persigue al demonio Graham, el Invocador busca desafiar a Abaddon, discípulo de Maxwell. ¿Pero de verdad se puede derrotar a Abaddon?","storylog.category.11001.name":"Morgan","storylog.category.11002.description":"El nuevo destino es la tierra bajo el dominio de la Creadora Maxwell. El objetivo: llegar con Tilith a su bastión, el Palacio de St. Lamia.","storylog.category.11002.name":"St. Lamia","storylog.category.11010.description":"El Invocador llega a donde antaño prosperó el gran Imperio de Amdahl. Tilith espera que este viaje acabe con la derrota de Cardes el Malévolo.","storylog.category.11010.name":"Amdahl","storylog.category.11011.description":"Según Tilith, esta tierra fue testigo de una guerra civil entre humanos. En plena tierra salvaje estallan intensas batallas.","storylog.category.11011.name":"Encervis","storylog.category.11040.description":"Zevalhua el Supremo es el nuevo objetivo. Tilith comenta que teme que se esté tramando algo.","storylog.category.11040.name":"Ryvern","storylog.category.11041.description":"El Invocador visita la tierra donde antaño se alzaba un imperio. Grahdens os ha confiado a ti y a Lugina el rescate de Karl, pero...","storylog.category.11041.name":"Agni","storylog.category.11042.description":"Al fin en la fortaleza de Zevalhua, este antiguo campo de batalla da paso a una nueva lucha para rescatar a Grahdens, que ha sido capturado.","storylog.category.11042.name":"Mirvana","storylog.category.20000.description":"Piden al Invocador que se aventure en una tierra misteriosa recién descubierta. Pero los enemigos que allí aguardan son mucho más fuertes de lo esperado...","storylog.category.20000.name":"Una nueva región","storylog.scenario.10001.description":"Tilith explica la situación de Grand Gaia en la Cueva de las Llamas. El Invocador debe emprender un largo viaje para derrotar a los Cuatro Dioses Caídos...","storylog.scenario.10001.title":"Comienza el viaje","storylog.scenario.10002.description":"En el Campo Nevado de Egor, Tilith explica la importancia de los elementos de las unidades. El trueno vence al agua, etc. Algo a tener en cuenta en futuros combates.","storylog.scenario.10002.title":"Afinidad de unidades","storylog.scenario.10003.description":"El Invocador llega al Bosque de Bestias, donde los enemigos cazan animales salvajes para comer. Aquí también se explica con detalle el uso de las esferas.","storylog.scenario.10003.title":"El equipo importa","storylog.scenario.10004.description":"La humedad de los Humedales de Magutagal pone de mal humor a Tilith, aunque explica las chispas que generan varios ataques sincronizados.","storylog.scenario.10004.title":"Técnica de combate","storylog.scenario.10005.description":"A Tilith le impresiona que el Invocador haya llegado sano y salvo a los Restos de Mirza. Como premio, le explica las ventajas de las Habilidades de líder.","storylog.scenario.10005.title":"Liderazgo","storylog.scenario.10006.description":"Se rumorea que un misterioso espadachín merodea por el Nido de Monstruos. Aunque Tilith jura que no tiene miedo, parece bastante asustada...","storylog.scenario.10006.title":"¡No tengo miedo!","storylog.scenario.10007.description":"En la Torre de Mistral, la liberación de toda la región está a un paso. Sin embargo, la Creadora Maxwell ha creado un rival aterrador...","storylog.scenario.10007.title":"Mistral liberada","storylog.scenario.10008.description":"El Invocador derrota al Juggernaut y se gana los elogios de Tilith. Lucius abrirá ahora el camino hacia la tierra desconocida de Morgan.","storylog.scenario.10008.title":"Hacia nuevas tierras","storylog.scenario.10009.description":"Buscando a Tilith, nuestro Invocador entra en el Desierto de Kagan. Un encuentro casual con Karl revela que persigue al demonio Graham.","storylog.scenario.10009.title":"Reencuentro con Karl","storylog.scenario.10010.description":"En Playa Brisa, Tilith oye hablar de una espadachina bella pero indiferente. Aun así, está segura de ser mucho más guapa que esa belleza.","storylog.scenario.10010.title":"La bella espadachina","storylog.scenario.10011.description":"Karl se hiere persiguiendo a Graham. Dicen que el Bosque Nocturno es territorio de un subordinado de Graham que ataca a muchos Invocadores.","storylog.scenario.10011.title":"El subordinado de Graham","storylog.scenario.10012.description":"Karl logra expulsar a Graham del Bosque Nocturno. Sin ningún sitio adonde huir, es hora de zanjarlo todo en los Páramos de Asekutt.","storylog.scenario.10012.title":"La persecución de Karl","storylog.scenario.10013.description":"Seria, de los Cazademonios, aparece en el Santuario de Lystia. Según ella, Graham es uno de los subordinados más preciados de Abaddon.","storylog.scenario.10013.title":"Abaddon & Graham","storylog.scenario.10014.description":"Seria se pone hostil con el Invocador. Aunque Karl quiere seguir hacia la Catedral Destruida como equipo de tres, Seria no lo pone fácil...","storylog.scenario.10014.title":"Rechazo","storylog.scenario.10015.description":"Tras llegar por fin al bastión de Abaddon en la Torre de Morgan, Karl y Seria contienen a los enemigos para que el Invocador pueda avanzar.","storylog.scenario.10015.title":"Por mis compañeros","storylog.scenario.10016.description":"Abaddon ha sido derrotado. Tras reencontrarse con Karl y separarse de nuevo, Tilith y el Invocador parten hacia St. Lamia en busca de Maxwell.","storylog.scenario.10016.title":"Hacia la base enemiga","storylog.scenario.10017.description":"En el Volcán Eldent, Tilith advierte que descuidar las obligaciones es inaceptable. Dice que nunca ha holgazaneado en su trabajo, pero...","storylog.scenario.10017.title":"¡Nada de holgazanear!","storylog.scenario.10018.description":"Aunque Tilith intenta explicar la historia del Monte Sagrado Craylia, no parece estar muy bien. Al parecer, se ha resfriado...","storylog.scenario.10018.title":"Un mal presagio","storylog.scenario.10019.description":"En el Bosque de Sangre, Tilith hace lo posible por fingir que su estado no empeora. Pero está claro que le está pasando factura...","storylog.scenario.10019.title":"Fingiendo","storylog.scenario.10020.description":"En el Monte Wistorea, Tilith confiesa por fin su mal estado físico. La maldición de Maxwell la afecta más a medida que se acerca al Palacio de St. Lamia.","storylog.scenario.10020.title":"La maldición","storylog.scenario.10021.description":"En el Santuario Recóndito, Tilith se desploma. Tras confiársela a Seria, el Invocador parte solo al Palacio de St. Lamia para acabar con la maldición.","storylog.scenario.10021.title":"Una promesa","storylog.scenario.10022.description":"Tras ser rescatado por Karl, el Invocador va a por Maxwell en el Palacio de St. Lamia. ¿Podrá salvarse Tilith de esta terrible maldición?","storylog.scenario.10022.title":"Algo que proteger","storylog.scenario.10023.description":"Rota la maldición, Tilith vuelve a ser la de siempre, pero acaba enzarzada en una dramática discusión con Seria...","storylog.scenario.10023.title":"La caída de la Creadora","storylog.scenario.10100.description":"Cuando Eriole se entera de que el Salón de Invocadores de Akras ha abierto la región sur de Mistral, envía a Paris a Cordelica...","storylog.scenario.10100.title":"Comienza la conspiración","storylog.scenario.10101.description":"En las Cuevas de Greskya surge un encuentro con Lugina, de los Cazademonios. Como no respeta al Ejército Regular, exige que el Invocador se marche.","storylog.scenario.10101.title":"Lugina el Cazademonios","storylog.scenario.10102.description":"En las Cataratas de Ignia, Lugina explica cómo el Imperio de Randall y el Salón de Invocadores de Akras influyen en la vida de Elgaia.","storylog.scenario.10102.title":"Asuntos de Elgaia","storylog.scenario.10103.description":"En el Bosque de Lomass, Lugina explica cómo funciona el Ejército de Invocadores. Y, como miembro de la élite, exige que el Invocador respete su autoridad.","storylog.scenario.10103.title":"El Ejército de Invocadores","storylog.scenario.10104.description":"Paris aparece en la Fortaleza de Valtan. Pide al Invocador que colabore en la exploración de Cordelica, pero...","storylog.scenario.10104.title":"La petición de Paris","storylog.scenario.10105.description":"Rumbo a la Torre de la Luz, Paris comenta que el Invocador es amigo de Karl, pero Lugina no se lo cree. No parece que Karl le caiga bien.","storylog.scenario.10105.title":"¡Ese engreído!","storylog.scenario.10106.description":"En la Mina de Cordelica, Paris explica que hace mucho una raza de gigantes habitó la isla. Parece que el dios de los gigantes también ha despertado.","storylog.scenario.10106.title":"Un dios gigante","storylog.scenario.10107.description":"Mientras Lugina parte a derrotar al dios gigante Grantos en las Ruinas del Gigante, Paris pide al Invocador que demuestre lo que es el verdadero poder.","storylog.scenario.10107.title":"Lugina entusiasta","storylog.scenario.10108.description":"Al saber que el Invocador ha derrotado a Grantos, Eriole ríe y proclama que el mundo va en la dirección correcta...","storylog.scenario.10108.title":"Los motivos de Eriole","storylog.scenario.10200.description":"Lucius guía al Invocador al archipiélago de Palmyna, mientras informan a cierto hombre de Randall de que la barrera sobre esas islas ha desaparecido.","storylog.scenario.10200.title":"Supervisor de caballeros","storylog.scenario.10201.description":"El siguiente objetivo es Cardes el Malévolo, otro de los Cuatro Dioses Caídos. En la Aldea Julep oyes que la mitad de su poder sigue sellada.","storylog.scenario.10201.title":"Cardes el Malévolo","storylog.scenario.10202.description":"Tilith asegura no tener miedo a bordo del Barco Fantasma Legnia. Aun así, da algo de información sobre Palmyna, donde Cardes está sellado...","storylog.scenario.10202.title":"Rumbo a Palmyna","storylog.scenario.10203.description":"Un hombre extraño ataca de repente al Invocador en las Llanuras de Elios. Pero su presencia desaparece tan rápido como apareció.","storylog.scenario.10203.title":"Un hombre misterioso","storylog.scenario.10204.description":"Un encuentro con Seria y Karl en las Minas de Saji revela que siguen tras Graham. Karl advierte al Invocador sobre alguien llamado Zebra.","storylog.scenario.10204.title":"Se llama Zebra","storylog.scenario.10205.description":"Tilith y su Invocador se topan con \\"Elder Grah\\" en el Templo de Lamellia. El anciano dice investigar el folclore ligado a los Cuatro Dioses Caídos.","storylog.scenario.10205.title":"Un anciano misterioso","storylog.scenario.10206.description":"Karl y Seria acorralan a Graham en el Pueblo Fantasma Edila, pero una fuerza desconocida y poderosa los derriba y Graham escapa.","storylog.scenario.10206.title":"Fuerza desconocida","storylog.scenario.10207.description":"Elder Grah aparece en el Castillo de Amdahl y habla del espíritu vengativo del último emperador de Amdahl, que al parecer aún ronda el castillo.","storylog.scenario.10207.title":"El último emperador de Amdahl","storylog.scenario.10208.description":"A Elder Grah le impresiona que el Invocador haya vencido al espíritu maligno. Seria llega corriendo y parece que de algún modo conoce al anciano.","storylog.scenario.10208.title":"Seria & Elder Grah","storylog.scenario.10209.description":"Guiado por Lucius, el Invocador llega a Encervis. Según Tilith, hace mucho tiempo una guerra civil entre humanos asoló esta tierra.","storylog.scenario.10209.title":"Ruinas del pasado","storylog.scenario.10210.description":"Al llegar al Cráter de Elsta, Tilith cuenta al Invocador lo mucho que ha trabajado hasta ahora. Pero, por algún motivo, sus palabras parecen dudosas...","storylog.scenario.10210.title":"Tilith la trabajadora","storylog.scenario.10211.description":"Zebra ataca de repente en el Lago Aldela, pero la ayuda de Elder Grah evita daños graves. Este poderoso enemigo parece vivir en una fortaleza flotante.","storylog.scenario.10211.title":"La fortaleza celeste restaurada","storylog.scenario.10212.description":"Elder Grah relata la historia de Amdahl mientras recorre el Castillo Avenia. Pide al Invocador que destruya la fortaleza celeste, pero a Tilith le da igual...","storylog.scenario.10212.title":"La historia de Amdahl","storylog.scenario.10213.description":"Zebra y la Figura Oscura están en el Barranco de Gadillian hablando de cómo encargarse del Invocador. ¿Qué relación tendrán...?","storylog.scenario.10213.title":"Zebra y una Figura Oscura","storylog.scenario.10214.description":"Seria y Karl buscan al Invocador en el Mausoleo de Alman. Ambos quieren usar su poder para ayudar a derribar la fortaleza celeste.","storylog.scenario.10214.title":"Un apoyo tranquilizador","storylog.scenario.10215.description":"En la Tierra de los Muertos, Tilith revela que el nombre oficial de la fortaleza celeste es Solaris. Piensa usar sus poderes para ayudar a infiltrarse.","storylog.scenario.10215.title":"Infiltración en la fortaleza","storylog.scenario.10216.description":"Gracias a los poderes de Tilith, la infiltración en la Fortaleza Celeste Solaris es un éxito. Zebra ve la ocasión de atacar a la agotada diosa.","storylog.scenario.10216.title":"Zebra vs. Tilith","storylog.scenario.10217.description":"Zebra por fin ha sido derrotado. Sin embargo, destruye Solaris para arrastrar consigo al Invocador. ¿Quién podrá evitar esta tragedia...?","storylog.scenario.10217.title":"Zebra & Grahdens","storylog.scenario.10218.description":"El Invocador llega a Palmyna guiado por Lucius. Aquí aún se ven con claridad los vestigios de un reino que luchó contra los dioses.","storylog.scenario.10218.title":"El campo de batalla","storylog.scenario.10219.description":"Aunque estaba en el Castillo de Obselion, Tilith corre a las Ruinas de Dejour para avisar de que el sello de Cardes empieza a debilitarse.","storylog.scenario.10219.title":"El sello se deshace","storylog.scenario.10220.description":"Grahdens se queda a solas con el Invocador en el Castillo de Obselion. Le cuenta la historia de los 4 Héroes de Palmyna que sellaron a Cardes el Malévolo.","storylog.scenario.10220.title":"Los 4 Héroes de Palmyna","storylog.scenario.10221.description":"En el Sendero Esmeralda, Seria y Karl descubren que deben viajar al mundo espiritual para derrotar a Cardes. Aunque Seria se comporta de forma rara...","storylog.scenario.10221.title":"Seria excéntrica","storylog.scenario.10222.description":"Al pasar por las Ruinas de Grandelt, Tilith revela que el cuerpo de Cardes se está desintegrando poco a poco y que sus poderes divinos se desbocan.","storylog.scenario.10222.title":"El desenfreno de los dioses","storylog.scenario.10223.description":"En el Seminario de Arlind, Grahdens expresa sus dudas sobre el pasado y los recientes movimientos de los dioses. Sus ideas parecen influir en el Invocador.","storylog.scenario.10223.title":"Las dudas de Grahdens","storylog.scenario.10224.description":"Karl y Seria acompañan al Invocador a las puertas del inframundo en el Campo de Batalla de Noera. Ambos están preocupados por Tilith.","storylog.scenario.10224.title":"La entrada al Hades","storylog.scenario.10225.description":"El Invocador y los demás se separan para buscar a Cardes en el Mundo Espiritual Palmyna. ¿Podrán derrotarlo antes de que lo destruya todo?","storylog.scenario.10225.title":"Batalla contra Cardes","storylog.scenario.10226.description":"Cuando todos intentan escapar del inframundo que se derrumba, Seria resulta herida. En esta situación desesperada, Tilith aparece para salvar el día.","storylog.scenario.10226.title":"La diosa renacida","storylog.scenario.10300.description":"Tras oír el informe de Paris, Eriole la envía a Lizeria. ¿Qué podrá estar buscando él?","storylog.scenario.10300.title":"La búsqueda","storylog.scenario.10301.description":"Lugina aparece en las Llanuras de Erinecht y afirma tener una misión mucho más importante que la del Invocador. Su actitud desafiante no ha cambiado.","storylog.scenario.10301.title":"La misión de Lugina","storylog.scenario.10302.description":"Al llegar a las Montañas de Golzo, se revela que Paris busca un poder latente en Lizeria. Y parece que Lugina va tras lo mismo.","storylog.scenario.10302.title":"Una ambición para dos","storylog.scenario.10303.description":"En el Lago Helado de Lodan, Lugina supone erróneamente que Paris ha traicionado al Invocador. Todo se aclara, pero Lugina insiste en entrenar...","storylog.scenario.10303.title":"El entrenamiento de Lugina","storylog.scenario.10304.description":"En los Pantanos Infranqueables, Paris habla de la estructura social de Elgaia. Parece que desconfía del poder del Salón de Invocadores.","storylog.scenario.10304.title":"El lado oscuro del Salón","storylog.scenario.10305.description":"En el Bosque del Relámpago Zaljiba, Paris menciona el lado oscuro del Salón de Invocadores. Luego le preguntan a Lugina al respecto, y él responde a su manera.","storylog.scenario.10305.title":"La motivación de Lugina","storylog.scenario.10306.description":"En la Ciudad Perdida La Veda, Paris comparte sus dudas sobre los dioses y habla de la inestabilidad del mundo. Quiere tomar cartas en el asunto.","storylog.scenario.10306.title":"La motivación de Paris","storylog.scenario.10307.description":"Sobre el Puente Negro, Lugina dice que aplastará a cualquiera que se interponga en su camino y hace una última confesión al Invocador antes de seguir adelante.","storylog.scenario.10307.title":"Última advertencia","storylog.scenario.10308.description":"Aunque Lugina pierde contra el Invocador, afirma que es imposible que haya fallado y sigue negando su propia derrota.","storylog.scenario.10308.title":"La derrota de Lugina","storylog.scenario.10309.description":"En la Torre de la Destrucción, una Paris herida sigue negándose a renunciar al poder latente de la región. No perdonará la intromisión del Invocador.","storylog.scenario.10309.title":"La determinación de Paris","storylog.scenario.10310.description":"Un sistema de defensa capaz de destruir Invocadores. Sin embargo, lo que Paris buscaba, que debería estar cerca, no aparece por ninguna parte...","storylog.scenario.10310.title":"Poder destructivo","storylog.scenario.10400.description":"Tilith y el Invocador parten para derrotar a Zevalhua el Supremo. Sin que lo sepan, Eriole y Paris también se dirigen a Agni...","storylog.scenario.10400.title":"Doble viaje","storylog.scenario.10401.description":"En la Hondonada de Glomore, Karl y Seria dicen que quieren ayudar a derrotar a Zevalhua mientras una misteriosa mujer los observa con desprecio desde lejos.","storylog.scenario.10401.title":"Compañeros","storylog.scenario.10402.description":"Tras llegar a la Zona Nevada de Khelne, la discípula Mare aparece de repente y le pide a Karl que vaya solo a las Ruinas de Azura para revelarle cierto secreto.","storylog.scenario.10402.title":"El pasado de Karl","storylog.scenario.10403.description":"Seria se preocupa por Karl mientras vaga por el Bosque de Stokhelna, cuando Mare reaparece para decir que Karl ha caído en sus redes...","storylog.scenario.10403.title":"La discípula Mare","storylog.scenario.10404.description":"Seria cae en la trampa de Mare en las Ruinas de Azura y resulta herida. Tilith deja el rescate de Karl en manos del Invocador mientras cuida de Seria.","storylog.scenario.10404.title":"Seria atrapada","storylog.scenario.10405.description":"Grahdens espera al Invocador en las Montañas de Ryvern y comparte sus recuerdos de Karl. Dice que se dejará capturar por Mare para liberar a Karl.","storylog.scenario.10405.title":"Grahdens y Karl","storylog.scenario.10406.description":"Mare se presenta ante el Invocador, que está solo en la Cueva del Abismo. Justo cuando se dispone a atacar, Tilith regresa y lo impide.","storylog.scenario.10406.title":"Tilith sigilosa","storylog.scenario.10407.description":"Mare lanza a Granvalm contra el Invocador en la Torre Blanca y huye. Sin embargo, Tilith no piensa dejarla escapar tan fácilmente.","storylog.scenario.10407.title":"Granvalm el Blanco","storylog.scenario.10408.description":"Mare reaparece tras la derrota de Granvalm y, en plena situación desesperada, un aliado inesperado salva el pellejo a todos...","storylog.scenario.10408.title":"Ayuda inesperada","storylog.scenario.10409.description":"Lugina salva al Invocador en Ryvern para cumplir la petición de Grahdens. También insiste en que le pidieron ayudar en el rescate de Karl.","storylog.scenario.10409.title":"Sé agradecido","storylog.scenario.10410.description":"En el Imperio de Agni, Lugina está muy entusiasmado con la misión de rescate. Dice que es la ocasión perfecta para cumplir su misión y burlarse de Karl.","storylog.scenario.10410.title":"Lugina lo da todo","storylog.scenario.10411.description":"Harto de esperar a que Mare aparezca, Lugina deja al Invocador en la Costa de Agniria y se va a buscar a Karl por su cuenta...","storylog.scenario.10411.title":"De nuevo en marcha","storylog.scenario.10412.description":"Mare por fin se deja ver en la Meseta de Granasta. Pero no está dispuesta a luchar. En su lugar, exige que el Invocador la siga para salvar a Karl.","storylog.scenario.10412.title":"Mare la embaucadora","storylog.scenario.10413.description":"Mare recuerda a cierta persona que luchó en la guerra contra los dioses mientras el angustiado Invocador la persigue hasta la Cumbre del Trueno Navara.","storylog.scenario.10413.title":"Los recuerdos de Mare","storylog.scenario.10414.description":"El Invocador avanza por la Tumba del Rey sin perder la esperanza de rescatar a Karl. Mare no entiende tanta obstinación, y eso la lleva por fin a atacar.","storylog.scenario.10414.title":"Fuerzas opuestas","storylog.scenario.10415.description":"Justo cuando Mare está a punto de asestar el golpe final en la Cala de Lognea, Seria, que supuestamente estaba gravemente herida, irrumpe para salvar al Invocador.","storylog.scenario.10415.title":"Contraataque","storylog.scenario.10416.description":"Una horda de enemigos aparece en el Santuario Oceánico Albina y pone en aprietos a Seria y al Invocador. Sin embargo, Lugina llega justo a tiempo con Karl liberado.","storylog.scenario.10416.title":"El rescate","storylog.scenario.10417.description":"Mare por fin es derrotada por el Invocador, pero de repente aparece Paris para informar de que Grahdens ha sido capturado.","storylog.scenario.10417.title":"Grahdens capturado","storylog.scenario.10418.description":"El Invocador por fin pisa Mirvana. Tilith explica que aquí se libró la batalla más sangrienta de la gran guerra contra los dioses.","storylog.scenario.10418.title":"Antiguo campo de batalla","storylog.scenario.10419.description":"Zevalhua el Supremo ha capturado a Grahdens. Para salvarlo, el Invocador y los demás se dividen en grupos en la Cueva de la Oscuridad.","storylog.scenario.10419.title":"Grupos de búsqueda","storylog.scenario.10420.description":"En el Campo Nevado de Arvest, Paris se pregunta con recelo por qué los dioses han tomado prisionero a Grahdens en lugar de matarlo sin más...","storylog.scenario.10420.title":"Actos sospechosos","storylog.scenario.10421.description":"Mientras buscan a Grahdens en el Mar de Árboles de Marleg, Paris vuelve a invitar al Invocador a unirse a su causa. Pero Tilith acaba interrumpiendo.","storylog.scenario.10421.title":"¿El Invocador de quién?","storylog.scenario.10422.description":"Lugina reprende a Paris en la Ciénaga de la Lluvia Eterna. Sin embargo, justo antes de que las cosas empeoren, Seria se une a la fiesta y discute con Lugina.","storylog.scenario.10422.title":"Lugina y Seria","storylog.scenario.10423.description":"Al llegar al Cabo Narasta se confirma dónde está Grahdens, y Paris se pregunta por qué Lucius no derrota él mismo a los Cuatro Dioses Caídos.","storylog.scenario.10423.title":"Las dudas de Paris","storylog.scenario.10424.description":"Karl da las gracias a Tilith cuando ella revela más información sobre Grahdens en las Ruinas de Mirvana. Lugina y Seria, en cambio, siguen con sus riñas de siempre.","storylog.scenario.10424.title":"Nunca cambian","storylog.scenario.10425.description":"Todo el grupo ha llegado por fin a la Torre de los Dioses. ¿Lograrán derrotar a Zevalhua el Supremo y rescatar a Grahdens?","storylog.scenario.10425.title":"Zevalhua el Supremo","storylog.scenario.10426.description":"Grahdens aparece y revela el secreto del origen de Karl. Al mismo tiempo, Eriole aparece de repente e interrumpe para hablar con el anciano.","storylog.scenario.10426.title":"El secreto de su origen","storylog.scenario.20000.description":"Lin, de la Oficina de Exploración, pide al Invocador que investigue las Montañas de Egor. Dicen que allí duerme un demonio de hielo.","storylog.scenario.20000.title":"El demonio de la montaña","storylog.scenario.20001.description":"Lin habla del pasado de Skramya. Las leyendas dicen que un héroe selló al demonio después de que intentara destruir la nación que quería manipularlo.","storylog.scenario.20001.title":"El pasado del demonio","storylog.scenario.20002.description":"Lin pide al Invocador que explore la Caverna de Ignia. Parece que allí ha despertado un demonio tras los terremotos de Cordelica...","storylog.scenario.20002.title":"Pegajoso y viscoso","storylog.scenario.20003.description":"El Invocador derrota al demonio gigantesco e incontrolable. Lin colma de elogios al Invocador, pero de pronto su actitud cambia por completo...","storylog.scenario.20003.title":"Lo que Lin detesta","storylog.scenario.20004.description":"Lin transmite al Invocador información según la cual el Nido de Valmodora alberga un demonio. Espera que el Invocador reúna más detalles.","storylog.scenario.20004.title":"Demonio gigantesco","storylog.scenario.20005.description":"El Invocador derrota a Valmodora mientras explora el lugar. Parece que las ruinas albergaban algo realmente gigantesco.","storylog.scenario.20005.title":"Ruinas misteriosas","storylog.scenario.20006.description":"El Invocador siente un poder tremendo que emana del fondo del Lago Subterráneo de Golzo. Lin tiene un mal presentimiento, pero pide una exploración.","storylog.scenario.20006.title":"El mal presentimiento de Lin","storylog.scenario.20007.description":"Lagzal, que yacía latente bajo tierra, era un dios que buscaba destruir a los humanos. Parece que Lin estaba muy preocupada por el Invocador durante la expedición.","storylog.scenario.20007.title":"El Dios Caído Lagzal","storylog.scenario.20008.description":"Al atravesar la Mazmorra de Agni, Lin le pide al Invocador que someta a cierto \\"ser maligno\\" encerrado en su interior.","storylog.scenario.20008.title":"Oculto en la mazmorra","storylog.scenario.20009.description":"Según Lin, lo que estaba encerrado era el fantasma de un temido tirano al que sellaron sus propios vasallos.","storylog.scenario.20009.title":"El fin de un tirano"}')}]);